-- =============================================================================
-- CourtKo — Reference PostgreSQL 16 schema (companion to docs/design/12-database-erd.md)
--
-- Reference schema — not yet executed against a live database; validate in CI with a PostGIS container before use.
--
-- Scope      : production data model for the multi-tenant court booking marketplace.
-- Target     : PostgreSQL 16 (Amazon RDS for PostgreSQL, Multi-AZ) with postgis, btree_gist, pg_trgm, citext, pgcrypto.
-- Conventions: see doc 12 §2. Summary:
--   * IDs              uuid (UUIDv7, generated by the application; app.uuidv7() is the SQL fallback default).
--   * Money            bigint minor units (centavos) in columns suffixed _minor, plus currency char(3) (ISO 4217).
--   * Rates            integer parts-per-million in columns suffixed _ppm (5% = 50000).
--   * Time             timestamptz (UTC) for instants; date/time + venue IANA timezone for local wall-clock rules.
--   * Statuses         PostgreSQL enums for code-owned state machines; lookup tables for data-managed catalogs.
--   * Tenancy          business_id on every tenant-owned row; RLS ENABLED + FORCED; app connects as a non-owner role.
--   * Append-only      audit.audit_logs, audit.security_events, app.financial_ledger_entries, app.ledger_journals,
--                      app.payment_events, app.inventory_movements, app.booking_price_snapshots, app.booking_status_history.
--
-- Layout of this file:
--   0. Bootstrap (run once by the RDS master user): roles, schemas, extensions
--   1. Helper functions (UUIDv7, RLS session context, generic triggers)
--   2. Enum types
--   3. Tables by domain (identity; tenancy & RBAC; platform config & reference; venues & courts; policies & pricing;
--      availability & booking; checkout; payments, ledger & settlement; events; products & orders; trust & safety;
--      notifications & support; privacy & files; platform ops & audit)
--   4. Triggers (updated_at, append-only, ledger balance, booking slot invariant)
--   5. Row-Level Security
--   6. Privileged helper functions (SECURITY DEFINER, owned by app_definer)
--   7. Reporting views
--   8. Grants
--
-- Session context contract (set by packages/db at the start of EVERY transaction, never per connection):
--   SET LOCAL app.scope       = 'public' | 'player' | 'business' | 'platform' | 'system';
--   SET LOCAL app.business_id = '<uuid>'   -- business scope only
--   SET LOCAL app.user_id     = '<uuid>'   -- authenticated actor (player, staff or platform user)
-- Unset or invalid context => app.app_scope() returns 'none' => every tenant policy evaluates to false (fail closed).
-- =============================================================================

BEGIN;

-- -----------------------------------------------------------------------------
-- 0. Bootstrap — roles, schemas, extensions
-- -----------------------------------------------------------------------------
-- Role model (doc 10 §4):
--   courtko_migrator  LOGIN   owns every schema object; used only by the migration job in CI/CD.
--   app_rw            NOLOGIN privilege group for runtime roles (no ownership, NOBYPASSRLS).
--   app_api           LOGIN   member of app_rw; used by apps/api (Fastify).
--   app_worker        LOGIN   member of app_rw; used by apps/worker; the only runtime role allowed app.scope='system'.
--   app_definer       NOLOGIN owns vetted SECURITY DEFINER functions; RLS policies grant it narrowly (section 6).
--   app_reporting     LOGIN   read-only; connects to the reporting read replica.
-- Credentials: IAM database authentication or Secrets Manager rotation (no passwords in this file).
DO $bootstrap$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'courtko_migrator') THEN
    CREATE ROLE courtko_migrator LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_rw') THEN
    CREATE ROLE app_rw NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_api') THEN
    CREATE ROLE app_api LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS IN ROLE app_rw;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_worker') THEN
    CREATE ROLE app_worker LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS IN ROLE app_rw;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_definer') THEN
    CREATE ROLE app_definer NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_reporting') THEN
    CREATE ROLE app_reporting LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
  END IF;
END
$bootstrap$;

-- The bootstrap user must be able to create objects owned by the migrator.
GRANT courtko_migrator TO CURRENT_USER;
GRANT app_definer TO courtko_migrator;   -- lets the migrator create functions owned by app_definer

CREATE SCHEMA IF NOT EXISTS extensions AUTHORIZATION courtko_migrator;
CREATE SCHEMA IF NOT EXISTS app        AUTHORIZATION courtko_migrator;
CREATE SCHEMA IF NOT EXISTS audit      AUTHORIZATION courtko_migrator;
CREATE SCHEMA IF NOT EXISTS reporting  AUTHORIZATION courtko_migrator;

REVOKE ALL ON SCHEMA public FROM PUBLIC;

-- Extensions are installed in a dedicated schema (never in app/audit). postgis requires rds_superuser on RDS.
CREATE EXTENSION IF NOT EXISTS postgis    WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pg_trgm    WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS citext     WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto   WITH SCHEMA extensions;

ALTER ROLE app_api       SET search_path = app, audit, extensions;
ALTER ROLE app_worker    SET search_path = app, audit, extensions;
ALTER ROLE app_reporting SET search_path = reporting, app, audit, extensions;
ALTER ROLE app_api       SET statement_timeout = '5s';
ALTER ROLE app_api       SET idle_in_transaction_session_timeout = '10s';
ALTER ROLE app_worker    SET statement_timeout = '60s';
ALTER ROLE app_reporting SET statement_timeout = '120s';
ALTER ROLE app_reporting SET default_transaction_read_only = on;

-- Everything below is owned by the migrator.
SET ROLE courtko_migrator;
SET LOCAL search_path = app, audit, extensions;

-- -----------------------------------------------------------------------------
-- 1. Helper functions
-- -----------------------------------------------------------------------------

-- UUIDv7 (RFC 9562): 48-bit Unix epoch milliseconds + version 7 + random bits. The application normally generates
-- the id (packages/db); this default guarantees time-ordered keys for rows inserted by SQL (migrations, jobs).
CREATE OR REPLACE FUNCTION app.uuidv7() RETURNS uuid
LANGUAGE sql VOLATILE PARALLEL SAFE
AS $fn$
  SELECT encode(
           set_bit(
             set_bit(
               overlay(uuid_send(gen_random_uuid())
                       PLACING substring(int8send(floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint) FROM 3)
                       FROM 1 FOR 6),
               52, 1),
             53, 1),
           'hex')::uuid
$fn$;

-- RLS session context. Policies call these through scalar sub-selects, e.g. (SELECT app.app_scope()),
-- so the planner evaluates them once per statement (InitPlan) instead of once per row.
CREATE OR REPLACE FUNCTION app.app_scope() RETURNS text
LANGUAGE plpgsql STABLE PARALLEL SAFE
SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
  s text := nullif(current_setting('app.scope', true), '');
BEGIN
  IF s IS NULL OR s NOT IN ('public', 'player', 'business', 'platform', 'system') THEN
    RETURN 'none';
  END IF;
  -- 'system' (cross-tenant jobs) is honoured only for the worker and migrator LOGIN roles. session_user (not
  -- current_user) is checked so the rule also holds inside SECURITY DEFINER functions.
  IF s = 'system' AND session_user NOT IN ('app_worker', 'courtko_migrator') THEN
    RETURN 'none';
  END IF;
  -- 'business' without a business id is invalid.
  IF s = 'business' AND nullif(current_setting('app.business_id', true), '') IS NULL THEN
    RETURN 'none';
  END IF;
  RETURN s;
END
$fn$;

CREATE OR REPLACE FUNCTION app.app_current_business_id() RETURNS uuid
LANGUAGE sql STABLE PARALLEL SAFE
SET search_path = pg_catalog, pg_temp
AS $fn$
  SELECT nullif(current_setting('app.business_id', true), '')::uuid
$fn$;

CREATE OR REPLACE FUNCTION app.app_current_user_id() RETURNS uuid
LANGUAGE sql STABLE PARALLEL SAFE
SET search_path = pg_catalog, pg_temp
AS $fn$
  SELECT nullif(current_setting('app.user_id', true), '')::uuid
$fn$;

-- Generic trigger: maintain updated_at.
CREATE OR REPLACE FUNCTION app.tg_set_updated_at() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $fn$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END
$fn$;

-- Generic trigger: block UPDATE / DELETE / TRUNCATE on append-only tables (defence in depth on top of grants).
CREATE OR REPLACE FUNCTION app.tg_forbid_mutation() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $fn$
BEGIN
  RAISE EXCEPTION 'table %.% is append-only: % is not permitted', TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'insufficient_privilege',
          HINT = 'Post a reversing/compensating record instead.';
  RETURN NULL;
END
$fn$;

-- Monthly range-partition helper for audit tables (idempotent). Called by migrations and by the
-- audit.archive job, which pre-creates the next 3 months and detaches partitions past retention.
CREATE OR REPLACE FUNCTION audit.ensure_monthly_partitions(p_parent regclass, p_from date, p_months int)
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
  i int;
  v_start date;
  v_end date;
  v_schema text;
  v_table text;
  v_name text;
BEGIN
  SELECT n.nspname, c.relname INTO v_schema, v_table
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
   WHERE c.oid = p_parent;
  FOR i IN 0 .. p_months - 1 LOOP
    v_start := (date_trunc('month', p_from) + make_interval(months => i))::date;
    v_end   := (v_start + interval '1 month')::date;
    v_name  := format('%s_%s', v_table, to_char(v_start, 'YYYYMM'));
    IF to_regclass(format('%I.%I', v_schema, v_name)) IS NULL THEN
      -- Partition bounds are UTC month boundaries regardless of the session TimeZone.
      EXECUTE format('CREATE TABLE %I.%I PARTITION OF %s FOR VALUES FROM (%L) TO (%L)',
                     v_schema, v_name, p_parent,
                     (v_start::timestamp AT TIME ZONE 'UTC'), (v_end::timestamp AT TIME ZONE 'UTC'));
      -- Partitions carry no policies: with RLS enabled + forced, direct partition access is denied to everyone;
      -- all access goes through the parent table (whose policies apply). Runtime roles are never granted partitions.
      EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', v_schema, v_name);
      EXECUTE format('ALTER TABLE %I.%I FORCE ROW LEVEL SECURITY', v_schema, v_name);
    END IF;
  END LOOP;
END
$fn$;

-- -----------------------------------------------------------------------------
-- 2. Enum types (code-owned state machines and closed catalogs; see doc 12 §2.5 for the enum strategy)
--    Evolution rule: ALTER TYPE ... ADD VALUE only (expand). Never rename/remove in place; a removal is a
--    contract-phase migration that swaps the column to a new type after the value is no longer written.
-- -----------------------------------------------------------------------------

-- Booking (doc 07)
CREATE TYPE app.booking_status AS ENUM (
  'draft', 'slot_held', 'payment_pending', 'confirmed', 'checked_in', 'completed', 'cancelled',
  'refund_pending', 'partially_refunded', 'refunded', 'no_show', 'disputed', 'failed', 'expired');
CREATE TYPE app.booking_source        AS ENUM ('player_app', 'walk_in', 'platform_admin');
CREATE TYPE app.hold_status           AS ENUM ('active', 'converted', 'released', 'expired');
CREATE TYPE app.slot_status           AS ENUM ('active', 'released');
CREATE TYPE app.slot_occupant_type    AS ENUM ('booking', 'court_block', 'event');
CREATE TYPE app.slot_release_reason   AS ENUM (
  'hold_expired', 'checkout_abandoned', 'payment_failed', 'cancelled', 'rescheduled', 'refunded_before_play',
  'block_removed', 'event_cancelled', 'restriction_unfulfillable', 'system_correction');
CREATE TYPE app.checkout_status       AS ENUM ('open', 'payment_pending', 'paid', 'expired', 'cancelled', 'failed');
CREATE TYPE app.checkout_item_type    AS ENUM ('court_booking', 'product', 'event_registration');
CREATE TYPE app.court_block_type      AS ENUM ('maintenance', 'closure', 'private_use', 'weather', 'other');

-- Payments (doc 08)
CREATE TYPE app.payment_status AS ENUM (
  'created', 'pending', 'authorized', 'captured', 'failed', 'expired', 'cancelled',
  'partially_refunded', 'refunded', 'disputed', 'chargeback');
CREATE TYPE app.payment_event_source  AS ENUM ('api', 'webhook', 'provider_query', 'reconciliation', 'system', 'admin');
CREATE TYPE app.provider_code         AS ENUM ('xendit', 'mock');
CREATE TYPE app.fee_bearer            AS ENUM ('customer', 'platform', 'venue');
CREATE TYPE app.settlement_model      AS ENUM ('provider_split', 'platform_payout');
CREATE TYPE app.provider_account_type AS ENUM ('managed', 'owned');   -- xenPlatform MANAGED / OWNED (decision pending, doc 23)
CREATE TYPE app.provider_account_status AS ENUM ('pending', 'active', 'suspended', 'closed');

-- Refunds, payouts, disputes, settlement (doc 09)
CREATE TYPE app.refund_status  AS ENUM ('requested', 'pending_approval', 'approved', 'processing', 'succeeded', 'failed', 'rejected');
CREATE TYPE app.refund_trigger AS ENUM (
  'player_cancellation', 'venue_cancellation', 'court_unavailable', 'weather', 'system_failure',
  'event_cancellation', 'product_cancellation', 'goodwill', 'restriction_unfulfillable',
  'late_payment_unfulfillable', 'duplicate_payment', 'reschedule_difference');
CREATE TYPE app.refund_destination    AS ENUM ('original_method', 'provider_payout_link', 'platform_credit');
-- provider_payout_link: fallback when the original method cannot be refunded (customer enters a destination on a
-- provider-hosted page; CourtKo never stores it). platform_credit: only where legally/contractually allowed (off).
CREATE TYPE app.payout_status         AS ENUM ('scheduled', 'processing', 'paid', 'failed', 'reversed');
CREATE TYPE app.payout_kind           AS ENUM ('sub_account_withdrawal', 'platform_payout');   -- money leaving the provider to a venue bank
CREATE TYPE app.dispute_status        AS ENUM ('open', 'evidence_submitted', 'won', 'lost');
CREATE TYPE app.liability_party       AS ENUM ('venue', 'platform', 'shared');
CREATE TYPE app.settlement_status     AS ENUM ('draft', 'finalized', 'paid', 'partially_paid', 'carried_forward', 'void');
CREATE TYPE app.commission_status     AS ENUM ('accrued', 'partially_reversed', 'reversed');
CREATE TYPE app.agreement_status      AS ENUM ('draft', 'pending_approval', 'approved', 'rejected', 'terminated');
CREATE TYPE app.payout_account_status AS ENUM ('pending_verification', 'verified', 'rejected', 'disabled');

-- Ledger (doc 09 §10)
CREATE TYPE app.ledger_direction    AS ENUM ('debit', 'credit');
CREATE TYPE app.ledger_account_type AS ENUM ('asset', 'liability', 'revenue', 'expense');
CREATE TYPE app.ledger_entry_type   AS ENUM (
  'customer_charge', 'booking_base', 'product_amount', 'event_amount', 'discount', 'tax', 'gateway_fee',
  'platform_commission', 'venue_payable', 'refund', 'partial_refund', 'chargeback', 'dispute_adjustment',
  'manual_adjustment', 'payout', 'failed_payout', 'reversed_payout');

-- Reconciliation (doc 08 §7)
CREATE TYPE app.recon_run_type        AS ENUM ('pending_sweep', 'daily_provider_report', 'payout_sync', 'refund_sync', 'manual');
CREATE TYPE app.recon_run_status      AS ENUM ('running', 'succeeded', 'failed');
CREATE TYPE app.recon_exception_class AS ENUM (
  'missing_internal', 'missing_provider', 'status_mismatch', 'amount_mismatch', 'currency_mismatch',
  'fee_variance', 'duplicate_capture', 'orphan_refund', 'split_failed', 'payout_mismatch', 'settlement_timing');
CREATE TYPE app.recon_exception_status AS ENUM ('open', 'auto_healed', 'resolved', 'accepted', 'escalated');

-- Tenancy, identity, RBAC (doc 10)
CREATE TYPE app.user_status          AS ENUM ('pending_verification', 'active', 'locked', 'suspended', 'pending_deletion', 'deleted');
CREATE TYPE app.business_status      AS ENUM ('draft', 'pending_verification', 'active', 'rejected', 'suspended');
CREATE TYPE app.venue_status         AS ENUM ('draft', 'published', 'unpublished', 'suspended');
CREATE TYPE app.court_status         AS ENUM ('active', 'inactive', 'archived');
CREATE TYPE app.verification_status  AS ENUM ('submitted', 'under_review', 'needs_more_info', 'approved', 'rejected');
CREATE TYPE app.role_scope           AS ENUM ('platform', 'business');
CREATE TYPE app.member_status        AS ENUM ('invited', 'active', 'suspended', 'removed');
CREATE TYPE app.permission_risk      AS ENUM ('low', 'medium', 'high', 'critical');
CREATE TYPE app.identity_provider    AS ENUM ('password', 'google', 'apple', 'facebook');
CREATE TYPE app.session_surface      AS ENUM ('web', 'business', 'admin', 'native');
CREATE TYPE app.mfa_factor_type      AS ENUM ('totp', 'webauthn');
CREATE TYPE app.token_purpose        AS ENUM ('email_verification', 'phone_verification', 'password_reset', 'email_change', 'staff_invitation', 'login_otp');
CREATE TYPE app.approval_status      AS ENUM ('pending', 'approved', 'rejected', 'expired', 'cancelled');
CREATE TYPE app.approval_action      AS ENUM (
  'commission_agreement', 'refund_exception', 'refund_after_payout', 'refund_high_value', 'manual_adjustment',
  'payout_account_change', 'fee_schedule_change', 'platform_setting_change', 'business_suspension');
CREATE TYPE app.support_session_status AS ENUM ('active', 'ended', 'expired', 'revoked');

-- Events, products (docs 04/08 of the package)
CREATE TYPE app.event_status              AS ENUM ('draft', 'published', 'registration_closed', 'in_progress', 'completed', 'cancelled');
CREATE TYPE app.event_visibility          AS ENUM ('public', 'unlisted', 'private');
CREATE TYPE app.event_registration_status AS ENUM (
  'held', 'pending_payment', 'confirmed', 'waitlisted', 'offered', 'checked_in', 'withdrawn', 'cancelled', 'refunded');
CREATE TYPE app.waitlist_status           AS ENUM ('waiting', 'offered', 'accepted', 'expired', 'removed');
CREATE TYPE app.match_status              AS ENUM ('scheduled', 'in_progress', 'completed', 'walkover', 'cancelled');
CREATE TYPE app.order_status AS ENUM (
  'pending_payment', 'paid', 'preparing', 'ready_for_pickup', 'claimed', 'cancelled', 'refunded', 'partially_refunded');
CREATE TYPE app.product_status          AS ENUM ('draft', 'active', 'inactive', 'archived');
CREATE TYPE app.inventory_movement_type AS ENUM ('receipt', 'reservation', 'reservation_release', 'sale', 'return', 'adjustment', 'write_off');
CREATE TYPE app.tax_treatment           AS ENUM ('vat_inclusive', 'vat_exclusive', 'vat_exempt', 'zero_rated', 'non_vat');
CREATE TYPE app.discount_type           AS ENUM ('percent', 'fixed');
CREATE TYPE app.discount_funder         AS ENUM ('venue', 'platform');
CREATE TYPE app.promotion_status        AS ENUM ('draft', 'active', 'paused', 'expired', 'archived');
CREATE TYPE app.redemption_status       AS ENUM ('reserved', 'redeemed', 'released');
CREATE TYPE app.pricing_rule_type       AS ENUM (
  'base', 'time_of_day', 'peak', 'off_peak', 'weekday', 'weekend', 'holiday', 'date_override', 'seasonal',
  'event', 'member', 'promotional', 'minimum_charge', 'temporary_override');
CREATE TYPE app.pricing_adjustment      AS ENUM ('set_hourly_rate', 'percent_delta', 'fixed_delta_per_hour', 'minimum_charge');
CREATE TYPE app.config_status           AS ENUM ('draft', 'active', 'archived');

-- Ratings (doc 07 of the product brief — label every source)
CREATE TYPE app.rating_source     AS ENUM ('self_declared', 'venue_verified', 'platform_recreational', 'external_provider');
CREATE TYPE app.visibility_level  AS ENUM ('private', 'connections', 'event_organizers', 'public');

-- Trust & safety
CREATE TYPE app.restriction_level           AS ENUM ('business', 'venue', 'platform');
CREATE TYPE app.restriction_status          AS ENUM ('active', 'lifted', 'expired');
CREATE TYPE app.appeal_status               AS ENUM ('none', 'submitted', 'upheld', 'overturned');
CREATE TYPE app.restriction_reason_category AS ENUM (
  'conduct', 'safety', 'repeated_no_show', 'non_payment', 'property_damage', 'fraud_suspected', 'policy_violation', 'other');
CREATE TYPE app.review_status        AS ENUM ('published', 'hidden', 'removed');
CREATE TYPE app.report_target_type   AS ENUM ('user', 'venue', 'event', 'product', 'review', 'business');
CREATE TYPE app.report_status        AS ENUM ('open', 'under_review', 'actioned', 'dismissed');

-- Notifications, support, privacy, files, ops
CREATE TYPE app.notification_channel  AS ENUM ('in_app', 'email', 'sms', 'push');
CREATE TYPE app.delivery_status       AS ENUM ('queued', 'sent', 'delivered', 'failed', 'suppressed');
CREATE TYPE app.support_case_status   AS ENUM ('open', 'pending_customer', 'pending_internal', 'resolved', 'closed');
CREATE TYPE app.dsr_type              AS ENUM ('access', 'export', 'correction', 'deletion', 'objection', 'consent_withdrawal');
CREATE TYPE app.dsr_status            AS ENUM ('received', 'identity_verification', 'in_progress', 'completed', 'rejected', 'extended');
CREATE TYPE app.upload_scan_status    AS ENUM ('pending', 'clean', 'infected', 'error');
CREATE TYPE app.upload_purpose        AS ENUM (
  'business_verification', 'venue_image', 'court_image', 'product_image', 'event_image', 'avatar',
  'restriction_evidence', 'dispute_evidence', 'report_export', 'support_attachment');
CREATE TYPE app.outbox_status         AS ENUM ('pending', 'dispatched', 'failed', 'dead');
CREATE TYPE app.webhook_status        AS ENUM ('received', 'processing', 'processed', 'ignored', 'failed');
CREATE TYPE app.idempotency_state     AS ENUM ('in_progress', 'completed');
CREATE TYPE app.ph_location_level     AS ENUM ('region', 'province', 'city', 'municipality', 'sub_municipality', 'barangay');
CREATE TYPE app.holiday_kind          AS ENUM ('regular', 'special_non_working', 'special_working', 'local', 'venue_closure');
CREATE TYPE app.retention_class       AS ENUM ('R1_session', 'R2_operational', 'R3_account', 'R4_financial', 'R5_audit', 'R6_legal_hold');

-- =============================================================================
-- 3. TABLES
-- Tables are declared in foreign-key dependency order; the domain of each table is given in its header comment
-- and matches the ERD sections in doc 12. "Tenant" = carries business_id and is RLS-protected.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 3.1 Platform reference data (non-tenant; readable by every scope; written only by platform scope)
-- -----------------------------------------------------------------------------

-- Philippine Standard Geographic Code (PSA PSGC) hierarchy used for manual search by region/province/city/barangay.
CREATE TABLE app.ph_locations (
  psgc_code         text PRIMARY KEY CHECK (psgc_code ~ '^[0-9]{9,10}$'),
  name              text NOT NULL,
  level             app.ph_location_level NOT NULL,
  parent_psgc_code  text REFERENCES app.ph_locations (psgc_code),
  region_code       text,
  province_code     text,
  city_code         text,
  centroid          geography(Point, 4326),
  psgc_release      text NOT NULL,                       -- e.g. '2025Q2' (PSA publication the row came from)
  is_active         boolean NOT NULL DEFAULT true,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ph_locations_parent_idx   ON app.ph_locations (parent_psgc_code);
CREATE INDEX ph_locations_name_trgm    ON app.ph_locations USING gin (name extensions.gin_trgm_ops);
CREATE INDEX ph_locations_centroid_gix ON app.ph_locations USING gist (centroid);

CREATE TABLE app.amenities (
  code        text PRIMARY KEY CHECK (code ~ '^[a-z0-9_]{2,40}$'),
  label       text NOT NULL,
  category    text NOT NULL DEFAULT 'general',            -- general | accessibility | parking | food | equipment
  icon        text,
  is_active   boolean NOT NULL DEFAULT true,
  sort_order  integer NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE app.court_types (
  code        text PRIMARY KEY CHECK (code ~ '^[a-z0-9_]{2,40}$'),   -- full, half, custom ...
  label       text NOT NULL,
  description text,
  is_active   boolean NOT NULL DEFAULT true,
  sort_order  integer NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE app.event_types (
  code        text PRIMARY KEY CHECK (code ~ '^[a-z0-9_]{2,40}$'),   -- tournament, league, clinic, training, open_play, social, private
  label       text NOT NULL,
  is_active   boolean NOT NULL DEFAULT true,
  sort_order  integer NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE app.product_categories (
  code        text PRIMARY KEY CHECK (code ~ '^[a-z0-9_]{2,40}$'),   -- food, drinks, merchandise, balls, paddle_rental, equipment, services
  label       text NOT NULL,
  is_active   boolean NOT NULL DEFAULT true,
  sort_order  integer NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

-- Payment method catalog. Capabilities are PROVIDER-DEPENDENT and must be confirmed per channel with Xendit.
CREATE TABLE app.payment_method_types (
  code                       text PRIMARY KEY CHECK (code ~ '^[a-z0-9_]{2,40}$'),  -- qrph, gcash, maya, grabpay, shopeepay, card, bpi_direct_debit, ubp_direct_debit
  provider                   app.provider_code NOT NULL,
  provider_channel_code      text NOT NULL,              -- e.g. 'QRPH', 'GCASH', 'CARDS' (to be verified against current Xendit docs)
  display_name               text NOT NULL,
  is_enabled                 boolean NOT NULL DEFAULT false,
  supports_refund            boolean NOT NULL DEFAULT false,
  supports_partial_refund    boolean NOT NULL DEFAULT false,
  refund_window_days         integer CHECK (refund_window_days IS NULL OR refund_window_days > 0),
  refunds_return_provider_fee boolean NOT NULL DEFAULT false,   -- provider-dependent (e.g. QR partial refunds keep the fee)
  supports_tokenization      boolean NOT NULL DEFAULT false,
  fee_pass_through_allowed   boolean NOT NULL DEFAULT false,    -- cards: false until surcharging notice is confirmed
  sort_order                 integer NOT NULL DEFAULT 0,
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  UNIQUE (provider, provider_channel_code)
);

CREATE TABLE app.platform_settings (
  key          text PRIMARY KEY CHECK (key ~ '^[a-z0-9_.]{3,80}$'),   -- e.g. 'booking.hold_ttl_seconds'
  value        jsonb NOT NULL,
  description  text NOT NULL,
  is_sensitive boolean NOT NULL DEFAULT false,            -- never secrets: secrets live in AWS Secrets Manager
  version      integer NOT NULL DEFAULT 1,
  updated_by   uuid,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE app.feature_flags (
  key          text PRIMARY KEY CHECK (key ~ '^[a-z0-9_.]{3,80}$'),
  description  text NOT NULL,
  enabled      boolean NOT NULL DEFAULT false,
  rollout      jsonb NOT NULL DEFAULT '{}'::jsonb,        -- {"business_ids":[...], "user_ids":[...], "percent":0}
  version      integer NOT NULL DEFAULT 1,
  updated_by   uuid,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now()
);

-- -----------------------------------------------------------------------------
-- 3.2 Identity & access (global identity; not tenant-owned)
-- -----------------------------------------------------------------------------

CREATE TABLE app.users (
  id                  uuid PRIMARY KEY DEFAULT app.uuidv7(),
  email               extensions.citext UNIQUE,
  email_verified_at   timestamptz,
  phone_e164          text UNIQUE CHECK (phone_e164 IS NULL OR phone_e164 ~ '^\+[1-9][0-9]{7,14}$'),
  phone_verified_at   timestamptz,
  password_hash       text,                               -- Argon2id PHC string; NULL for identity-provider-only accounts
  password_changed_at timestamptz,
  status              app.user_status NOT NULL DEFAULT 'pending_verification',
  is_platform_staff   boolean NOT NULL DEFAULT false,
  mfa_enrolled        boolean NOT NULL DEFAULT false,
  locale              text NOT NULL DEFAULT 'en-PH',
  timezone            text NOT NULL DEFAULT 'Asia/Manila',
  failed_login_count  integer NOT NULL DEFAULT 0 CHECK (failed_login_count >= 0),
  locked_until        timestamptz,
  last_login_at       timestamptz,
  deletion_requested_at timestamptz,
  anonymized_at       timestamptz,                        -- set when PII is scrubbed after account deletion
  version             integer NOT NULL DEFAULT 1,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  deleted_at          timestamptz,
  CONSTRAINT users_contact_required CHECK (email IS NOT NULL OR phone_e164 IS NOT NULL OR anonymized_at IS NOT NULL),
  CONSTRAINT users_password_format  CHECK (password_hash IS NULL OR password_hash LIKE '$argon2id$%')
);
CREATE INDEX users_status_idx ON app.users (status) WHERE deleted_at IS NULL;

CREATE TABLE app.uploads (
  id                uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id       uuid,                                  -- NULL for player/platform uploads; FK added after businesses
  uploaded_by       uuid NOT NULL REFERENCES app.users (id),
  purpose           app.upload_purpose NOT NULL,
  s3_bucket         text NOT NULL,                         -- uploads-quarantine until clean, then uploads-clean
  s3_key            text NOT NULL,                         -- tenant prefix: t/{business_id}/... or u/{user_id}/... or p/...
  content_type      text NOT NULL CHECK (content_type IN ('image/jpeg', 'image/png', 'image/webp', 'application/pdf', 'text/csv')),
  byte_size         bigint NOT NULL CHECK (byte_size > 0 AND byte_size <= 20971520),   -- 20 MiB hard cap
  sha256_hex        text NOT NULL CHECK (sha256_hex ~ '^[0-9a-f]{64}$'),
  scan_status       app.upload_scan_status NOT NULL DEFAULT 'pending',
  scanned_at        timestamptz,
  scan_result       text,
  variants          jsonb NOT NULL DEFAULT '{}'::jsonb,    -- processed image renditions (images.process)
  retention_class   app.retention_class NOT NULL DEFAULT 'R2_operational',
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  deleted_at        timestamptz,
  UNIQUE (s3_bucket, s3_key)
);
CREATE INDEX uploads_business_idx ON app.uploads (business_id, created_at DESC);
CREATE INDEX uploads_pending_scan_idx ON app.uploads (created_at) WHERE scan_status = 'pending';

CREATE TABLE app.user_profiles (
  user_id              uuid PRIMARY KEY REFERENCES app.users (id) ON DELETE CASCADE,
  display_name         text NOT NULL CHECK (length(display_name) BETWEEN 1 AND 60),
  given_name           text,
  family_name          text,
  avatar_upload_id     uuid REFERENCES app.uploads (id),
  self_declared_level  text CHECK (self_declared_level IS NULL OR self_declared_level ~ '^[1-7](\.[05])?$'),
  home_psgc_code       text REFERENCES app.ph_locations (psgc_code),
  profile_visibility   app.visibility_level NOT NULL DEFAULT 'private',
  activity_visibility  app.visibility_level NOT NULL DEFAULT 'private',
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE app.user_addresses (
  id                 uuid PRIMARY KEY DEFAULT app.uuidv7(),
  user_id            uuid NOT NULL REFERENCES app.users (id) ON DELETE CASCADE,
  label              text NOT NULL DEFAULT 'billing',
  line1              text NOT NULL,
  line2              text,
  barangay_psgc_code text REFERENCES app.ph_locations (psgc_code),
  city_psgc_code     text REFERENCES app.ph_locations (psgc_code),
  province_psgc_code text REFERENCES app.ph_locations (psgc_code),
  postal_code        text CHECK (postal_code IS NULL OR postal_code ~ '^[0-9]{4}$'),
  country_code       char(2) NOT NULL DEFAULT 'PH',
  is_default_billing boolean NOT NULL DEFAULT false,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  deleted_at         timestamptz
);
CREATE INDEX user_addresses_user_idx ON app.user_addresses (user_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX user_addresses_one_default ON app.user_addresses (user_id) WHERE is_default_billing AND deleted_at IS NULL;

CREATE TABLE app.user_preferences (
  user_id                   uuid PRIMARY KEY REFERENCES app.users (id) ON DELETE CASCADE,
  location_permission       text NOT NULL DEFAULT 'unknown' CHECK (location_permission IN ('unknown', 'granted', 'denied', 'revoked')),
  default_search_psgc_code  text REFERENCES app.ph_locations (psgc_code),
  marketing_opt_in          boolean NOT NULL DEFAULT false,
  cookie_preferences        jsonb NOT NULL DEFAULT '{"analytics": false, "marketing": false}'::jsonb,
  language                  text NOT NULL DEFAULT 'en-PH',
  distance_unit             text NOT NULL DEFAULT 'km' CHECK (distance_unit IN ('km')),
  created_at                timestamptz NOT NULL DEFAULT now(),
  updated_at                timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE app.identities (
  id                uuid PRIMARY KEY DEFAULT app.uuidv7(),
  user_id           uuid NOT NULL REFERENCES app.users (id) ON DELETE CASCADE,
  provider          app.identity_provider NOT NULL CHECK (provider <> 'password'),
  provider_subject  text NOT NULL,                        -- OIDC 'sub'
  email             extensions.citext,
  email_verified    boolean NOT NULL DEFAULT false,
  linked_at         timestamptz NOT NULL DEFAULT now(),
  last_used_at      timestamptz,
  UNIQUE (provider, provider_subject)
);
CREATE INDEX identities_user_idx ON app.identities (user_id);

-- Support-mode (impersonation) sessions; referenced by sessions and audit rows.
CREATE TABLE app.support_sessions (
  id                 uuid PRIMARY KEY DEFAULT app.uuidv7(),
  admin_user_id      uuid NOT NULL REFERENCES app.users (id),
  subject_user_id    uuid NOT NULL REFERENCES app.users (id),
  subject_business_id uuid,                               -- when impersonating a staff member inside a business (FK below)
  reason             text NOT NULL CHECK (length(reason) >= 15),
  ticket_reference   text NOT NULL CHECK (length(ticket_reference) BETWEEN 3 AND 64),
  read_only          boolean NOT NULL DEFAULT true,
  status             app.support_session_status NOT NULL DEFAULT 'active',
  started_at         timestamptz NOT NULL DEFAULT now(),
  expires_at         timestamptz NOT NULL,
  ended_at           timestamptz,
  ended_by           uuid REFERENCES app.users (id),
  request_count      integer NOT NULL DEFAULT 0,
  CONSTRAINT support_sessions_max_30_min CHECK (expires_at <= started_at + interval '30 minutes'),
  CONSTRAINT support_sessions_not_self   CHECK (admin_user_id <> subject_user_id)
);
CREATE UNIQUE INDEX support_sessions_one_active_per_admin ON app.support_sessions (admin_user_id) WHERE status = 'active';

CREATE TABLE app.sessions (
  id                    uuid PRIMARY KEY DEFAULT app.uuidv7(),
  user_id               uuid NOT NULL REFERENCES app.users (id) ON DELETE CASCADE,
  surface               app.session_surface NOT NULL,
  token_hash            bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),   -- SHA-256 of the opaque 256-bit token
  refresh_family_id     uuid,                             -- native apps only: rotation family for reuse detection
  refresh_token_hash    bytea UNIQUE CHECK (refresh_token_hash IS NULL OR octet_length(refresh_token_hash) = 32),
  remember_me           boolean NOT NULL DEFAULT false,
  mfa_verified_at       timestamptz,
  support_session_id    uuid REFERENCES app.support_sessions (id),
  ip                    inet,
  user_agent            text,
  device_label          text,
  created_at            timestamptz NOT NULL DEFAULT now(),
  last_seen_at          timestamptz NOT NULL DEFAULT now(),
  idle_expires_at       timestamptz NOT NULL,
  absolute_expires_at   timestamptz NOT NULL,
  revoked_at            timestamptz,
  revoke_reason         text CHECK (revoke_reason IS NULL OR revoke_reason IN
                          ('logout', 'logout_all', 'password_change', 'admin_revoke', 'refresh_reuse_detected', 'mfa_reset', 'account_suspended')),
  CONSTRAINT sessions_expiry_order CHECK (idle_expires_at <= absolute_expires_at)
);
CREATE INDEX sessions_user_active_idx ON app.sessions (user_id) WHERE revoked_at IS NULL;
CREATE INDEX sessions_expiry_idx ON app.sessions (absolute_expires_at);

CREATE TABLE app.mfa_factors (
  id                 uuid PRIMARY KEY DEFAULT app.uuidv7(),
  user_id            uuid NOT NULL REFERENCES app.users (id) ON DELETE CASCADE,
  factor_type        app.mfa_factor_type NOT NULL DEFAULT 'totp',
  label              text NOT NULL DEFAULT 'Authenticator app',
  secret_ciphertext  bytea NOT NULL,                      -- envelope-encrypted (KMS data key); never logged
  secret_key_ref     text NOT NULL,                       -- KMS key id / data-key version
  last_used_step     bigint,                              -- TOTP time-step replay protection
  confirmed_at       timestamptz,
  disabled_at        timestamptz,
  created_at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX mfa_factors_user_idx ON app.mfa_factors (user_id) WHERE disabled_at IS NULL;

CREATE TABLE app.mfa_recovery_codes (
  id          uuid PRIMARY KEY DEFAULT app.uuidv7(),
  user_id     uuid NOT NULL REFERENCES app.users (id) ON DELETE CASCADE,
  code_hash   text NOT NULL,                              -- Argon2id PHC string of a one-time code
  used_at     timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX mfa_recovery_codes_user_idx ON app.mfa_recovery_codes (user_id) WHERE used_at IS NULL;

CREATE TABLE app.verification_tokens (
  id            uuid PRIMARY KEY DEFAULT app.uuidv7(),
  user_id       uuid REFERENCES app.users (id) ON DELETE CASCADE,
  purpose       app.token_purpose NOT NULL,
  token_hash    bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
  target        text NOT NULL,                            -- email or E.164 phone the token was sent to
  business_id   uuid,                                     -- staff invitations only (FK below)
  attempts      integer NOT NULL DEFAULT 0 CHECK (attempts BETWEEN 0 AND 10),
  expires_at    timestamptz NOT NULL,
  consumed_at   timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX verification_tokens_user_idx ON app.verification_tokens (user_id, purpose) WHERE consumed_at IS NULL;

-- -----------------------------------------------------------------------------
-- 3.3 Tenancy & RBAC
-- -----------------------------------------------------------------------------

CREATE TABLE app.businesses (
  id                        uuid PRIMARY KEY DEFAULT app.uuidv7(),
  legal_name                text NOT NULL,
  display_name              text NOT NULL,
  slug                      extensions.citext NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  status                    app.business_status NOT NULL DEFAULT 'draft',
  owner_user_id             uuid NOT NULL REFERENCES app.users (id),
  entity_type               text NOT NULL CHECK (entity_type IN ('sole_proprietorship', 'partnership', 'corporation', 'cooperative', 'other')),
  registration_number       text,                         -- DTI / SEC / CDA registration
  tin_ciphertext            bytea,                        -- BIR TIN, envelope-encrypted
  tin_last4                 char(4),
  vat_registered            boolean NOT NULL DEFAULT false,
  prices_include_vat        boolean NOT NULL DEFAULT true,
  withholding_applicable    boolean NOT NULL DEFAULT false,  -- RR 16-2023 (confirm with tax counsel)
  withholding_exempt_until  date,                         -- e.g. sworn declaration below the PHP 500,000 threshold
  settlement_model          app.settlement_model NOT NULL DEFAULT 'provider_split',
  default_gateway_fee_bearer app.fee_bearer NOT NULL DEFAULT 'platform' CHECK (default_gateway_fee_bearer <> 'customer'),
  default_timezone          text NOT NULL DEFAULT 'Asia/Manila',
  support_email             extensions.citext,
  support_phone_e164        text CHECK (support_phone_e164 IS NULL OR support_phone_e164 ~ '^\+[1-9][0-9]{7,14}$'),
  approved_at               timestamptz,
  approved_by               uuid REFERENCES app.users (id),
  rejection_reason          text,
  suspended_at              timestamptz,
  suspension_reason         text,
  suspension_booking_policy text CHECK (suspension_booking_policy IS NULL OR suspension_booking_policy IN ('honor_existing', 'cancel_and_refund')),
  offboarding_started_at    timestamptz,
  offboarded_at             timestamptz,
  version                   integer NOT NULL DEFAULT 1,
  created_at                timestamptz NOT NULL DEFAULT now(),
  updated_at                timestamptz NOT NULL DEFAULT now(),
  deleted_at                timestamptz,
  CONSTRAINT businesses_active_requires_approval CHECK (status <> 'active' OR approved_at IS NOT NULL),
  CONSTRAINT businesses_suspended_requires_reason CHECK (status <> 'suspended' OR suspension_reason IS NOT NULL)
);
CREATE INDEX businesses_status_idx ON app.businesses (status);
CREATE INDEX businesses_owner_idx ON app.businesses (owner_user_id);
CREATE INDEX businesses_name_trgm ON app.businesses USING gin (display_name extensions.gin_trgm_ops);

ALTER TABLE app.uploads             ADD CONSTRAINT uploads_business_fk             FOREIGN KEY (business_id) REFERENCES app.businesses (id);
ALTER TABLE app.support_sessions    ADD CONSTRAINT support_sessions_business_fk    FOREIGN KEY (subject_business_id) REFERENCES app.businesses (id);
ALTER TABLE app.verification_tokens ADD CONSTRAINT verification_tokens_business_fk FOREIGN KEY (business_id) REFERENCES app.businesses (id);

CREATE TABLE app.business_verifications (
  id               uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id      uuid NOT NULL REFERENCES app.businesses (id),
  status           app.verification_status NOT NULL DEFAULT 'submitted',
  documents        jsonb NOT NULL DEFAULT '[]'::jsonb,   -- [{"type":"dti_certificate","upload_id":"..."}]; files in uploads
  submitted_by     uuid NOT NULL REFERENCES app.users (id),
  submitted_at     timestamptz NOT NULL DEFAULT now(),
  reviewed_by      uuid REFERENCES app.users (id),
  reviewed_at      timestamptz,
  decision_reason  text,
  checklist        jsonb NOT NULL DEFAULT '{}'::jsonb,   -- ITA (RA 11967) merchant-verification checklist results
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT business_verifications_review_consistency CHECK (
    (status IN ('approved', 'rejected', 'needs_more_info')) = (reviewed_at IS NOT NULL AND reviewed_by IS NOT NULL)),
  CONSTRAINT business_verifications_four_eyes CHECK (reviewed_by IS NULL OR reviewed_by <> submitted_by)
);
CREATE INDEX business_verifications_business_idx ON app.business_verifications (business_id, submitted_at DESC);
CREATE INDEX business_verifications_queue_idx ON app.business_verifications (submitted_at) WHERE status IN ('submitted', 'under_review');

CREATE TABLE app.permissions (
  code          text PRIMARY KEY CHECK (code ~ '^[a-z_]+(\.[a-z_]+)+$'),   -- e.g. 'bookings.cancel', 'platform.refunds.approve'
  scope         app.role_scope NOT NULL,
  description   text NOT NULL,
  risk          app.permission_risk NOT NULL,
  requires_mfa  boolean NOT NULL DEFAULT false,
  created_at    timestamptz NOT NULL DEFAULT now()
);

-- System templates: business_id NULL (scope 'business' templates are copied into each business at onboarding).
-- Custom roles: business_id set, is_system = false.
CREATE TABLE app.roles (
  id           uuid PRIMARY KEY DEFAULT app.uuidv7(),
  scope        app.role_scope NOT NULL,
  business_id  uuid REFERENCES app.businesses (id),
  code         text NOT NULL CHECK (code ~ '^[a-z0-9_]{2,40}$'),     -- superadmin, platform_finance, business_owner, receptionist, ...
  name         text NOT NULL,
  description  text,
  is_system    boolean NOT NULL DEFAULT false,
  version      integer NOT NULL DEFAULT 1,
  created_by   uuid REFERENCES app.users (id),
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  deleted_at   timestamptz,
  CONSTRAINT roles_platform_has_no_business CHECK (scope = 'business' OR business_id IS NULL)
);
CREATE UNIQUE INDEX roles_code_uniq ON app.roles (scope, coalesce(business_id, '00000000-0000-0000-0000-000000000000'::uuid), code)
  WHERE deleted_at IS NULL;
CREATE INDEX roles_business_idx ON app.roles (business_id) WHERE business_id IS NOT NULL;

CREATE TABLE app.role_permissions (
  role_id          uuid NOT NULL REFERENCES app.roles (id) ON DELETE CASCADE,
  permission_code  text NOT NULL REFERENCES app.permissions (code),
  business_id      uuid REFERENCES app.businesses (id),   -- denormalized from roles for RLS (NULL for templates/platform roles)
  granted_by       uuid REFERENCES app.users (id),
  created_at       timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (role_id, permission_code)
);
CREATE INDEX role_permissions_business_idx ON app.role_permissions (business_id) WHERE business_id IS NOT NULL;

-- Platform staff role assignments (superadmin, platform_support, platform_finance, platform_trust_safety, platform_compliance).
CREATE TABLE app.platform_member_roles (
  user_id     uuid NOT NULL REFERENCES app.users (id),
  role_id     uuid NOT NULL REFERENCES app.roles (id),
  granted_by  uuid NOT NULL REFERENCES app.users (id),
  granted_at  timestamptz NOT NULL DEFAULT now(),
  expires_at  timestamptz,
  PRIMARY KEY (user_id, role_id),
  CONSTRAINT platform_member_roles_no_self_grant CHECK (granted_by <> user_id)
);

-- -----------------------------------------------------------------------------
-- 3.4 Venues & courts (tenant)
-- -----------------------------------------------------------------------------

CREATE TABLE app.venues (
  id                      uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id             uuid NOT NULL REFERENCES app.businesses (id),
  name                    text NOT NULL,
  slug                    extensions.citext NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  status                  app.venue_status NOT NULL DEFAULT 'draft',
  description             text,
  address_line1           text NOT NULL,
  address_line2           text,
  landmark                text,
  barangay_psgc_code      text REFERENCES app.ph_locations (psgc_code),
  city_psgc_code          text NOT NULL REFERENCES app.ph_locations (psgc_code),
  province_psgc_code      text REFERENCES app.ph_locations (psgc_code),
  region_psgc_code        text REFERENCES app.ph_locations (psgc_code),
  postal_code             text CHECK (postal_code IS NULL OR postal_code ~ '^[0-9]{4}$'),
  location                geography(Point, 4326),          -- required before publishing
  timezone                text NOT NULL DEFAULT 'Asia/Manila',  -- IANA name
  contact_phone_e164      text CHECK (contact_phone_e164 IS NULL OR contact_phone_e164 ~ '^\+[1-9][0-9]{7,14}$'),
  contact_email           extensions.citext,
  rules_md                text,
  parking_info            text,
  accessibility_info      text,
  cover_upload_id         uuid REFERENCES app.uploads (id),
  logo_upload_id          uuid REFERENCES app.uploads (id),
  -- booking settings
  min_booking_minutes     integer NOT NULL DEFAULT 60,
  max_booking_minutes     integer NOT NULL DEFAULT 180,
  slot_increment_minutes  integer NOT NULL DEFAULT 60 CHECK (slot_increment_minutes IN (30, 60, 90)),
  advance_booking_days    integer NOT NULL DEFAULT 30 CHECK (advance_booking_days BETWEEN 1 AND 365),
  cleanup_buffer_minutes  integer NOT NULL DEFAULT 0 CHECK (cleanup_buffer_minutes BETWEEN 0 AND 60),
  check_in_required       boolean NOT NULL DEFAULT true,
  check_in_opens_minutes  integer NOT NULL DEFAULT 30 CHECK (check_in_opens_minutes BETWEEN 0 AND 240),
  no_show_grace_minutes   integer NOT NULL DEFAULT 15 CHECK (no_show_grace_minutes BETWEEN 0 AND 120),
  cancellation_policy_id  uuid,                             -- FK added after cancellation_policies
  -- denormalized discovery fields (maintained by search.reindex)
  starting_rate_minor     bigint CHECK (starting_rate_minor IS NULL OR starting_rate_minor >= 0),
  rating_avg              numeric(3, 2) CHECK (rating_avg IS NULL OR rating_avg BETWEEN 1 AND 5),
  rating_count            integer NOT NULL DEFAULT 0,
  published_at            timestamptz,
  suspended_at            timestamptz,
  version                 integer NOT NULL DEFAULT 1,
  created_at              timestamptz NOT NULL DEFAULT now(),
  updated_at              timestamptz NOT NULL DEFAULT now(),
  deleted_at              timestamptz,
  CONSTRAINT venues_duration_bounds CHECK (
    min_booking_minutes > 0 AND min_booking_minutes <= max_booking_minutes
    AND min_booking_minutes % slot_increment_minutes = 0 AND max_booking_minutes % slot_increment_minutes = 0),
  CONSTRAINT venues_published_requires_location CHECK (status <> 'published' OR (location IS NOT NULL AND published_at IS NOT NULL))
);
CREATE INDEX venues_business_idx ON app.venues (business_id) WHERE deleted_at IS NULL;
CREATE INDEX venues_location_gix ON app.venues USING gist (location) WHERE status = 'published' AND deleted_at IS NULL;
CREATE INDEX venues_name_trgm    ON app.venues USING gin (name extensions.gin_trgm_ops);
CREATE INDEX venues_landmark_trgm ON app.venues USING gin (landmark extensions.gin_trgm_ops);
CREATE INDEX venues_city_idx     ON app.venues (city_psgc_code) WHERE status = 'published' AND deleted_at IS NULL;
CREATE INDEX venues_barangay_idx ON app.venues (barangay_psgc_code) WHERE status = 'published' AND deleted_at IS NULL;

CREATE TABLE app.venue_operating_hours (
  id            uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id   uuid NOT NULL REFERENCES app.businesses (id),
  venue_id      uuid NOT NULL REFERENCES app.venues (id) ON DELETE CASCADE,
  iso_weekday   smallint NOT NULL CHECK (iso_weekday BETWEEN 1 AND 7),   -- 1 = Monday ... 7 = Sunday (venue local)
  opens_at      time NOT NULL,
  closes_at     time NOT NULL,                             -- '24:00' allowed; past-midnight hours use closes_next_day
  closes_next_day boolean NOT NULL DEFAULT false,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT venue_hours_order CHECK (closes_next_day OR closes_at > opens_at),
  UNIQUE (venue_id, iso_weekday, opens_at)
);
CREATE INDEX venue_operating_hours_business_idx ON app.venue_operating_hours (business_id);

CREATE TABLE app.venue_special_hours (
  id            uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id   uuid NOT NULL REFERENCES app.businesses (id),
  venue_id      uuid NOT NULL REFERENCES app.venues (id) ON DELETE CASCADE,
  local_date    date NOT NULL,
  is_closed     boolean NOT NULL DEFAULT false,
  opens_at      time,
  closes_at     time,
  reason        text,
  created_by    uuid REFERENCES app.users (id),
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT venue_special_hours_shape CHECK (
    (is_closed AND opens_at IS NULL AND closes_at IS NULL) OR (NOT is_closed AND opens_at IS NOT NULL AND closes_at > opens_at))
);
CREATE UNIQUE INDEX venue_special_hours_uniq ON app.venue_special_hours (venue_id, local_date, coalesce(opens_at, '00:00'::time));
CREATE INDEX venue_special_hours_business_idx ON app.venue_special_hours (business_id, local_date);

CREATE TABLE app.venue_amenities (
  venue_id      uuid NOT NULL REFERENCES app.venues (id) ON DELETE CASCADE,
  amenity_code  text NOT NULL REFERENCES app.amenities (code),
  business_id   uuid NOT NULL REFERENCES app.businesses (id),
  notes         text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (venue_id, amenity_code)
);
CREATE INDEX venue_amenities_amenity_idx ON app.venue_amenities (amenity_code);

CREATE TABLE app.courts (
  id               uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id      uuid NOT NULL REFERENCES app.businesses (id),
  venue_id         uuid NOT NULL REFERENCES app.venues (id),
  name             text NOT NULL,
  court_type_code  text NOT NULL REFERENCES app.court_types (code),
  environment      text NOT NULL CHECK (environment IN ('indoor', 'outdoor', 'covered')),
  surface          text,
  status           app.court_status NOT NULL DEFAULT 'active',
  max_players      smallint NOT NULL DEFAULT 4 CHECK (max_players BETWEEN 1 AND 16),
  sort_order       integer NOT NULL DEFAULT 0,
  description      text,
  version          integer NOT NULL DEFAULT 1,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  deleted_at       timestamptz
);
CREATE UNIQUE INDEX courts_name_per_venue ON app.courts (venue_id, lower(name)) WHERE deleted_at IS NULL;
CREATE INDEX courts_business_idx ON app.courts (business_id);

CREATE TABLE app.court_blocks (
  id            uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id   uuid NOT NULL REFERENCES app.businesses (id),
  venue_id      uuid NOT NULL REFERENCES app.venues (id),
  court_id      uuid NOT NULL REFERENCES app.courts (id),
  block_type    app.court_block_type NOT NULL,
  starts_at     timestamptz NOT NULL,
  ends_at       timestamptz NOT NULL,
  reason        text NOT NULL,
  created_by    uuid NOT NULL REFERENCES app.users (id),
  removed_at    timestamptz,
  removed_by    uuid REFERENCES app.users (id),
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT court_blocks_range CHECK (ends_at > starts_at)
);
CREATE INDEX court_blocks_court_time_idx ON app.court_blocks (court_id, starts_at) WHERE removed_at IS NULL;
CREATE INDEX court_blocks_business_idx ON app.court_blocks (business_id, starts_at);

CREATE TABLE app.business_members (
  id           uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id  uuid NOT NULL REFERENCES app.businesses (id),
  user_id      uuid NOT NULL REFERENCES app.users (id),
  status       app.member_status NOT NULL DEFAULT 'invited',
  title        text,
  invited_by   uuid REFERENCES app.users (id),
  invited_at   timestamptz NOT NULL DEFAULT now(),
  joined_at    timestamptz,
  removed_at   timestamptz,
  removed_by   uuid REFERENCES app.users (id),
  version      integer NOT NULL DEFAULT 1,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  UNIQUE (business_id, user_id),
  UNIQUE (business_id, id)                                 -- target for composite FKs that pin rows to one tenant
);
CREATE INDEX business_members_user_idx ON app.business_members (user_id) WHERE status = 'active';

CREATE TABLE app.business_member_roles (
  id           uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id  uuid NOT NULL REFERENCES app.businesses (id),
  member_id    uuid NOT NULL,
  role_id      uuid NOT NULL REFERENCES app.roles (id),
  venue_id     uuid REFERENCES app.venues (id),            -- NULL = all venues of the business
  granted_by   uuid NOT NULL REFERENCES app.users (id),
  granted_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT business_member_roles_member_same_tenant FOREIGN KEY (business_id, member_id)
    REFERENCES app.business_members (business_id, id) ON DELETE CASCADE
);
CREATE UNIQUE INDEX business_member_roles_uniq
  ON app.business_member_roles (member_id, role_id, coalesce(venue_id, '00000000-0000-0000-0000-000000000000'::uuid));
CREATE INDEX business_member_roles_business_idx ON app.business_member_roles (business_id);

CREATE TABLE app.holidays (
  id               uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id      uuid REFERENCES app.businesses (id),    -- NULL = national/platform calendar (tenant rows override)
  venue_id         uuid REFERENCES app.venues (id),
  holiday_date     date NOT NULL,
  name             text NOT NULL,
  kind             app.holiday_kind NOT NULL,
  proclamation_ref text,                                   -- e.g. Presidential Proclamation number (national rows)
  created_by       uuid REFERENCES app.users (id),
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT holidays_venue_requires_business CHECK (venue_id IS NULL OR business_id IS NOT NULL)
);
CREATE UNIQUE INDEX holidays_uniq ON app.holidays (
  coalesce(business_id, '00000000-0000-0000-0000-000000000000'::uuid),
  coalesce(venue_id, '00000000-0000-0000-0000-000000000000'::uuid), holiday_date, name);
CREATE INDEX holidays_date_idx ON app.holidays (holiday_date);

CREATE TABLE app.favorites (
  user_id     uuid NOT NULL REFERENCES app.users (id) ON DELETE CASCADE,
  venue_id    uuid NOT NULL REFERENCES app.venues (id) ON DELETE CASCADE,
  created_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, venue_id)
);
CREATE INDEX favorites_venue_idx ON app.favorites (venue_id);

-- -----------------------------------------------------------------------------
-- 3.5 Commercial terms: commission agreements, gateway fee schedules (payments domain; declared early for FKs)
-- -----------------------------------------------------------------------------

-- business_id NULL = the global default schedule. Rate resolution at quote time: approved business agreement whose
-- effective range contains the booking creation instant, else the approved global row. Maker-checker via approval_requests.
CREATE TABLE app.commission_agreements (
  id                      uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id             uuid REFERENCES app.businesses (id),
  rate_ppm                integer NOT NULL CHECK (rate_ppm BETWEEN 0 AND 1000000),
  commissionable_base     text NOT NULL DEFAULT 'base_after_venue_funded_discounts'
                            CHECK (commissionable_base IN ('base_after_venue_funded_discounts', 'base_before_discounts')),
  applies_to_products     boolean NOT NULL DEFAULT false,
  applies_to_events       boolean NOT NULL DEFAULT false,
  effective_from          timestamptz NOT NULL,
  effective_to            timestamptz,
  status                  app.agreement_status NOT NULL DEFAULT 'draft',
  contract_reference      text,
  approval_request_id     uuid,                            -- FK added after approval_requests
  created_by              uuid NOT NULL REFERENCES app.users (id),
  approved_by             uuid REFERENCES app.users (id),
  approved_at             timestamptz,
  notes                   text,
  version                 integer NOT NULL DEFAULT 1,
  created_at              timestamptz NOT NULL DEFAULT now(),
  updated_at              timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT commission_agreements_range CHECK (effective_to IS NULL OR effective_to > effective_from),
  CONSTRAINT commission_agreements_maker_checker CHECK (approved_by IS NULL OR approved_by <> created_by),
  CONSTRAINT commission_agreements_approved_fields CHECK (status <> 'approved' OR (approved_by IS NOT NULL AND approved_at IS NOT NULL)),
  CONSTRAINT commission_agreements_no_overlap EXCLUDE USING gist (
    (coalesce(business_id, '00000000-0000-0000-0000-000000000000'::uuid)) WITH =,
    tstzrange(effective_from, effective_to, '[)') WITH &&
  ) WHERE (status = 'approved')
);
CREATE INDEX commission_agreements_business_idx ON app.commission_agreements (business_id, effective_from DESC);

-- Gateway fee schedules per payment method (PLACEHOLDER values until the Xendit contract is signed: is_placeholder = true).
CREATE TABLE app.fee_schedules (
  id                    uuid PRIMARY KEY DEFAULT app.uuidv7(),
  provider              app.provider_code NOT NULL,
  payment_method_code   text NOT NULL REFERENCES app.payment_method_types (code),
  business_id           uuid REFERENCES app.businesses (id),   -- NULL = platform default; set = negotiated per agreement
  percent_ppm           integer NOT NULL DEFAULT 0 CHECK (percent_ppm BETWEEN 0 AND 200000),
  fixed_minor           bigint  NOT NULL DEFAULT 0 CHECK (fixed_minor >= 0),
  fee_vat_ppm           integer NOT NULL DEFAULT 0 CHECK (fee_vat_ppm BETWEEN 0 AND 200000),  -- VAT charged on the provider fee, if any
  currency              char(3) NOT NULL DEFAULT 'PHP' CHECK (currency ~ '^[A-Z]{3}$'),
  pass_through_enabled  boolean NOT NULL DEFAULT false,    -- customer pays the gross-up fee (law + provider + card network permitting)
  absorbed_by           app.fee_bearer NOT NULL DEFAULT 'platform' CHECK (absorbed_by <> 'customer'),
  effective_from        timestamptz NOT NULL,
  effective_to          timestamptz,
  status                app.agreement_status NOT NULL DEFAULT 'draft',
  is_placeholder        boolean NOT NULL DEFAULT true,
  contract_reference    text,
  created_by            uuid NOT NULL REFERENCES app.users (id),
  approved_by           uuid REFERENCES app.users (id),
  approved_at           timestamptz,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT fee_schedules_range CHECK (effective_to IS NULL OR effective_to > effective_from),
  CONSTRAINT fee_schedules_maker_checker CHECK (approved_by IS NULL OR approved_by <> created_by),
  CONSTRAINT fee_schedules_no_overlap EXCLUDE USING gist (
    (coalesce(business_id, '00000000-0000-0000-0000-000000000000'::uuid)) WITH =,
    payment_method_code WITH =,
    tstzrange(effective_from, effective_to, '[)') WITH &&
  ) WHERE (status = 'approved')
);

-- -----------------------------------------------------------------------------
-- 3.6 Policies & pricing (tenant; platform templates have business_id NULL)
-- -----------------------------------------------------------------------------

CREATE TABLE app.cancellation_policies (
  id                  uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id         uuid REFERENCES app.businesses (id),  -- NULL = platform template (standard, flexible, strict, non_refundable)
  code                text NOT NULL CHECK (code ~ '^[a-z0-9_]{2,40}$'),
  name                text NOT NULL,
  status              app.config_status NOT NULL DEFAULT 'draft',
  current_version_id  uuid,                                -- FK added below
  created_by          uuid REFERENCES app.users (id),
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX cancellation_policies_code_uniq
  ON app.cancellation_policies (coalesce(business_id, '00000000-0000-0000-0000-000000000000'::uuid), code);

-- Immutable once inserted: bookings store the accepted version id; edits create a new version.
CREATE TABLE app.cancellation_policy_versions (
  id                                  uuid PRIMARY KEY DEFAULT app.uuidv7(),
  policy_id                           uuid NOT NULL REFERENCES app.cancellation_policies (id),
  business_id                         uuid REFERENCES app.businesses (id),
  version                             integer NOT NULL CHECK (version > 0),
  -- tiers ordered by min_hours_before DESC, e.g. Standard:
  -- [{"min_hours_before":24,"refund_ppm":1000000},{"min_hours_before":6,"refund_ppm":500000},{"min_hours_before":0,"refund_ppm":0}]
  tiers                               jsonb NOT NULL CHECK (jsonb_typeof(tiers) = 'array' AND jsonb_array_length(tiers) >= 1),
  non_refundable                      boolean NOT NULL DEFAULT false,
  gateway_fee_refundable_on_player_cancel boolean NOT NULL DEFAULT false,
  reschedule_allowed_count            integer NOT NULL DEFAULT 1 CHECK (reschedule_allowed_count BETWEEN 0 AND 5),
  reschedule_min_hours_before         integer NOT NULL DEFAULT 12 CHECK (reschedule_min_hours_before >= 0),
  no_show_refundable                  boolean NOT NULL DEFAULT false,
  disclosure_md                       text NOT NULL,       -- exact text shown before payment
  disclosure_sha256                   text NOT NULL CHECK (disclosure_sha256 ~ '^[0-9a-f]{64}$'),
  published_by                        uuid REFERENCES app.users (id),
  published_at                        timestamptz NOT NULL DEFAULT now(),
  created_at                          timestamptz NOT NULL DEFAULT now(),
  UNIQUE (policy_id, version)
);
ALTER TABLE app.cancellation_policies ADD CONSTRAINT cancellation_policies_current_version_fk
  FOREIGN KEY (current_version_id) REFERENCES app.cancellation_policy_versions (id);
ALTER TABLE app.venues ADD CONSTRAINT venues_cancellation_policy_fk
  FOREIGN KEY (cancellation_policy_id) REFERENCES app.cancellation_policies (id);

-- Pricing rules. Resolution per 30-minute slice: highest priority wins; ties -> court-scoped over venue-scoped ->
-- later effective_from -> lower id. Every change bumps version (ETag) and writes an audit row with before/after.
CREATE TABLE app.pricing_rules (
  id                    uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id           uuid NOT NULL REFERENCES app.businesses (id),
  venue_id              uuid NOT NULL REFERENCES app.venues (id),
  court_id              uuid REFERENCES app.courts (id),   -- NULL = every court of the venue
  name                  text NOT NULL,
  rule_type             app.pricing_rule_type NOT NULL,
  adjustment            app.pricing_adjustment NOT NULL,
  hourly_rate_minor     bigint CHECK (hourly_rate_minor IS NULL OR hourly_rate_minor >= 0),
  percent_delta_ppm     integer CHECK (percent_delta_ppm IS NULL OR percent_delta_ppm BETWEEN -1000000 AND 10000000),
  fixed_delta_minor     bigint,
  minimum_charge_minor  bigint CHECK (minimum_charge_minor IS NULL OR minimum_charge_minor >= 0),
  currency              char(3) NOT NULL DEFAULT 'PHP' CHECK (currency ~ '^[A-Z]{3}$'),
  priority              integer NOT NULL DEFAULT 100 CHECK (priority BETWEEN 0 AND 10000),
  iso_weekdays          smallint[] CHECK (iso_weekdays IS NULL OR iso_weekdays <@ ARRAY[1,2,3,4,5,6,7]::smallint[]),
  local_start_time      time,
  local_end_time        time,
  effective_from        date,
  effective_to          date,                              -- inclusive last local date
  holiday_only          boolean NOT NULL DEFAULT false,
  refundable            boolean NOT NULL DEFAULT true,     -- false = non-refundable rate plan
  status                app.config_status NOT NULL DEFAULT 'draft',
  version               integer NOT NULL DEFAULT 1,
  created_by            uuid NOT NULL REFERENCES app.users (id),
  updated_by            uuid REFERENCES app.users (id),
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT pricing_rules_adjustment_shape CHECK (
       (adjustment = 'set_hourly_rate'      AND hourly_rate_minor IS NOT NULL)
    OR (adjustment = 'percent_delta'        AND percent_delta_ppm IS NOT NULL)
    OR (adjustment = 'fixed_delta_per_hour' AND fixed_delta_minor IS NOT NULL)
    OR (adjustment = 'minimum_charge'       AND minimum_charge_minor IS NOT NULL)),
  CONSTRAINT pricing_rules_time_window CHECK (
    (local_start_time IS NULL AND local_end_time IS NULL) OR (local_start_time IS NOT NULL AND local_end_time > local_start_time)),
  CONSTRAINT pricing_rules_date_window CHECK (effective_to IS NULL OR effective_from IS NULL OR effective_to >= effective_from)
);
CREATE INDEX pricing_rules_lookup_idx ON app.pricing_rules (venue_id, status, priority DESC) WHERE status = 'active';
CREATE INDEX pricing_rules_court_idx ON app.pricing_rules (court_id) WHERE court_id IS NOT NULL;
CREATE INDEX pricing_rules_business_idx ON app.pricing_rules (business_id);

-- business_id NULL = platform promotion (platform-funded); business promotions are venue-funded.
CREATE TABLE app.promotions (
  id                     uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id            uuid REFERENCES app.businesses (id),
  code                   extensions.citext NOT NULL CHECK (code ~* '^[A-Z0-9_-]{3,32}$'),
  name                   text NOT NULL,
  description            text,
  discount_type          app.discount_type NOT NULL,
  percent_ppm            integer CHECK (percent_ppm IS NULL OR percent_ppm BETWEEN 1 AND 1000000),
  amount_minor           bigint CHECK (amount_minor IS NULL OR amount_minor > 0),
  max_discount_minor     bigint CHECK (max_discount_minor IS NULL OR max_discount_minor > 0),
  min_spend_minor        bigint NOT NULL DEFAULT 0 CHECK (min_spend_minor >= 0),
  currency               char(3) NOT NULL DEFAULT 'PHP' CHECK (currency ~ '^[A-Z]{3}$'),
  funded_by              app.discount_funder NOT NULL,
  applies_to             text NOT NULL DEFAULT 'court_booking' CHECK (applies_to IN ('court_booking', 'product', 'event_registration', 'any')),
  venue_ids              uuid[],                           -- NULL = all venues in scope
  starts_at              timestamptz NOT NULL,
  ends_at                timestamptz NOT NULL,
  usage_limit_total      integer CHECK (usage_limit_total IS NULL OR usage_limit_total > 0),
  usage_limit_per_user   integer NOT NULL DEFAULT 1 CHECK (usage_limit_per_user > 0),
  redemption_count       integer NOT NULL DEFAULT 0 CHECK (redemption_count >= 0),
  status                 app.promotion_status NOT NULL DEFAULT 'draft',
  created_by             uuid NOT NULL REFERENCES app.users (id),
  version                integer NOT NULL DEFAULT 1,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT promotions_funding_matches_owner CHECK ((business_id IS NULL) = (funded_by = 'platform')),
  CONSTRAINT promotions_value_shape CHECK (
    (discount_type = 'percent' AND percent_ppm IS NOT NULL AND amount_minor IS NULL)
    OR (discount_type = 'fixed' AND amount_minor IS NOT NULL AND percent_ppm IS NULL)),
  CONSTRAINT promotions_window CHECK (ends_at > starts_at),
  CONSTRAINT promotions_limit CHECK (usage_limit_total IS NULL OR redemption_count <= usage_limit_total)
);
CREATE UNIQUE INDEX promotions_code_uniq
  ON app.promotions (coalesce(business_id, '00000000-0000-0000-0000-000000000000'::uuid), code) WHERE status <> 'archived';
CREATE INDEX promotions_business_idx ON app.promotions (business_id, status);

-- -----------------------------------------------------------------------------
-- 3.7 Checkout (tenant). One checkout = one business = one provider payment (xenPlatform sub-account + split rule).
-- -----------------------------------------------------------------------------

CREATE TABLE app.checkouts (
  id                              uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id                     uuid NOT NULL REFERENCES app.businesses (id),
  venue_id                        uuid NOT NULL REFERENCES app.venues (id),
  user_id                         uuid REFERENCES app.users (id),         -- NULL = guest walk-in paying via payment link
  created_by_user_id              uuid NOT NULL REFERENCES app.users (id),
  status                          app.checkout_status NOT NULL DEFAULT 'open',
  currency                        char(3) NOT NULL DEFAULT 'PHP' CHECK (currency ~ '^[A-Z]{3}$'),
  quote_lines                     jsonb NOT NULL,          -- display lines exactly as shown to the customer (doc 13 §3.3)
  quote_sha256                    text NOT NULL CHECK (quote_sha256 ~ '^[0-9a-f]{64}$'),
  subtotal_minor                  bigint NOT NULL CHECK (subtotal_minor >= 0),
  discount_minor                  bigint NOT NULL DEFAULT 0 CHECK (discount_minor >= 0),
  tax_exclusive_minor             bigint NOT NULL DEFAULT 0 CHECK (tax_exclusive_minor >= 0),
  vat_included_minor              bigint NOT NULL DEFAULT 0 CHECK (vat_included_minor >= 0),   -- informational
  gateway_fee_minor               bigint NOT NULL DEFAULT 0 CHECK (gateway_fee_minor >= 0),   -- customer-paid part only
  total_minor                     bigint NOT NULL CHECK (total_minor >= 0),
  payment_method_code             text NOT NULL REFERENCES app.payment_method_types (code),
  fee_schedule_id                 uuid REFERENCES app.fee_schedules (id),
  promotion_id                    uuid REFERENCES app.promotions (id),
  cancellation_policy_version_id  uuid NOT NULL REFERENCES app.cancellation_policy_versions (id),
  policy_accepted_at              timestamptz NOT NULL,
  quote_expires_at                timestamptz NOT NULL,    -- = earliest hold expiry; the quote is locked until then
  paid_at                         timestamptz,
  closed_at                       timestamptz,
  version                         integer NOT NULL DEFAULT 1,
  created_at                      timestamptz NOT NULL DEFAULT now(),
  updated_at                      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT checkouts_total_formula CHECK (
    total_minor = subtotal_minor - discount_minor + tax_exclusive_minor + gateway_fee_minor),
  CONSTRAINT checkouts_paid_at CHECK ((status = 'paid') = (paid_at IS NOT NULL))
);
CREATE INDEX checkouts_user_idx ON app.checkouts (user_id, created_at DESC);
CREATE INDEX checkouts_business_idx ON app.checkouts (business_id, created_at DESC);
CREATE INDEX checkouts_open_expiry_idx ON app.checkouts (quote_expires_at) WHERE status IN ('open', 'payment_pending');

-- -----------------------------------------------------------------------------
-- 3.8 Events (core tables; declared before booking_slots because events reserve courts)
-- -----------------------------------------------------------------------------

CREATE TABLE app.events (
  id                              uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id                     uuid NOT NULL REFERENCES app.businesses (id),
  venue_id                        uuid NOT NULL REFERENCES app.venues (id),
  event_type_code                 text NOT NULL REFERENCES app.event_types (code),
  name                            text NOT NULL,
  slug                            extensions.citext NOT NULL CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  description                     text,
  status                          app.event_status NOT NULL DEFAULT 'draft',
  visibility                      app.event_visibility NOT NULL DEFAULT 'public',
  organizer_member_id             uuid,
  starts_at                       timestamptz NOT NULL,
  ends_at                         timestamptz NOT NULL,
  registration_opens_at           timestamptz NOT NULL,
  registration_closes_at          timestamptz NOT NULL,
  capacity                        integer NOT NULL CHECK (capacity > 0),
  waitlist_enabled                boolean NOT NULL DEFAULT true,
  waitlist_offer_ttl_minutes      integer NOT NULL DEFAULT 120 CHECK (waitlist_offer_ttl_minutes BETWEEN 15 AND 2880),
  fee_minor                       bigint NOT NULL DEFAULT 0 CHECK (fee_minor >= 0),
  currency                        char(3) NOT NULL DEFAULT 'PHP' CHECK (currency ~ '^[A-Z]{3}$'),
  team_based                      boolean NOT NULL DEFAULT false,
  team_size                       smallint CHECK (team_size IS NULL OR team_size BETWEEN 2 AND 12),
  skill_min                       text,
  skill_max                       text,
  age_category                    text,
  match_format                    text,
  prizes_md                       text,
  rules_md                        text,
  check_in_opens_minutes          integer NOT NULL DEFAULT 60,
  cancellation_policy_version_id  uuid REFERENCES app.cancellation_policy_versions (id),
  published_at                    timestamptz,
  cancelled_at                    timestamptz,
  cancellation_reason             text,
  created_by                      uuid NOT NULL REFERENCES app.users (id),
  version                         integer NOT NULL DEFAULT 1,
  created_at                      timestamptz NOT NULL DEFAULT now(),
  updated_at                      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT events_time_order CHECK (ends_at > starts_at AND registration_closes_at > registration_opens_at
                                      AND registration_closes_at <= ends_at),
  CONSTRAINT events_team_size CHECK (NOT team_based OR team_size IS NOT NULL),
  CONSTRAINT events_organizer_same_tenant FOREIGN KEY (business_id, organizer_member_id)
    REFERENCES app.business_members (business_id, id),
  UNIQUE (business_id, slug),
  UNIQUE (business_id, id)
);
CREATE INDEX events_schedule_idx ON app.events (venue_id, starts_at) WHERE status IN ('published', 'registration_closed', 'in_progress');
CREATE INDEX events_public_idx ON app.events (starts_at) WHERE status = 'published' AND visibility = 'public';
CREATE INDEX events_name_trgm ON app.events USING gin (name extensions.gin_trgm_ops);

CREATE TABLE app.event_divisions (
  id               uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id      uuid NOT NULL REFERENCES app.businesses (id),
  event_id         uuid NOT NULL,
  name             text NOT NULL,
  capacity         integer NOT NULL CHECK (capacity > 0),
  occupied_count   integer NOT NULL DEFAULT 0,             -- held + pending_payment + confirmed + offered + checked_in (row-locked)
  fee_minor        bigint CHECK (fee_minor IS NULL OR fee_minor >= 0),   -- NULL = event fee
  skill_min        text,
  skill_max        text,
  age_category     text,
  gender_category  text,
  team_size        smallint,
  sort_order       integer NOT NULL DEFAULT 0,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT event_divisions_capacity CHECK (occupied_count BETWEEN 0 AND capacity),
  CONSTRAINT event_divisions_event_same_tenant FOREIGN KEY (business_id, event_id) REFERENCES app.events (business_id, id),
  UNIQUE (event_id, name)
);

-- -----------------------------------------------------------------------------
-- 3.9 Availability & booking (tenant) — state machine in doc 07
-- -----------------------------------------------------------------------------

CREATE TABLE app.bookings (
  id                              uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id                     uuid NOT NULL REFERENCES app.businesses (id),
  venue_id                        uuid NOT NULL REFERENCES app.venues (id),
  court_id                        uuid NOT NULL REFERENCES app.courts (id),
  player_user_id                  uuid REFERENCES app.users (id),         -- NULL only for guest walk-ins
  guest_name                      text,
  guest_contact_ciphertext        bytea,                  -- envelope-encrypted {email, phone} for guest walk-ins
  booker_display_name             text NOT NULL,          -- snapshot shown on the staff calendar (minimal PII)
  source                          app.booking_source NOT NULL DEFAULT 'player_app',
  status                          app.booking_status NOT NULL DEFAULT 'draft',
  booking_code                    text NOT NULL CHECK (booking_code ~ '^[0-9A-HJKMNP-TV-Z]{8}$'),   -- Crockford base32
  starts_at                       timestamptz NOT NULL,
  ends_at                         timestamptz NOT NULL,
  play_local_date                 date NOT NULL,          -- venue-local date of starts_at ("play date" report basis)
  checkout_id                     uuid REFERENCES app.checkouts (id),
  price_snapshot_id               uuid,                   -- FK added after booking_price_snapshots
  cancellation_policy_version_id  uuid REFERENCES app.cancellation_policy_versions (id),
  policy_accepted_at              timestamptz,
  commission_agreement_id         uuid REFERENCES app.commission_agreements (id),
  commission_rate_ppm             integer CHECK (commission_rate_ppm IS NULL OR commission_rate_ppm BETWEEN 0 AND 1000000),
  currency                        char(3) NOT NULL DEFAULT 'PHP' CHECK (currency ~ '^[A-Z]{3}$'),
  base_minor                      bigint NOT NULL DEFAULT 0 CHECK (base_minor >= 0),
  discount_minor                  bigint NOT NULL DEFAULT 0 CHECK (discount_minor >= 0),
  total_minor                     bigint NOT NULL DEFAULT 0 CHECK (total_minor >= 0),
  refunded_minor                  bigint NOT NULL DEFAULT 0 CHECK (refunded_minor >= 0),
  confirmed_at                    timestamptz,
  checked_in_at                   timestamptz,
  checked_in_by                   uuid REFERENCES app.users (id),
  completed_at                    timestamptz,
  cancelled_at                    timestamptz,
  cancelled_by                    uuid REFERENCES app.users (id),
  cancellation_initiator          text CHECK (cancellation_initiator IS NULL OR cancellation_initiator IN ('player', 'venue', 'platform', 'system')),
  cancellation_reason             text,
  no_show_at                      timestamptz,
  no_show_marked_by               uuid REFERENCES app.users (id),
  expired_at                      timestamptz,
  failed_at                       timestamptz,
  failure_reason                  text,
  pre_dispute_status              app.booking_status CHECK (pre_dispute_status IS NULL OR pre_dispute_status IN ('confirmed', 'checked_in', 'completed')),
  reschedule_count                integer NOT NULL DEFAULT 0 CHECK (reschedule_count >= 0),
  late_payment_recovered          boolean NOT NULL DEFAULT false,
  version                         integer NOT NULL DEFAULT 1,
  created_at                      timestamptz NOT NULL DEFAULT now(),
  updated_at                      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT bookings_time_order CHECK (ends_at > starts_at),
  CONSTRAINT bookings_customer_present CHECK (player_user_id IS NOT NULL OR guest_name IS NOT NULL),
  CONSTRAINT bookings_policy_before_payment CHECK (
    status IN ('draft', 'slot_held', 'cancelled', 'expired', 'failed')
    OR (cancellation_policy_version_id IS NOT NULL AND policy_accepted_at IS NOT NULL
        AND commission_rate_ppm IS NOT NULL AND checkout_id IS NOT NULL)),
  CONSTRAINT bookings_confirmed_at CHECK (
    status NOT IN ('confirmed', 'checked_in', 'completed', 'no_show', 'disputed') OR confirmed_at IS NOT NULL),
  CONSTRAINT bookings_dispute_restore CHECK (status <> 'disputed' OR pre_dispute_status IS NOT NULL),
  CONSTRAINT bookings_refund_bound CHECK (refunded_minor <= total_minor),
  UNIQUE (business_id, booking_code),
  UNIQUE (business_id, id)
);
CREATE INDEX bookings_business_start_idx ON app.bookings (business_id, starts_at);
CREATE INDEX bookings_venue_date_idx ON app.bookings (venue_id, play_local_date);
CREATE INDEX bookings_court_start_idx ON app.bookings (court_id, starts_at);
CREATE INDEX bookings_player_idx ON app.bookings (player_user_id, starts_at DESC) WHERE player_user_id IS NOT NULL;
CREATE INDEX bookings_checkout_idx ON app.bookings (checkout_id) WHERE checkout_id IS NOT NULL;
CREATE INDEX bookings_to_complete_idx ON app.bookings (ends_at) WHERE status IN ('confirmed', 'checked_in');
CREATE INDEX bookings_reminders_idx ON app.bookings (starts_at) WHERE status = 'confirmed';
CREATE INDEX bookings_status_idx ON app.bookings (business_id, status, starts_at);

-- A hold is the temporary reservation contract (who, until when, why released). 1 hold : 1 booking.
CREATE TABLE app.booking_holds (
  id                    uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id           uuid NOT NULL REFERENCES app.businesses (id),
  venue_id              uuid NOT NULL REFERENCES app.venues (id),
  court_id              uuid NOT NULL REFERENCES app.courts (id),
  booking_id            uuid NOT NULL UNIQUE,
  holder_user_id        uuid NOT NULL REFERENCES app.users (id),   -- player, or staff member for walk-ins
  on_behalf_of_user_id  uuid REFERENCES app.users (id),
  status                app.hold_status NOT NULL DEFAULT 'active',
  expires_at            timestamptz NOT NULL,
  extended_at           timestamptz,                    -- one-time extension to the provider's minimum session TTL
  released_at           timestamptz,
  release_reason        app.slot_release_reason,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT booking_holds_booking_same_tenant FOREIGN KEY (business_id, booking_id) REFERENCES app.bookings (business_id, id),
  CONSTRAINT booking_holds_expiry CHECK (expires_at > created_at AND expires_at <= created_at + interval '30 minutes'),
  CONSTRAINT booking_holds_release CHECK ((status IN ('released', 'expired')) = (released_at IS NOT NULL))
);
CREATE INDEX booking_holds_active_user_idx ON app.booking_holds (holder_user_id) WHERE status = 'active';
CREATE INDEX booking_holds_expiry_idx ON app.booking_holds (expires_at) WHERE status = 'active';

-- Physical court occupancy. Holds (via their booking), bookings, maintenance blocks and event reservations all live here,
-- so the exclusion constraint makes double booking impossible at the database level.
CREATE TABLE app.booking_slots (
  id               uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id      uuid NOT NULL REFERENCES app.businesses (id),
  venue_id         uuid NOT NULL REFERENCES app.venues (id),
  court_id         uuid NOT NULL REFERENCES app.courts (id),
  occupant_type    app.slot_occupant_type NOT NULL,
  booking_id       uuid,
  court_block_id   uuid REFERENCES app.court_blocks (id),
  event_id         uuid,
  play_range       tstzrange NOT NULL,                  -- customer play time [start, end)
  occupied_range   tstzrange NOT NULL,                  -- play_range extended by the venue cleanup buffer
  status           app.slot_status NOT NULL DEFAULT 'active',
  hold_expires_at  timestamptz,                         -- set while the owning booking is slot_held/payment_pending
  released_at      timestamptz,
  release_reason   app.slot_release_reason,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT booking_slots_booking_same_tenant FOREIGN KEY (business_id, booking_id) REFERENCES app.bookings (business_id, id),
  CONSTRAINT booking_slots_event_same_tenant   FOREIGN KEY (business_id, event_id)   REFERENCES app.events (business_id, id),
  CONSTRAINT booking_slots_one_occupant CHECK (
       (occupant_type = 'booking'     AND booking_id IS NOT NULL AND court_block_id IS NULL AND event_id IS NULL)
    OR (occupant_type = 'court_block' AND court_block_id IS NOT NULL AND booking_id IS NULL AND event_id IS NULL)
    OR (occupant_type = 'event'       AND event_id IS NOT NULL AND booking_id IS NULL AND court_block_id IS NULL)),
  CONSTRAINT booking_slots_range_shape CHECK (
    NOT isempty(play_range) AND lower_inc(play_range) AND NOT upper_inc(play_range)
    AND NOT lower_inf(play_range) AND NOT upper_inf(play_range)
    AND occupied_range @> play_range),
  CONSTRAINT booking_slots_hold_only_for_bookings CHECK (hold_expires_at IS NULL OR occupant_type = 'booking'),
  CONSTRAINT booking_slots_release_consistency CHECK (
    (status = 'released') = (released_at IS NOT NULL AND release_reason IS NOT NULL)),
  CONSTRAINT booking_slots_no_overlap EXCLUDE USING gist (court_id WITH =, occupied_range WITH &&) WHERE (status = 'active')
);
CREATE UNIQUE INDEX booking_slots_one_active_per_booking ON app.booking_slots (booking_id) WHERE status = 'active' AND booking_id IS NOT NULL;
CREATE UNIQUE INDEX booking_slots_one_active_per_block   ON app.booking_slots (court_block_id) WHERE status = 'active' AND court_block_id IS NOT NULL;
CREATE INDEX booking_slots_stale_holds_idx ON app.booking_slots (hold_expires_at) WHERE status = 'active' AND hold_expires_at IS NOT NULL;
CREATE INDEX booking_slots_business_idx ON app.booking_slots (business_id, lower(play_range));
CREATE INDEX booking_slots_event_idx ON app.booking_slots (event_id) WHERE event_id IS NOT NULL;

-- Same-tenant integrity: a row can never point at another tenant's venue or court (defence in depth beside RLS).
ALTER TABLE app.venues ADD CONSTRAINT venues_business_id_id_key UNIQUE (business_id, id);
ALTER TABLE app.courts ADD CONSTRAINT courts_business_id_id_key UNIQUE (business_id, id);
ALTER TABLE app.courts ADD CONSTRAINT courts_venue_same_tenant
  FOREIGN KEY (business_id, venue_id) REFERENCES app.venues (business_id, id);
ALTER TABLE app.bookings ADD CONSTRAINT bookings_venue_same_tenant
  FOREIGN KEY (business_id, venue_id) REFERENCES app.venues (business_id, id);
ALTER TABLE app.bookings ADD CONSTRAINT bookings_court_same_tenant
  FOREIGN KEY (business_id, court_id) REFERENCES app.courts (business_id, id);
ALTER TABLE app.booking_holds ADD CONSTRAINT booking_holds_court_same_tenant
  FOREIGN KEY (business_id, court_id) REFERENCES app.courts (business_id, id);
ALTER TABLE app.booking_slots ADD CONSTRAINT booking_slots_court_same_tenant
  FOREIGN KEY (business_id, court_id) REFERENCES app.courts (business_id, id);
ALTER TABLE app.court_blocks ADD CONSTRAINT court_blocks_court_same_tenant
  FOREIGN KEY (business_id, court_id) REFERENCES app.courts (business_id, id);

CREATE TABLE app.booking_participants (
  id             uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id    uuid NOT NULL REFERENCES app.businesses (id),
  booking_id     uuid NOT NULL,
  user_id        uuid REFERENCES app.users (id),
  display_name   text NOT NULL,
  status         text NOT NULL DEFAULT 'invited' CHECK (status IN ('invited', 'accepted', 'declined', 'removed')),
  invited_by     uuid NOT NULL REFERENCES app.users (id),
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT booking_participants_booking_same_tenant FOREIGN KEY (business_id, booking_id) REFERENCES app.bookings (business_id, id)
);
CREATE UNIQUE INDEX booking_participants_user_uniq ON app.booking_participants (booking_id, user_id) WHERE user_id IS NOT NULL;
CREATE INDEX booking_participants_user_idx ON app.booking_participants (user_id) WHERE user_id IS NOT NULL;

-- Immutable pricing snapshot (quote locked at checkout; final on confirmation; a reschedule adds a superseding row).
CREATE TABLE app.booking_price_snapshots (
  id                         uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id                uuid NOT NULL REFERENCES app.businesses (id),
  booking_id                 uuid NOT NULL,
  checkout_id                uuid NOT NULL REFERENCES app.checkouts (id),
  supersedes_snapshot_id     uuid REFERENCES app.booking_price_snapshots (id),
  engine_version             text NOT NULL,             -- packages/domain pricing engine semantic version
  currency                   char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  slices                     jsonb NOT NULL,            -- [{start,end,minutes,rate_minor_per_hour,rule_id,rule_version}]
  lines                      jsonb NOT NULL,            -- customer-facing lines (base, discounts, VAT info, fee, total)
  base_minor                 bigint NOT NULL CHECK (base_minor >= 0),
  venue_discount_minor       bigint NOT NULL DEFAULT 0 CHECK (venue_discount_minor >= 0),
  platform_discount_minor    bigint NOT NULL DEFAULT 0 CHECK (platform_discount_minor >= 0),
  commissionable_base_minor  bigint NOT NULL CHECK (commissionable_base_minor >= 0),
  commission_agreement_id    uuid NOT NULL REFERENCES app.commission_agreements (id),
  commission_rate_ppm        integer NOT NULL CHECK (commission_rate_ppm BETWEEN 0 AND 1000000),
  commission_minor           bigint NOT NULL CHECK (commission_minor >= 0),
  gateway_fee_minor          bigint NOT NULL DEFAULT 0 CHECK (gateway_fee_minor >= 0),   -- customer-paid
  gateway_fee_bearer         app.fee_bearer NOT NULL,
  fee_schedule_id            uuid REFERENCES app.fee_schedules (id),
  tax_exclusive_minor        bigint NOT NULL DEFAULT 0 CHECK (tax_exclusive_minor >= 0),
  vat_included_minor         bigint NOT NULL DEFAULT 0 CHECK (vat_included_minor >= 0),
  customer_total_minor       bigint NOT NULL CHECK (customer_total_minor >= 0),
  venue_net_minor            bigint NOT NULL,
  promotion_id               uuid REFERENCES app.promotions (id),
  quote_expires_at           timestamptz NOT NULL,
  created_at                 timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT booking_price_snapshots_booking_same_tenant FOREIGN KEY (business_id, booking_id) REFERENCES app.bookings (business_id, id),
  CONSTRAINT booking_price_snapshots_commissionable CHECK (commissionable_base_minor <= base_minor)
);
CREATE INDEX booking_price_snapshots_booking_idx ON app.booking_price_snapshots (booking_id, created_at DESC);
ALTER TABLE app.bookings ADD CONSTRAINT bookings_price_snapshot_fk
  FOREIGN KEY (price_snapshot_id) REFERENCES app.booking_price_snapshots (id);

CREATE TABLE app.booking_status_history (
  id               uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id      uuid NOT NULL REFERENCES app.businesses (id),
  booking_id       uuid NOT NULL,
  from_status      app.booking_status,                  -- NULL for creation
  to_status        app.booking_status NOT NULL,
  transition_code  text NOT NULL CHECK (transition_code ~ '^B[0-9]{2}$'),   -- B01..B28, doc 07 §3
  actor_type       text NOT NULL CHECK (actor_type IN ('player', 'staff', 'platform', 'system', 'provider')),
  actor_user_id    uuid REFERENCES app.users (id),
  support_session_id uuid REFERENCES app.support_sessions (id),
  reason           text,
  metadata         jsonb NOT NULL DEFAULT '{}'::jsonb,  -- e.g. {"old_slot_id":..., "new_slot_id":...} for reschedules
  correlation_id   text NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT booking_status_history_booking_same_tenant FOREIGN KEY (business_id, booking_id) REFERENCES app.bookings (business_id, id)
);
CREATE INDEX booking_status_history_booking_idx ON app.booking_status_history (booking_id, created_at);

CREATE TABLE app.checkout_items (
  id                         uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id                uuid NOT NULL REFERENCES app.businesses (id),
  checkout_id                uuid NOT NULL REFERENCES app.checkouts (id),
  item_type                  app.checkout_item_type NOT NULL,
  booking_id                 uuid,
  order_item_id              uuid,                      -- FK added after order_items
  event_registration_id      uuid,                      -- FK added after event_registrations
  description                text NOT NULL,
  quantity                   integer NOT NULL DEFAULT 1 CHECK (quantity > 0),
  unit_amount_minor          bigint NOT NULL CHECK (unit_amount_minor >= 0),
  gross_minor                bigint NOT NULL CHECK (gross_minor >= 0),
  venue_discount_minor       bigint NOT NULL DEFAULT 0 CHECK (venue_discount_minor >= 0),
  platform_discount_minor    bigint NOT NULL DEFAULT 0 CHECK (platform_discount_minor >= 0),
  tax_exclusive_minor        bigint NOT NULL DEFAULT 0 CHECK (tax_exclusive_minor >= 0),
  vat_included_minor         bigint NOT NULL DEFAULT 0 CHECK (vat_included_minor >= 0),
  commissionable             boolean NOT NULL,
  commissionable_base_minor  bigint NOT NULL DEFAULT 0 CHECK (commissionable_base_minor >= 0),
  commission_minor           bigint NOT NULL DEFAULT 0 CHECK (commission_minor >= 0),
  refunded_minor             bigint NOT NULL DEFAULT 0 CHECK (refunded_minor >= 0),
  currency                   char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  created_at                 timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT checkout_items_booking_same_tenant FOREIGN KEY (business_id, booking_id) REFERENCES app.bookings (business_id, id),
  CONSTRAINT checkout_items_reference_shape CHECK (
       (item_type = 'court_booking'      AND booking_id IS NOT NULL AND order_item_id IS NULL AND event_registration_id IS NULL)
    OR (item_type = 'product'            AND order_item_id IS NOT NULL AND booking_id IS NULL AND event_registration_id IS NULL)
    OR (item_type = 'event_registration' AND event_registration_id IS NOT NULL AND booking_id IS NULL AND order_item_id IS NULL)),
  CONSTRAINT checkout_items_gross CHECK (gross_minor = unit_amount_minor * quantity),
  CONSTRAINT checkout_items_commission_flag CHECK (commissionable OR (commissionable_base_minor = 0 AND commission_minor = 0)),
  CONSTRAINT checkout_items_refund_bound CHECK (
    refunded_minor <= gross_minor - venue_discount_minor - platform_discount_minor + tax_exclusive_minor)
);
CREATE INDEX checkout_items_checkout_idx ON app.checkout_items (checkout_id);
CREATE INDEX checkout_items_booking_idx ON app.checkout_items (booking_id) WHERE booking_id IS NOT NULL;

CREATE TABLE app.promotion_redemptions (
  id             uuid PRIMARY KEY DEFAULT app.uuidv7(),
  promotion_id   uuid NOT NULL REFERENCES app.promotions (id),
  business_id    uuid NOT NULL REFERENCES app.businesses (id),   -- tenant of the checkout
  user_id        uuid REFERENCES app.users (id),
  checkout_id    uuid NOT NULL REFERENCES app.checkouts (id),
  discount_minor bigint NOT NULL CHECK (discount_minor > 0),
  currency       char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  status         app.redemption_status NOT NULL DEFAULT 'reserved',
  reserved_at    timestamptz NOT NULL DEFAULT now(),
  redeemed_at    timestamptz,
  released_at    timestamptz,
  UNIQUE (promotion_id, checkout_id)
);
CREATE INDEX promotion_redemptions_user_idx ON app.promotion_redemptions (promotion_id, user_id) WHERE status IN ('reserved', 'redeemed');
CREATE INDEX promotion_redemptions_business_idx ON app.promotion_redemptions (business_id);

-- -----------------------------------------------------------------------------
-- 3.10 Payments, approvals, refunds, disputes (tenant unless noted) — docs 08 and 09
-- -----------------------------------------------------------------------------

-- xenPlatform sub-account per approved business (Option A). MANAGED vs OWNED is an open decision (doc 23).
CREATE TABLE app.payment_provider_accounts (
  id                    uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id           uuid NOT NULL REFERENCES app.businesses (id),
  provider              app.provider_code NOT NULL,
  provider_account_id   text NOT NULL,                  -- Xendit sub-account business id (sent as for-user-id)
  account_type          app.provider_account_type NOT NULL,
  status                app.provider_account_status NOT NULL DEFAULT 'pending',
  kyc_status            text,                           -- provider-reported, informational
  capabilities          jsonb NOT NULL DEFAULT '{}'::jsonb,   -- enabled channels, refund support (provider-dependent)
  activated_at          timestamptz,
  suspended_at          timestamptz,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  UNIQUE (provider, provider_account_id)
);
CREATE UNIQUE INDEX payment_provider_accounts_one_active ON app.payment_provider_accounts (business_id, provider) WHERE status IN ('pending', 'active');

-- Provider customer objects (global, player-owned; not tenant data).
CREATE TABLE app.payment_customers (
  id                    uuid PRIMARY KEY DEFAULT app.uuidv7(),
  user_id               uuid NOT NULL REFERENCES app.users (id),
  provider              app.provider_code NOT NULL,
  provider_customer_id  text NOT NULL,
  provider_account_scope text NOT NULL DEFAULT 'master',   -- 'master' or a sub-account id (token portability: to be verified)
  created_at            timestamptz NOT NULL DEFAULT now(),
  UNIQUE (provider, provider_customer_id),
  UNIQUE (provider, user_id, provider_account_scope)
);

-- Saved methods = provider tokens + masked metadata ONLY (never PAN, CVV, OTP, PIN).
CREATE TABLE app.payment_method_tokens (
  id                    uuid PRIMARY KEY DEFAULT app.uuidv7(),
  user_id               uuid NOT NULL REFERENCES app.users (id),
  payment_customer_id   uuid NOT NULL REFERENCES app.payment_customers (id),
  provider              app.provider_code NOT NULL,
  provider_token_id     text NOT NULL,
  payment_method_code   text NOT NULL REFERENCES app.payment_method_types (code),
  card_brand            text,
  card_last4            char(4) CHECK (card_last4 IS NULL OR card_last4 ~ '^[0-9]{4}$'),
  card_exp_month        smallint CHECK (card_exp_month IS NULL OR card_exp_month BETWEEN 1 AND 12),
  card_exp_year         smallint CHECK (card_exp_year IS NULL OR card_exp_year BETWEEN 2020 AND 2100),
  wallet_account_masked text CHECK (wallet_account_masked IS NULL OR wallet_account_masked !~ '[0-9]{5,}'),   -- e.g. '+63 9** *** 0001'
  status                text NOT NULL DEFAULT 'active' CHECK (status IN ('pending', 'active', 'expired', 'revoked', 'failed')),
  is_default            boolean NOT NULL DEFAULT false,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  revoked_at            timestamptz,
  UNIQUE (provider, provider_token_id)
);
CREATE UNIQUE INDEX payment_method_tokens_one_default ON app.payment_method_tokens (user_id) WHERE is_default AND status = 'active';

-- Maker-checker for sensitive actions (commission agreements, exception refunds, manual adjustments, payout-account changes ...).
CREATE TABLE app.approval_requests (
  id                   uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id          uuid REFERENCES app.businesses (id),   -- NULL = platform-level request
  action               app.approval_action NOT NULL,
  target_type          text NOT NULL,                  -- e.g. 'commission_agreement', 'refund', 'ledger_journal'
  target_id            uuid,
  payload              jsonb NOT NULL,                 -- the exact proposed change; executed verbatim after approval
  payload_sha256       text NOT NULL CHECK (payload_sha256 ~ '^[0-9a-f]{64}$'),
  required_permission  text NOT NULL REFERENCES app.permissions (code),
  status               app.approval_status NOT NULL DEFAULT 'pending',
  reason               text NOT NULL CHECK (length(reason) >= 10),
  requested_by         uuid NOT NULL REFERENCES app.users (id),
  requested_at         timestamptz NOT NULL DEFAULT now(),
  decided_by           uuid REFERENCES app.users (id),
  decided_at           timestamptz,
  decision_note        text,
  expires_at           timestamptz NOT NULL,
  executed_at          timestamptz,
  version              integer NOT NULL DEFAULT 1,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT approval_requests_four_eyes CHECK (decided_by IS NULL OR decided_by <> requested_by),
  CONSTRAINT approval_requests_decision CHECK ((status IN ('approved', 'rejected')) = (decided_by IS NOT NULL AND decided_at IS NOT NULL)),
  CONSTRAINT approval_requests_execution CHECK (executed_at IS NULL OR status = 'approved')
);
CREATE INDEX approval_requests_queue_idx ON app.approval_requests (required_permission, requested_at) WHERE status = 'pending';
CREATE INDEX approval_requests_business_idx ON app.approval_requests (business_id, requested_at DESC);
CREATE INDEX approval_requests_target_idx ON app.approval_requests (target_type, target_id);

ALTER TABLE app.commission_agreements ADD CONSTRAINT commission_agreements_approval_fk
  FOREIGN KEY (approval_request_id) REFERENCES app.approval_requests (id);

-- Payout destination (masked). Full account number only as ciphertext for provider payout calls (Option B / OWNED withdrawals).
CREATE TABLE app.payout_accounts (
  id                          uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id                 uuid NOT NULL REFERENCES app.businesses (id),
  provider                    app.provider_code NOT NULL,
  channel_code                text NOT NULL,           -- provider bank/e-wallet channel code (to be verified)
  account_holder_name         text NOT NULL,
  account_number_last4        char(4) NOT NULL CHECK (account_number_last4 ~ '^[0-9]{4}$'),
  account_number_ciphertext   bytea,                   -- envelope-encrypted; decrypt only inside payouts worker
  status                      app.payout_account_status NOT NULL DEFAULT 'pending_verification',
  verification_method         text CHECK (verification_method IS NULL OR verification_method IN ('provider_name_validation', 'bank_document', 'provider_managed')),
  verified_at                 timestamptz,
  approval_request_id         uuid REFERENCES app.approval_requests (id),
  payouts_paused_until        timestamptz,             -- cooling-off after a change (fraud control)
  created_by                  uuid NOT NULL REFERENCES app.users (id),
  created_at                  timestamptz NOT NULL DEFAULT now(),
  updated_at                  timestamptz NOT NULL DEFAULT now(),
  disabled_at                 timestamptz
);
CREATE UNIQUE INDEX payout_accounts_one_verified ON app.payout_accounts (business_id) WHERE status = 'verified';

CREATE TABLE app.payments (
  id                           uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id                  uuid NOT NULL REFERENCES app.businesses (id),
  checkout_id                  uuid NOT NULL REFERENCES app.checkouts (id),
  user_id                      uuid REFERENCES app.users (id),
  provider                     app.provider_code NOT NULL,
  provider_account_id          text,                    -- for-user-id (Option A); NULL = platform master account (Option B)
  settlement_model             app.settlement_model NOT NULL,
  payment_method_code          text NOT NULL REFERENCES app.payment_method_types (code),
  payment_method_token_id      uuid REFERENCES app.payment_method_tokens (id),
  status                       app.payment_status NOT NULL DEFAULT 'created',
  attempt_no                   integer NOT NULL DEFAULT 1 CHECK (attempt_no BETWEEN 1 AND 10),
  amount_minor                 bigint NOT NULL CHECK (amount_minor > 0),
  currency                     char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  customer_fee_minor           bigint NOT NULL DEFAULT 0 CHECK (customer_fee_minor >= 0),   -- gateway fee charged to the customer
  provider_fee_minor           bigint CHECK (provider_fee_minor IS NULL OR provider_fee_minor >= 0),   -- actual, from provider/reconciliation
  provider_fee_vat_minor       bigint CHECK (provider_fee_vat_minor IS NULL OR provider_fee_vat_minor >= 0),
  split_rule_id                text,                    -- Xendit split rule id sent as with-split-rule
  split_amount_minor           bigint CHECK (split_amount_minor IS NULL OR split_amount_minor >= 0),
  split_status                 text CHECK (split_status IS NULL OR split_status IN ('pending', 'completed', 'failed')),
  provider_session_id          text,
  provider_payment_request_id  text,
  provider_payment_id          text,
  provider_reference_id        text NOT NULL UNIQUE,    -- our reference sent to the provider (= payments.id)
  provider_idempotency_key     text NOT NULL UNIQUE,    -- Idempotency-Key header used toward the provider
  provider_status              text,                    -- raw last-known provider status (diagnostic)
  checkout_url                 text,                    -- hosted checkout URL (short-lived)
  failure_code                 text,
  failure_message              text,
  retryable                    boolean,
  card_brand                   text,
  card_last4                   char(4) CHECK (card_last4 IS NULL OR card_last4 ~ '^[0-9]{4}$'),
  expires_at                   timestamptz NOT NULL,
  authorized_at                timestamptz,
  captured_at                  timestamptz,
  failed_at                    timestamptz,
  expired_at                   timestamptz,
  cancelled_at                 timestamptz,
  provider_settled_at          timestamptz,             -- "settlement date" report basis
  refunded_minor               bigint NOT NULL DEFAULT 0 CHECK (refunded_minor >= 0),
  disputed_minor               bigint NOT NULL DEFAULT 0 CHECK (disputed_minor >= 0),
  last_verified_at             timestamptz,             -- last authoritative provider re-query
  version                      integer NOT NULL DEFAULT 1,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT payments_refund_bound CHECK (refunded_minor <= amount_minor),
  CONSTRAINT payments_captured_at CHECK (
    status NOT IN ('captured', 'partially_refunded', 'refunded', 'disputed', 'chargeback') OR captured_at IS NOT NULL),
  CONSTRAINT payments_model_account CHECK (settlement_model <> 'provider_split' OR provider_account_id IS NOT NULL OR provider = 'mock'),
  UNIQUE (business_id, id)
);
CREATE UNIQUE INDEX payments_one_in_flight_per_checkout ON app.payments (checkout_id) WHERE status IN ('created', 'pending', 'authorized');
CREATE UNIQUE INDEX payments_provider_session_uniq ON app.payments (provider, provider_session_id) WHERE provider_session_id IS NOT NULL;
CREATE UNIQUE INDEX payments_provider_request_uniq ON app.payments (provider, provider_payment_request_id) WHERE provider_payment_request_id IS NOT NULL;
CREATE UNIQUE INDEX payments_provider_payment_uniq ON app.payments (provider, provider_payment_id) WHERE provider_payment_id IS NOT NULL;
CREATE INDEX payments_pending_sweep_idx ON app.payments (updated_at) WHERE status IN ('created', 'pending', 'authorized');
CREATE INDEX payments_business_captured_idx ON app.payments (business_id, captured_at) WHERE captured_at IS NOT NULL;
CREATE INDEX payments_checkout_idx ON app.payments (checkout_id);
CREATE INDEX payments_user_idx ON app.payments (user_id, created_at DESC) WHERE user_id IS NOT NULL;

-- Raw inbound provider notifications (untrusted until re-queried). Global table; business_id resolved when known.
-- Deduplication requires a GLOBAL unique key, so this table stays unpartitioned (doc 11 §9 partitioning plan).
CREATE TABLE app.webhook_events (
  id                   uuid PRIMARY KEY DEFAULT app.uuidv7(),
  provider             app.provider_code NOT NULL,
  provider_event_id    text NOT NULL,                   -- Xendit 'webhook-id' header (fallback: sha256 of body) — to be verified
  event_type           text NOT NULL,                   -- e.g. 'payment.capture', 'payment_session.completed', 'refund.succeeded'
  provider_account_id  text,                            -- sub-account id carried in the payload, if any
  business_id          uuid REFERENCES app.businesses (id),
  headers_redacted     jsonb NOT NULL,                  -- x-callback-token is NEVER stored
  payload_redacted     jsonb NOT NULL,                  -- PII fields removed before persistence
  payload_sha256       text NOT NULL CHECK (payload_sha256 ~ '^[0-9a-f]{64}$'),
  source_ip            inet,
  status               app.webhook_status NOT NULL DEFAULT 'received',
  attempts             integer NOT NULL DEFAULT 0,
  next_attempt_at      timestamptz,
  last_error           text,
  related_payment_id   uuid REFERENCES app.payments (id),
  received_at          timestamptz NOT NULL DEFAULT now(),
  processed_at         timestamptz,
  CONSTRAINT webhook_events_dedup UNIQUE (provider, provider_event_id)
);
CREATE INDEX webhook_events_work_idx ON app.webhook_events (next_attempt_at) WHERE status IN ('received', 'failed');
CREATE INDEX webhook_events_received_idx ON app.webhook_events (received_at);
CREATE INDEX webhook_events_payment_idx ON app.webhook_events (related_payment_id) WHERE related_payment_id IS NOT NULL;

CREATE TABLE app.payment_events (
  id                   uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id          uuid NOT NULL REFERENCES app.businesses (id),
  payment_id           uuid NOT NULL,
  source               app.payment_event_source NOT NULL,
  webhook_event_id     uuid REFERENCES app.webhook_events (id),
  provider_event_type  text,
  provider_status      text,
  from_status          app.payment_status,
  to_status            app.payment_status,              -- NULL when the event caused no transition (duplicate/ignored)
  amount_minor         bigint,
  details              jsonb NOT NULL DEFAULT '{}'::jsonb,   -- redacted
  correlation_id       text NOT NULL,
  occurred_at          timestamptz NOT NULL,
  created_at           timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT payment_events_payment_same_tenant FOREIGN KEY (business_id, payment_id) REFERENCES app.payments (business_id, id)
);
CREATE INDEX payment_events_payment_idx ON app.payment_events (payment_id, created_at);

CREATE TABLE app.refunds (
  id                          uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id                 uuid NOT NULL REFERENCES app.businesses (id),
  payment_id                  uuid NOT NULL,
  booking_id                  uuid,
  order_id                    uuid,                     -- FK added after orders
  event_registration_id       uuid,                     -- FK added after event_registrations
  checkout_item_id            uuid REFERENCES app.checkout_items (id),   -- NULL = whole-checkout refund
  refund_trigger              app.refund_trigger NOT NULL,
  status                      app.refund_status NOT NULL DEFAULT 'requested',
  destination                 app.refund_destination NOT NULL DEFAULT 'original_method',
  currency                    char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  amount_minor                bigint NOT NULL CHECK (amount_minor > 0),     -- total returned to the customer
  -- components (doc 09 §3); amount_minor = base + product + event + tax + gateway_fee refunds
  base_refund_minor           bigint NOT NULL DEFAULT 0 CHECK (base_refund_minor >= 0),
  product_refund_minor        bigint NOT NULL DEFAULT 0 CHECK (product_refund_minor >= 0),
  event_refund_minor          bigint NOT NULL DEFAULT 0 CHECK (event_refund_minor >= 0),
  tax_refund_minor            bigint NOT NULL DEFAULT 0 CHECK (tax_refund_minor >= 0),
  gateway_fee_refund_minor    bigint NOT NULL DEFAULT 0 CHECK (gateway_fee_refund_minor >= 0),
  commission_reversal_minor   bigint NOT NULL DEFAULT 0 CHECK (commission_reversal_minor >= 0),
  venue_share_minor           bigint NOT NULL DEFAULT 0,  -- charged to venue payable
  platform_share_minor        bigint NOT NULL DEFAULT 0,  -- absorbed by the platform (e.g. fee on venue-initiated refunds)
  policy_version_id           uuid REFERENCES app.cancellation_policy_versions (id),
  policy_tier                 jsonb,                    -- tier applied, e.g. {"min_hours_before":24,"refund_ppm":1000000}
  requested_by                uuid REFERENCES app.users (id),   -- NULL = system
  requested_at                timestamptz NOT NULL DEFAULT now(),
  reason                      text,
  approval_request_id         uuid REFERENCES app.approval_requests (id),
  provider_refund_id          text,
  provider_idempotency_key    text NOT NULL UNIQUE,
  provider_status             text,
  failure_code                text,
  failure_count               integer NOT NULL DEFAULT 0,
  after_payout                boolean NOT NULL DEFAULT false,   -- venue funds already paid out when requested
  succeeded_at                timestamptz,
  failed_at                   timestamptz,
  version                     integer NOT NULL DEFAULT 1,
  created_at                  timestamptz NOT NULL DEFAULT now(),
  updated_at                  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT refunds_payment_same_tenant FOREIGN KEY (business_id, payment_id) REFERENCES app.payments (business_id, id),
  CONSTRAINT refunds_booking_same_tenant FOREIGN KEY (business_id, booking_id) REFERENCES app.bookings (business_id, id),
  CONSTRAINT refunds_components_sum CHECK (
    amount_minor = base_refund_minor + product_refund_minor + event_refund_minor + tax_refund_minor + gateway_fee_refund_minor),
  CONSTRAINT refunds_shares_sum CHECK (
    venue_share_minor + platform_share_minor = amount_minor),
  CONSTRAINT refunds_succeeded_at CHECK ((status = 'succeeded') = (succeeded_at IS NOT NULL))
);
CREATE UNIQUE INDEX refunds_provider_refund_uniq ON app.refunds (provider_refund_id) WHERE provider_refund_id IS NOT NULL;
CREATE INDEX refunds_payment_idx ON app.refunds (payment_id);
CREATE INDEX refunds_business_idx ON app.refunds (business_id, requested_at DESC);
CREATE INDEX refunds_sync_idx ON app.refunds (updated_at) WHERE status IN ('approved', 'processing', 'failed');

CREATE TABLE app.disputes (
  id                    uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id           uuid NOT NULL REFERENCES app.businesses (id),
  payment_id            uuid NOT NULL,
  booking_id            uuid,
  provider_dispute_id   text,
  status                app.dispute_status NOT NULL DEFAULT 'open',
  reason_code           text,                           -- card-network reason code, as reported
  amount_minor          bigint NOT NULL CHECK (amount_minor > 0),
  fee_minor             bigint NOT NULL DEFAULT 0 CHECK (fee_minor >= 0),   -- provider dispute fee (provider-dependent)
  currency              char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  liability             app.liability_party NOT NULL DEFAULT 'venue',       -- configurable per agreement (doc 09 §6)
  liability_rule        text NOT NULL DEFAULT 'default_venue_bears_unless_platform_fault',
  opened_at             timestamptz NOT NULL,
  evidence_due_at       timestamptz,
  evidence_submitted_at timestamptz,
  evidence_upload_ids   uuid[] NOT NULL DEFAULT '{}',
  resolved_at           timestamptz,
  source                text NOT NULL CHECK (source IN ('webhook', 'provider_report', 'manual_entry')),
  notes                 text,
  version               integer NOT NULL DEFAULT 1,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT disputes_payment_same_tenant FOREIGN KEY (business_id, payment_id) REFERENCES app.payments (business_id, id),
  CONSTRAINT disputes_resolution CHECK ((status IN ('won', 'lost')) = (resolved_at IS NOT NULL))
);
CREATE UNIQUE INDEX disputes_provider_uniq ON app.disputes (provider_dispute_id) WHERE provider_dispute_id IS NOT NULL;
CREATE INDEX disputes_open_idx ON app.disputes (evidence_due_at) WHERE status IN ('open', 'evidence_submitted');
CREATE INDEX disputes_business_idx ON app.disputes (business_id, opened_at DESC);

CREATE TABLE app.commissions (
  id                       uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id              uuid NOT NULL REFERENCES app.businesses (id),
  checkout_item_id         uuid NOT NULL UNIQUE REFERENCES app.checkout_items (id),
  booking_id               uuid,
  payment_id               uuid NOT NULL,
  commission_agreement_id  uuid NOT NULL REFERENCES app.commission_agreements (id),
  rate_ppm                 integer NOT NULL CHECK (rate_ppm BETWEEN 0 AND 1000000),
  base_minor               bigint NOT NULL CHECK (base_minor >= 0),
  amount_minor             bigint NOT NULL CHECK (amount_minor >= 0),
  reversed_minor           bigint NOT NULL DEFAULT 0 CHECK (reversed_minor >= 0),
  status                   app.commission_status NOT NULL DEFAULT 'accrued',
  currency                 char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  accrued_at               timestamptz NOT NULL DEFAULT now(),
  created_at               timestamptz NOT NULL DEFAULT now(),
  updated_at               timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT commissions_payment_same_tenant FOREIGN KEY (business_id, payment_id) REFERENCES app.payments (business_id, id),
  CONSTRAINT commissions_reversal_bound CHECK (reversed_minor <= amount_minor)
);
CREATE INDEX commissions_business_idx ON app.commissions (business_id, accrued_at);

-- -----------------------------------------------------------------------------
-- 3.11 Settlement, payouts, ledger (doc 09)
-- -----------------------------------------------------------------------------

CREATE TABLE app.settlements (
  id                       uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id              uuid NOT NULL REFERENCES app.businesses (id),
  settlement_model         app.settlement_model NOT NULL,
  period_start             timestamptz NOT NULL,
  period_end               timestamptz NOT NULL,
  status                   app.settlement_status NOT NULL DEFAULT 'draft',
  currency                 char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  opening_balance_minor    bigint NOT NULL DEFAULT 0,   -- negative = receivable carried from previous statement
  gross_sales_minor        bigint NOT NULL DEFAULT 0,
  venue_discounts_minor    bigint NOT NULL DEFAULT 0,
  commission_minor         bigint NOT NULL DEFAULT 0,
  venue_fee_minor          bigint NOT NULL DEFAULT 0,   -- gateway fees borne by the venue (if configured)
  refunds_minor            bigint NOT NULL DEFAULT 0,   -- venue share of refunds
  chargebacks_minor        bigint NOT NULL DEFAULT 0,
  adjustments_minor        bigint NOT NULL DEFAULT 0,   -- signed (+ credit to venue, - debit)
  withholding_tax_minor    bigint NOT NULL DEFAULT 0,
  net_payable_minor        bigint NOT NULL DEFAULT 0,
  paid_minor               bigint NOT NULL DEFAULT 0,
  closing_balance_minor    bigint NOT NULL DEFAULT 0,
  statement_upload_id      uuid REFERENCES app.uploads (id),
  generated_at             timestamptz NOT NULL DEFAULT now(),
  finalized_at             timestamptz,
  finalized_by             uuid REFERENCES app.users (id),
  version                  integer NOT NULL DEFAULT 1,
  created_at               timestamptz NOT NULL DEFAULT now(),
  updated_at               timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT settlements_period CHECK (period_end > period_start),
  CONSTRAINT settlements_net_formula CHECK (
    net_payable_minor = opening_balance_minor + gross_sales_minor - venue_discounts_minor - commission_minor
                        - venue_fee_minor - refunds_minor - chargebacks_minor + adjustments_minor - withholding_tax_minor),
  CONSTRAINT settlements_closing_formula CHECK (closing_balance_minor = net_payable_minor - paid_minor),
  UNIQUE (business_id, period_start, period_end),
  UNIQUE (business_id, id)
);

CREATE TABLE app.payouts (
  id                     uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id            uuid NOT NULL REFERENCES app.businesses (id),
  settlement_id          uuid,
  payout_kind            app.payout_kind NOT NULL,
  provider               app.provider_code NOT NULL,
  provider_account_id    text,                          -- for-user-id when withdrawing from a sub-account
  provider_payout_id     text,
  payout_account_id      uuid REFERENCES app.payout_accounts (id),
  status                 app.payout_status NOT NULL DEFAULT 'scheduled',
  amount_minor           bigint NOT NULL CHECK (amount_minor > 0),
  currency               char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  provider_idempotency_key text NOT NULL UNIQUE,
  scheduled_for          date NOT NULL,
  requested_at           timestamptz,
  paid_at                timestamptz,                   -- "payout date" report basis
  failed_at              timestamptz,
  failure_code           text,
  reversed_at            timestamptz,
  reversal_reason        text,
  retry_of_payout_id     uuid REFERENCES app.payouts (id),
  version                integer NOT NULL DEFAULT 1,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT payouts_settlement_same_tenant FOREIGN KEY (business_id, settlement_id) REFERENCES app.settlements (business_id, id),
  CONSTRAINT payouts_paid_at CHECK (status NOT IN ('paid', 'reversed') OR paid_at IS NOT NULL),
  CONSTRAINT payouts_destination CHECK (payout_account_id IS NOT NULL OR provider_account_id IS NOT NULL),
  UNIQUE (business_id, id)
);
CREATE UNIQUE INDEX payouts_provider_uniq ON app.payouts (provider, provider_payout_id) WHERE provider_payout_id IS NOT NULL;
CREATE INDEX payouts_sync_idx ON app.payouts (updated_at) WHERE status IN ('scheduled', 'processing');
CREATE INDEX payouts_business_idx ON app.payouts (business_id, scheduled_for DESC);

-- Chart of accounts. Codes are the brief's canonical account names; one payable account per business.
CREATE TABLE app.ledger_accounts (
  code            text PRIMARY KEY,
  account_type    app.ledger_account_type NOT NULL,
  normal_balance  app.ledger_direction NOT NULL,
  owner           text NOT NULL CHECK (owner IN ('platform', 'venue')),
  business_id     uuid REFERENCES app.businesses (id),
  currency        char(3) NOT NULL DEFAULT 'PHP' CHECK (currency ~ '^[A-Z]{3}$'),
  description     text NOT NULL,
  is_active       boolean NOT NULL DEFAULT true,
  created_at      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ledger_accounts_code_shape CHECK (
       (owner = 'platform' AND business_id IS NULL AND code ~ '^platform:[a-z_]+$')
    OR (owner = 'venue' AND business_id IS NOT NULL AND code = 'venue:' || business_id::text || ':payable'))
);

-- Journal header. idempotency_key makes every posting exactly-once (e.g. 'capture:{payment_id}', 'refund:{refund_id}').
CREATE TABLE app.ledger_journals (
  id                   uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id          uuid REFERENCES app.businesses (id),   -- tenant the journal concerns (NULL = platform-only)
  journal_type         text NOT NULL CHECK (journal_type IN (
                         'capture', 'provider_fee', 'fee_variance', 'refund', 'commission_reversal',
                         'payout', 'payout_failed', 'payout_reversed', 'dispute_adjustment', 'chargeback', 'dispute_won',
                         'dispute_fee', 'manual_adjustment', 'withholding', 'reversal', 'receivable_offset')),
  source_type          text NOT NULL,                   -- 'payment' | 'refund' | 'payout' | 'dispute' | 'approval_request' | 'settlement'
  source_id            uuid NOT NULL,
  idempotency_key      text NOT NULL UNIQUE,
  reverses_journal_id  uuid UNIQUE REFERENCES app.ledger_journals (id),
  approval_request_id  uuid REFERENCES app.approval_requests (id),
  effective_at         timestamptz NOT NULL,            -- accounting date (e.g. captured_at)
  posted_at            timestamptz NOT NULL DEFAULT now(),
  posted_by            uuid REFERENCES app.users (id),  -- NULL = system
  memo                 text,
  correlation_id       text NOT NULL,
  CONSTRAINT ledger_journals_manual_needs_approval CHECK (journal_type <> 'manual_adjustment' OR approval_request_id IS NOT NULL),
  CONSTRAINT ledger_journals_reversal_link CHECK ((journal_type = 'reversal') = (reverses_journal_id IS NOT NULL))
);
CREATE INDEX ledger_journals_source_idx ON app.ledger_journals (source_type, source_id);
CREATE INDEX ledger_journals_business_idx ON app.ledger_journals (business_id, effective_at);

-- Lines. Append-only; each journal balances per currency (deferred constraint trigger, section 4).
-- Kept unpartitioned in the reference schema; monthly partitioning plan in doc 11 §9.
CREATE TABLE app.financial_ledger_entries (
  id                uuid PRIMARY KEY DEFAULT app.uuidv7(),
  journal_id        uuid NOT NULL REFERENCES app.ledger_journals (id),
  business_id       uuid REFERENCES app.businesses (id),
  account_code      text NOT NULL REFERENCES app.ledger_accounts (code),
  entry_type        app.ledger_entry_type NOT NULL,
  direction         app.ledger_direction NOT NULL,
  amount_minor      bigint NOT NULL CHECK (amount_minor > 0),
  currency          char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  payment_id        uuid REFERENCES app.payments (id),
  refund_id         uuid REFERENCES app.refunds (id),
  payout_id         uuid REFERENCES app.payouts (id),
  dispute_id        uuid REFERENCES app.disputes (id),
  booking_id        uuid REFERENCES app.bookings (id),
  checkout_item_id  uuid REFERENCES app.checkout_items (id),
  memo              text,
  posted_at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX fle_journal_idx ON app.financial_ledger_entries (journal_id);
CREATE INDEX fle_account_time_idx ON app.financial_ledger_entries (account_code, posted_at);
CREATE INDEX fle_business_time_idx ON app.financial_ledger_entries (business_id, posted_at) WHERE business_id IS NOT NULL;
CREATE INDEX fle_payment_idx ON app.financial_ledger_entries (payment_id) WHERE payment_id IS NOT NULL;
CREATE INDEX fle_refund_idx ON app.financial_ledger_entries (refund_id) WHERE refund_id IS NOT NULL;
CREATE INDEX fle_payout_idx ON app.financial_ledger_entries (payout_id) WHERE payout_id IS NOT NULL;

CREATE TABLE app.settlement_lines (
  id                     uuid PRIMARY KEY DEFAULT app.uuidv7(),
  settlement_id          uuid NOT NULL,
  business_id            uuid NOT NULL REFERENCES app.businesses (id),
  line_type              text NOT NULL CHECK (line_type IN (
                           'booking', 'product', 'event', 'venue_discount', 'commission', 'venue_fee', 'refund',
                           'commission_reversal', 'chargeback', 'dispute_reversal', 'adjustment', 'withholding',
                           'payout', 'failed_payout', 'carry_forward')),
  ledger_entry_id        uuid REFERENCES app.financial_ledger_entries (id),
  booking_id             uuid REFERENCES app.bookings (id),
  payment_id             uuid REFERENCES app.payments (id),
  refund_id              uuid REFERENCES app.refunds (id),
  payout_id              uuid REFERENCES app.payouts (id),
  description            text NOT NULL,
  -- every date basis is carried separately and never mixed (doc 09 §9)
  booking_created_at     timestamptz,
  play_starts_at         timestamptz,
  payment_captured_at    timestamptz,
  provider_settled_at    timestamptz,
  refund_succeeded_at    timestamptz,
  payout_paid_at         timestamptz,
  amount_minor           bigint NOT NULL,                -- signed effect on the venue balance
  currency               char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  created_at             timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT settlement_lines_settlement_same_tenant FOREIGN KEY (business_id, settlement_id) REFERENCES app.settlements (business_id, id)
);
CREATE INDEX settlement_lines_settlement_idx ON app.settlement_lines (settlement_id);

CREATE TABLE app.reconciliation_runs (
  id                   uuid PRIMARY KEY DEFAULT app.uuidv7(),
  run_type             app.recon_run_type NOT NULL,
  provider             app.provider_code NOT NULL,
  provider_account_id  text,                            -- NULL = master + all sub-accounts
  window_start         timestamptz NOT NULL,
  window_end           timestamptz NOT NULL,
  status               app.recon_run_status NOT NULL DEFAULT 'running',
  stats                jsonb NOT NULL DEFAULT '{}'::jsonb,   -- counts per class, matched totals
  report_upload_id     uuid REFERENCES app.uploads (id),     -- provider report file retained for audit
  started_at           timestamptz NOT NULL DEFAULT now(),
  finished_at          timestamptz,
  error                text,
  CONSTRAINT reconciliation_runs_window CHECK (window_end > window_start)
);
CREATE UNIQUE INDEX reconciliation_runs_daily_uniq ON app.reconciliation_runs (run_type, provider, coalesce(provider_account_id, ''), window_start)
  WHERE run_type = 'daily_provider_report' AND status <> 'failed';

CREATE TABLE app.reconciliation_exceptions (
  id                     uuid PRIMARY KEY DEFAULT app.uuidv7(),
  run_id                 uuid NOT NULL REFERENCES app.reconciliation_runs (id),
  business_id            uuid REFERENCES app.businesses (id),
  exception_class        app.recon_exception_class NOT NULL,
  status                 app.recon_exception_status NOT NULL DEFAULT 'open',
  payment_id             uuid REFERENCES app.payments (id),
  refund_id              uuid REFERENCES app.refunds (id),
  payout_id              uuid REFERENCES app.payouts (id),
  provider_reference     text,
  internal_amount_minor  bigint,
  provider_amount_minor  bigint,
  currency               char(3) CHECK (currency IS NULL OR currency ~ '^[A-Z]{3}$'),
  details                jsonb NOT NULL DEFAULT '{}'::jsonb,
  auto_heal_action       text,                          -- e.g. 'requeried_and_transitioned', 'posted_fee_variance'
  resolved_by            uuid REFERENCES app.users (id),
  resolved_at            timestamptz,
  resolution_note        text,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX reconciliation_exceptions_open_idx ON app.reconciliation_exceptions (exception_class, created_at) WHERE status IN ('open', 'escalated');
CREATE INDEX reconciliation_exceptions_business_idx ON app.reconciliation_exceptions (business_id) WHERE business_id IS NOT NULL;

-- -----------------------------------------------------------------------------
-- 3.12 Events — registrations, waitlists, teams, matches; ratings
-- -----------------------------------------------------------------------------

CREATE TABLE app.event_registrations (
  id               uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id      uuid NOT NULL REFERENCES app.businesses (id),
  event_id         uuid NOT NULL,
  division_id      uuid NOT NULL REFERENCES app.event_divisions (id),
  user_id          uuid NOT NULL REFERENCES app.users (id),
  team_id          uuid,                                 -- FK added after teams
  status           app.event_registration_status NOT NULL DEFAULT 'held',
  checkout_id      uuid REFERENCES app.checkouts (id),
  hold_expires_at  timestamptz,                          -- 'held' / 'offered' expiry
  fee_minor        bigint NOT NULL CHECK (fee_minor >= 0),
  currency         char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  confirmed_at     timestamptz,
  checked_in_at    timestamptz,
  checked_in_by    uuid REFERENCES app.users (id),
  withdrawn_at     timestamptz,
  cancelled_at     timestamptz,
  refunded_at      timestamptz,
  version          integer NOT NULL DEFAULT 1,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT event_registrations_event_same_tenant FOREIGN KEY (business_id, event_id) REFERENCES app.events (business_id, id),
  CONSTRAINT event_registrations_hold CHECK (status NOT IN ('held', 'offered') OR hold_expires_at IS NOT NULL),
  UNIQUE (business_id, id)
);
CREATE UNIQUE INDEX event_registrations_one_live_per_user ON app.event_registrations (event_id, user_id)
  WHERE status NOT IN ('withdrawn', 'cancelled', 'refunded');
CREATE INDEX event_registrations_division_idx ON app.event_registrations (division_id, status);
CREATE INDEX event_registrations_user_idx ON app.event_registrations (user_id, created_at DESC);
CREATE INDEX event_registrations_hold_expiry_idx ON app.event_registrations (hold_expires_at) WHERE status IN ('held', 'offered');

CREATE TABLE app.event_waitlists (
  id                uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id       uuid NOT NULL REFERENCES app.businesses (id),
  event_id          uuid NOT NULL,
  division_id       uuid NOT NULL REFERENCES app.event_divisions (id),
  user_id           uuid NOT NULL REFERENCES app.users (id),
  status            app.waitlist_status NOT NULL DEFAULT 'waiting',
  joined_at         timestamptz NOT NULL DEFAULT now(),  -- FIFO order
  offered_at        timestamptz,
  offer_expires_at  timestamptz,
  registration_id   uuid REFERENCES app.event_registrations (id),
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT event_waitlists_event_same_tenant FOREIGN KEY (business_id, event_id) REFERENCES app.events (business_id, id),
  CONSTRAINT event_waitlists_offer CHECK (status <> 'offered' OR (offered_at IS NOT NULL AND offer_expires_at > offered_at))
);
CREATE UNIQUE INDEX event_waitlists_one_live_per_user ON app.event_waitlists (division_id, user_id) WHERE status IN ('waiting', 'offered');
CREATE INDEX event_waitlists_queue_idx ON app.event_waitlists (division_id, joined_at) WHERE status = 'waiting';
CREATE INDEX event_waitlists_offer_expiry_idx ON app.event_waitlists (offer_expires_at) WHERE status = 'offered';

CREATE TABLE app.teams (
  id               uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id      uuid NOT NULL REFERENCES app.businesses (id),
  event_id         uuid NOT NULL,
  division_id      uuid REFERENCES app.event_divisions (id),
  name             text NOT NULL,
  captain_user_id  uuid NOT NULL REFERENCES app.users (id),
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT teams_event_same_tenant FOREIGN KEY (business_id, event_id) REFERENCES app.events (business_id, id)
);
CREATE UNIQUE INDEX teams_name_per_event ON app.teams (event_id, lower(name));
ALTER TABLE app.event_registrations ADD CONSTRAINT event_registrations_team_fk FOREIGN KEY (team_id) REFERENCES app.teams (id);

CREATE TABLE app.team_members (
  team_id       uuid NOT NULL REFERENCES app.teams (id) ON DELETE CASCADE,
  user_id       uuid NOT NULL REFERENCES app.users (id),
  business_id   uuid NOT NULL REFERENCES app.businesses (id),
  role          text NOT NULL DEFAULT 'member' CHECK (role IN ('captain', 'member')),
  status        text NOT NULL DEFAULT 'invited' CHECK (status IN ('invited', 'accepted', 'declined', 'removed')),
  invited_at    timestamptz NOT NULL DEFAULT now(),
  responded_at  timestamptz,
  PRIMARY KEY (team_id, user_id)
);

CREATE TABLE app.matches (
  id              uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id     uuid NOT NULL REFERENCES app.businesses (id),
  event_id        uuid NOT NULL,
  division_id     uuid REFERENCES app.event_divisions (id),
  court_id        uuid REFERENCES app.courts (id),
  round_no        integer NOT NULL CHECK (round_no > 0),
  match_no        integer NOT NULL CHECK (match_no > 0),
  scheduled_at    timestamptz,
  team_a_id       uuid REFERENCES app.teams (id),
  team_b_id       uuid REFERENCES app.teams (id),
  score           jsonb,                                  -- [{"game":1,"a":11,"b":7}, ...]
  winner_team_id  uuid REFERENCES app.teams (id),
  status          app.match_status NOT NULL DEFAULT 'scheduled',
  recorded_by     uuid REFERENCES app.users (id),
  verified_by     uuid REFERENCES app.users (id),         -- "officially recorded" = verified by organizer/referee
  recorded_at     timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT matches_event_same_tenant FOREIGN KEY (business_id, event_id) REFERENCES app.events (business_id, id),
  CONSTRAINT matches_distinct_teams CHECK (team_a_id IS NULL OR team_b_id IS NULL OR team_a_id <> team_b_id),
  CONSTRAINT matches_winner_is_participant CHECK (winner_team_id IS NULL OR winner_team_id IN (team_a_id, team_b_id))
);
CREATE UNIQUE INDEX matches_slot_uniq ON app.matches (event_id, coalesce(division_id, '00000000-0000-0000-0000-000000000000'::uuid), round_no, match_no);

-- Ratings are labelled by source; no invented "official" rating (product brief §7).
CREATE TABLE app.player_ratings (
  id            uuid PRIMARY KEY DEFAULT app.uuidv7(),
  user_id       uuid NOT NULL REFERENCES app.users (id) ON DELETE CASCADE,
  source        app.rating_source NOT NULL,
  provider      text,                                     -- external provider code (Phase 2, official API + user authorization)
  business_id   uuid REFERENCES app.businesses (id),      -- venue_verified: the verifying business
  rating_value  numeric(6, 3),
  rating_label  text,
  visibility    app.visibility_level NOT NULL DEFAULT 'private',
  verified_by   uuid REFERENCES app.users (id),
  external_ref  text,
  as_of         timestamptz NOT NULL DEFAULT now(),
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT player_ratings_source_shape CHECK (
       (source = 'external_provider' AND provider IS NOT NULL)
    OR (source = 'venue_verified' AND business_id IS NOT NULL AND verified_by IS NOT NULL)
    OR (source IN ('self_declared', 'platform_recreational')))
);
CREATE UNIQUE INDEX player_ratings_uniq ON app.player_ratings (
  user_id, source, coalesce(provider, ''), coalesce(business_id, '00000000-0000-0000-0000-000000000000'::uuid));

CREATE TABLE app.rating_history (
  id                uuid PRIMARY KEY DEFAULT app.uuidv7(),
  player_rating_id  uuid NOT NULL REFERENCES app.player_ratings (id) ON DELETE CASCADE,
  user_id           uuid NOT NULL REFERENCES app.users (id) ON DELETE CASCADE,
  source            app.rating_source NOT NULL,
  rating_value      numeric(6, 3),
  rating_label      text,
  match_id          uuid REFERENCES app.matches (id),
  recorded_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX rating_history_user_idx ON app.rating_history (user_id, recorded_at);

-- -----------------------------------------------------------------------------
-- 3.13 Products & orders (tenant)
-- -----------------------------------------------------------------------------

CREATE TABLE app.products (
  id                   uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id          uuid NOT NULL REFERENCES app.businesses (id),
  venue_id             uuid NOT NULL REFERENCES app.venues (id),
  category_code        text NOT NULL REFERENCES app.product_categories (code),
  name                 text NOT NULL,
  description          text,
  status               app.product_status NOT NULL DEFAULT 'draft',
  price_minor          bigint NOT NULL CHECK (price_minor >= 0),
  currency             char(3) NOT NULL DEFAULT 'PHP' CHECK (currency ~ '^[A-Z]{3}$'),
  tax_treatment        app.tax_treatment NOT NULL DEFAULT 'vat_inclusive',
  fulfillment_modes    text[] NOT NULL DEFAULT ARRAY['pickup_only']::text[]
                         CHECK (cardinality(fulfillment_modes) >= 1
                                AND fulfillment_modes <@ ARRAY['pickup_only', 'booking_addon', 'event_addon', 'standalone']::text[]),
  max_qty_per_order    integer NOT NULL DEFAULT 10 CHECK (max_qty_per_order BETWEEN 1 AND 100),
  pickup_instructions  text,
  availability         jsonb NOT NULL DEFAULT '{}'::jsonb,   -- weekly schedule in venue local time
  track_inventory      boolean NOT NULL DEFAULT true,
  image_upload_ids     uuid[] NOT NULL DEFAULT '{}',
  created_by           uuid NOT NULL REFERENCES app.users (id),
  version              integer NOT NULL DEFAULT 1,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  deleted_at           timestamptz,
  UNIQUE (business_id, id)
);
CREATE INDEX products_venue_idx ON app.products (venue_id, status) WHERE deleted_at IS NULL;
CREATE INDEX products_name_trgm ON app.products USING gin (name extensions.gin_trgm_ops);

CREATE TABLE app.product_variants (
  id              uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id     uuid NOT NULL REFERENCES app.businesses (id),
  product_id      uuid NOT NULL,
  sku             text NOT NULL,
  name            text NOT NULL,
  price_minor     bigint CHECK (price_minor IS NULL OR price_minor >= 0),   -- NULL = product price
  stock_on_hand   integer NOT NULL DEFAULT 0,
  stock_reserved  integer NOT NULL DEFAULT 0,
  status          app.product_status NOT NULL DEFAULT 'active',
  version         integer NOT NULL DEFAULT 1,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT product_variants_product_same_tenant FOREIGN KEY (business_id, product_id) REFERENCES app.products (business_id, id),
  CONSTRAINT product_variants_stock CHECK (stock_on_hand >= 0 AND stock_reserved >= 0 AND stock_reserved <= stock_on_hand),
  UNIQUE (business_id, sku),
  UNIQUE (business_id, id)
);
CREATE INDEX product_variants_product_idx ON app.product_variants (product_id);

CREATE TABLE app.orders (
  id                     uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id            uuid NOT NULL REFERENCES app.businesses (id),
  venue_id               uuid NOT NULL REFERENCES app.venues (id),
  user_id                uuid REFERENCES app.users (id),
  checkout_id            uuid NOT NULL REFERENCES app.checkouts (id),
  booking_id             uuid,                           -- set when purchased as a booking add-on
  event_registration_id  uuid,                           -- set when purchased as an event add-on
  status                 app.order_status NOT NULL DEFAULT 'pending_payment',
  claim_code             text NOT NULL CHECK (claim_code ~ '^[0-9A-HJKMNP-TV-Z]{8}$'),
  subtotal_minor         bigint NOT NULL CHECK (subtotal_minor >= 0),
  discount_minor         bigint NOT NULL DEFAULT 0 CHECK (discount_minor >= 0),
  tax_exclusive_minor    bigint NOT NULL DEFAULT 0 CHECK (tax_exclusive_minor >= 0),
  total_minor            bigint NOT NULL CHECK (total_minor >= 0),
  refunded_minor         bigint NOT NULL DEFAULT 0 CHECK (refunded_minor >= 0),
  currency               char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  paid_at                timestamptz,
  preparing_at           timestamptz,
  ready_at               timestamptz,
  claimed_at             timestamptz,
  cancelled_at           timestamptz,
  cancellation_reason    text,
  version                integer NOT NULL DEFAULT 1,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT orders_booking_same_tenant FOREIGN KEY (business_id, booking_id) REFERENCES app.bookings (business_id, id),
  CONSTRAINT orders_registration_same_tenant FOREIGN KEY (business_id, event_registration_id) REFERENCES app.event_registrations (business_id, id),
  CONSTRAINT orders_total_formula CHECK (total_minor = subtotal_minor - discount_minor + tax_exclusive_minor),
  CONSTRAINT orders_refund_bound CHECK (refunded_minor <= total_minor),
  CONSTRAINT orders_claimed_at CHECK ((status = 'claimed') = (claimed_at IS NOT NULL)),
  UNIQUE (business_id, claim_code),
  UNIQUE (business_id, id)
);
CREATE INDEX orders_venue_status_idx ON app.orders (venue_id, status, created_at);
CREATE INDEX orders_user_idx ON app.orders (user_id, created_at DESC) WHERE user_id IS NOT NULL;
CREATE INDEX orders_checkout_idx ON app.orders (checkout_id);

CREATE TABLE app.order_items (
  id                   uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id          uuid NOT NULL REFERENCES app.businesses (id),
  order_id             uuid NOT NULL,
  product_id           uuid NOT NULL,
  variant_id           uuid,
  name_snapshot        text NOT NULL,
  quantity             integer NOT NULL CHECK (quantity > 0),
  unit_price_minor     bigint NOT NULL CHECK (unit_price_minor >= 0),
  discount_minor       bigint NOT NULL DEFAULT 0 CHECK (discount_minor >= 0),
  tax_exclusive_minor  bigint NOT NULL DEFAULT 0 CHECK (tax_exclusive_minor >= 0),
  vat_included_minor   bigint NOT NULL DEFAULT 0 CHECK (vat_included_minor >= 0),
  total_minor          bigint NOT NULL CHECK (total_minor >= 0),
  refunded_quantity    integer NOT NULL DEFAULT 0,
  refunded_minor       bigint NOT NULL DEFAULT 0 CHECK (refunded_minor >= 0),
  currency             char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT order_items_order_same_tenant   FOREIGN KEY (business_id, order_id)   REFERENCES app.orders (business_id, id),
  CONSTRAINT order_items_product_same_tenant FOREIGN KEY (business_id, product_id) REFERENCES app.products (business_id, id),
  CONSTRAINT order_items_variant_same_tenant FOREIGN KEY (business_id, variant_id) REFERENCES app.product_variants (business_id, id),
  CONSTRAINT order_items_total_formula CHECK (total_minor = unit_price_minor * quantity - discount_minor + tax_exclusive_minor),
  CONSTRAINT order_items_refund_bounds CHECK (refunded_quantity BETWEEN 0 AND quantity AND refunded_minor <= total_minor)
);
CREATE INDEX order_items_order_idx ON app.order_items (order_id);

ALTER TABLE app.checkout_items ADD CONSTRAINT checkout_items_order_item_fk FOREIGN KEY (order_item_id) REFERENCES app.order_items (id);
ALTER TABLE app.checkout_items ADD CONSTRAINT checkout_items_event_registration_fk FOREIGN KEY (event_registration_id) REFERENCES app.event_registrations (id);
ALTER TABLE app.refunds ADD CONSTRAINT refunds_order_fk FOREIGN KEY (order_id) REFERENCES app.orders (id);
ALTER TABLE app.refunds ADD CONSTRAINT refunds_event_registration_fk FOREIGN KEY (event_registration_id) REFERENCES app.event_registrations (id);

CREATE TABLE app.inventory_movements (
  id              uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id     uuid NOT NULL REFERENCES app.businesses (id),
  variant_id      uuid NOT NULL,
  movement_type   app.inventory_movement_type NOT NULL,
  quantity        integer NOT NULL CHECK (quantity <> 0),   -- signed effect on on_hand (sale/write_off negative) or reserved
  on_hand_after   integer NOT NULL CHECK (on_hand_after >= 0),
  reserved_after  integer NOT NULL CHECK (reserved_after >= 0),
  order_item_id   uuid REFERENCES app.order_items (id),
  reason          text,
  created_by      uuid REFERENCES app.users (id),         -- NULL = system (checkout reservation/expiry)
  created_at      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT inventory_movements_variant_same_tenant FOREIGN KEY (business_id, variant_id) REFERENCES app.product_variants (business_id, id)
);
CREATE INDEX inventory_movements_variant_idx ON app.inventory_movements (variant_id, created_at);

-- One claim per order => an order can never be claimed twice (QR or code).
CREATE TABLE app.pickup_claims (
  id            uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id   uuid NOT NULL REFERENCES app.businesses (id),
  order_id      uuid NOT NULL UNIQUE,
  claimed_by    uuid NOT NULL REFERENCES app.users (id),
  method        text NOT NULL CHECK (method IN ('qr', 'claim_code', 'manual')),
  claimed_at    timestamptz NOT NULL DEFAULT now(),
  notes         text,
  CONSTRAINT pickup_claims_order_same_tenant FOREIGN KEY (business_id, order_id) REFERENCES app.orders (business_id, id)
);

-- -----------------------------------------------------------------------------
-- 3.14 Trust, safety & reviews
-- -----------------------------------------------------------------------------

-- level 'platform' rows have business_id NULL and are managed only with platform.restrictions.manage.
CREATE TABLE app.venue_user_restrictions (
  id                         uuid PRIMARY KEY DEFAULT app.uuidv7(),
  level                      app.restriction_level NOT NULL,
  business_id                uuid REFERENCES app.businesses (id),
  venue_id                   uuid REFERENCES app.venues (id),
  user_id                    uuid NOT NULL REFERENCES app.users (id),
  reason_category            app.restriction_reason_category NOT NULL,
  internal_notes_ciphertext  bytea,                       -- envelope-encrypted; decrypted only with restrictions.manage
  incident_ref               text,
  evidence_upload_ids        uuid[] NOT NULL DEFAULT '{}',
  blocks_bookings            boolean NOT NULL DEFAULT true,
  blocks_event_registration  boolean NOT NULL DEFAULT true,
  starts_at                  timestamptz NOT NULL DEFAULT now(),
  ends_at                    timestamptz,                 -- NULL = permanent
  status                     app.restriction_status NOT NULL DEFAULT 'active',
  appeal_status              app.appeal_status NOT NULL DEFAULT 'none',
  appeal_submitted_at        timestamptz,
  appeal_decided_by          uuid REFERENCES app.users (id),
  appeal_decided_at          timestamptz,
  created_by                 uuid NOT NULL REFERENCES app.users (id),
  approved_by                uuid REFERENCES app.users (id),
  lifted_at                  timestamptz,
  lifted_by                  uuid REFERENCES app.users (id),
  lift_reason                text,
  version                    integer NOT NULL DEFAULT 1,
  created_at                 timestamptz NOT NULL DEFAULT now(),
  updated_at                 timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT restrictions_level_shape CHECK (
       (level = 'platform' AND business_id IS NULL AND venue_id IS NULL)
    OR (level = 'business' AND business_id IS NOT NULL AND venue_id IS NULL)
    OR (level = 'venue'    AND business_id IS NOT NULL AND venue_id IS NOT NULL)),
  CONSTRAINT restrictions_period CHECK (ends_at IS NULL OR ends_at > starts_at),
  CONSTRAINT restrictions_lifted CHECK ((status = 'lifted') = (lifted_at IS NOT NULL AND lifted_by IS NOT NULL))
);
CREATE INDEX restrictions_active_user_idx ON app.venue_user_restrictions (user_id, business_id) WHERE status = 'active';
CREATE INDEX restrictions_business_idx ON app.venue_user_restrictions (business_id, created_at DESC) WHERE business_id IS NOT NULL;
CREATE INDEX restrictions_expiry_idx ON app.venue_user_restrictions (ends_at) WHERE status = 'active' AND ends_at IS NOT NULL;

-- A review requires a verified completed booking; one review per booking.
CREATE TABLE app.reviews (
  id                 uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id        uuid NOT NULL REFERENCES app.businesses (id),
  venue_id           uuid NOT NULL REFERENCES app.venues (id),
  booking_id         uuid NOT NULL UNIQUE,
  user_id            uuid NOT NULL REFERENCES app.users (id),
  reviewer_display_name text NOT NULL,                  -- snapshot (e.g. 'Juan D.'); profiles are never publicly readable
  rating             smallint NOT NULL CHECK (rating BETWEEN 1 AND 5),
  title              text CHECK (title IS NULL OR length(title) <= 120),
  body               text CHECK (body IS NULL OR length(body) <= 4000),
  status             app.review_status NOT NULL DEFAULT 'published',
  business_response  text CHECK (business_response IS NULL OR length(business_response) <= 2000),
  responded_by       uuid REFERENCES app.users (id),
  responded_at       timestamptz,
  moderated_by       uuid REFERENCES app.users (id),
  moderated_at       timestamptz,
  moderation_reason  text,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT reviews_booking_same_tenant FOREIGN KEY (business_id, booking_id) REFERENCES app.bookings (business_id, id)
);
CREATE INDEX reviews_venue_idx ON app.reviews (venue_id, created_at DESC) WHERE status = 'published';

CREATE TABLE app.reports (
  id                uuid PRIMARY KEY DEFAULT app.uuidv7(),
  reporter_user_id  uuid NOT NULL REFERENCES app.users (id),
  target_type       app.report_target_type NOT NULL,
  target_id         uuid NOT NULL,
  business_id       uuid REFERENCES app.businesses (id),  -- tenant owning the target, when applicable
  reason_code       text NOT NULL,
  details           text CHECK (details IS NULL OR length(details) <= 4000),
  status            app.report_status NOT NULL DEFAULT 'open',
  assigned_to       uuid REFERENCES app.users (id),
  resolution        text,
  resolved_at       timestamptz,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX reports_queue_idx ON app.reports (status, created_at) WHERE status IN ('open', 'under_review');
CREATE INDEX reports_target_idx ON app.reports (target_type, target_id);

-- -----------------------------------------------------------------------------
-- 3.15 Notifications & support
-- -----------------------------------------------------------------------------

CREATE TABLE app.notifications (
  id                uuid PRIMARY KEY DEFAULT app.uuidv7(),
  user_id           uuid NOT NULL REFERENCES app.users (id) ON DELETE CASCADE,
  business_id       uuid REFERENCES app.businesses (id),  -- context only (e.g. staff alert for a business)
  category          text NOT NULL CHECK (category ~ '^[a-z_]+(\.[a-z_]+)*$'),   -- e.g. 'booking.confirmed', 'payout.failed'
  is_transactional  boolean NOT NULL,                     -- transactional/security: cannot be disabled
  title             text NOT NULL,
  body              text NOT NULL,
  data              jsonb NOT NULL DEFAULT '{}'::jsonb,   -- deep-link ids only; no PII beyond what the recipient owns
  dedupe_key        text NOT NULL UNIQUE,                 -- e.g. 'booking.reminder.24h:{booking_id}'
  read_at           timestamptz,
  expires_at        timestamptz,
  created_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX notifications_inbox_idx ON app.notifications (user_id, created_at DESC);

CREATE TABLE app.notification_deliveries (
  id                   uuid PRIMARY KEY DEFAULT app.uuidv7(),
  notification_id      uuid NOT NULL REFERENCES app.notifications (id) ON DELETE CASCADE,
  channel              app.notification_channel NOT NULL,
  status               app.delivery_status NOT NULL DEFAULT 'queued',
  provider_message_id  text,
  attempts             integer NOT NULL DEFAULT 0,
  last_error           text,
  sent_at              timestamptz,
  delivered_at         timestamptz,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  UNIQUE (notification_id, channel)
);
CREATE INDEX notification_deliveries_queue_idx ON app.notification_deliveries (created_at) WHERE status = 'queued';

CREATE TABLE app.notification_preferences (
  user_id     uuid NOT NULL REFERENCES app.users (id) ON DELETE CASCADE,
  category    text NOT NULL,
  channel     app.notification_channel NOT NULL,
  enabled     boolean NOT NULL,
  updated_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, category, channel)
);

CREATE TABLE app.push_subscriptions (
  id                      uuid PRIMARY KEY DEFAULT app.uuidv7(),
  user_id                 uuid NOT NULL REFERENCES app.users (id) ON DELETE CASCADE,
  endpoint                text NOT NULL UNIQUE,
  p256dh                  text NOT NULL,
  auth_secret_ciphertext  bytea NOT NULL,
  user_agent              text,
  created_at              timestamptz NOT NULL DEFAULT now(),
  last_used_at            timestamptz,
  revoked_at              timestamptz
);
CREATE INDEX push_subscriptions_user_idx ON app.push_subscriptions (user_id) WHERE revoked_at IS NULL;

CREATE TABLE app.support_cases (
  id                  uuid PRIMARY KEY DEFAULT app.uuidv7(),
  requester_user_id   uuid REFERENCES app.users (id),
  requester_email     extensions.citext,
  business_id         uuid REFERENCES app.businesses (id),
  subject             text NOT NULL,
  category            text NOT NULL,                      -- booking, payment, refund, account, venue, privacy, other
  priority            text NOT NULL DEFAULT 'normal' CHECK (priority IN ('low', 'normal', 'high', 'urgent')),
  status              app.support_case_status NOT NULL DEFAULT 'open',
  assigned_to         uuid REFERENCES app.users (id),
  related_booking_id  uuid REFERENCES app.bookings (id),
  related_payment_id  uuid REFERENCES app.payments (id),
  external_ticket_ref text,
  resolved_at         timestamptz,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT support_cases_requester CHECK (requester_user_id IS NOT NULL OR requester_email IS NOT NULL)
);
CREATE INDEX support_cases_queue_idx ON app.support_cases (status, priority, created_at);

-- -----------------------------------------------------------------------------
-- 3.16 Privacy
-- -----------------------------------------------------------------------------

-- Append-only consent log: every grant or withdrawal is a new row; the latest row per (user, purpose) wins.
CREATE TABLE app.consents (
  id                uuid PRIMARY KEY DEFAULT app.uuidv7(),
  user_id           uuid NOT NULL REFERENCES app.users (id) ON DELETE CASCADE,
  purpose           text NOT NULL CHECK (purpose IN (
                      'terms_of_service', 'privacy_notice', 'marketing_email', 'marketing_sms', 'marketing_push',
                      'location_processing', 'analytics_cookies', 'external_rating_link')),
  document_version  text NOT NULL,
  granted           boolean NOT NULL,
  source            text NOT NULL CHECK (source IN ('signup', 'settings', 'checkout', 'cookie_banner', 'os_prompt', 'support')),
  ip                inet,
  user_agent        text,
  captured_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX consents_latest_idx ON app.consents (user_id, purpose, captured_at DESC);

CREATE TABLE app.data_subject_requests (
  id                  uuid PRIMARY KEY DEFAULT app.uuidv7(),
  user_id             uuid REFERENCES app.users (id),
  requester_email     extensions.citext NOT NULL,
  request_type        app.dsr_type NOT NULL,
  status              app.dsr_status NOT NULL DEFAULT 'received',
  received_at         timestamptz NOT NULL DEFAULT now(),
  due_at              timestamptz NOT NULL,              -- response deadline per NPC rules (confirm with counsel)
  identity_verified_at timestamptz,
  completed_at        timestamptz,
  handled_by          uuid REFERENCES app.users (id),
  export_upload_id    uuid REFERENCES app.uploads (id),
  rejection_reason    text,
  notes               text,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT dsr_due_after_receipt CHECK (due_at > received_at)
);
CREATE INDEX data_subject_requests_open_idx ON app.data_subject_requests (due_at) WHERE status NOT IN ('completed', 'rejected');

-- -----------------------------------------------------------------------------
-- 3.17 Platform ops & audit
-- -----------------------------------------------------------------------------

-- Audit log: append-only for every application role; partitioned monthly (UTC); archived daily to S3 Object Lock.
CREATE TABLE audit.audit_logs (
  id                    uuid NOT NULL DEFAULT app.uuidv7(),
  occurred_at           timestamptz NOT NULL DEFAULT now(),
  actor_type            text NOT NULL CHECK (actor_type IN ('user', 'system', 'provider')),
  actor_user_id         uuid,
  support_session_id    uuid,                            -- set for every request made in support mode
  impersonated_user_id  uuid,
  scope                 text NOT NULL CHECK (scope IN ('public', 'player', 'business', 'platform', 'system')),
  business_id           uuid,
  venue_id              uuid,
  action                text NOT NULL CHECK (action ~ '^[a-z_]+(\.[a-z_]+)+$'),   -- e.g. 'refund.approve', 'commission_agreement.approve'
  target_type           text NOT NULL,
  target_id             uuid,
  outcome               text NOT NULL CHECK (outcome IN ('success', 'denied', 'failure')),
  before_state          jsonb,                           -- redacted (no secrets, no full PII)
  after_state           jsonb,
  reason                text,
  ip                    inet,
  user_agent            text,
  correlation_id        text NOT NULL,
  PRIMARY KEY (id, occurred_at)
) PARTITION BY RANGE (occurred_at);
CREATE INDEX audit_logs_business_time_idx ON audit.audit_logs (business_id, occurred_at DESC);
CREATE INDEX audit_logs_actor_time_idx ON audit.audit_logs (actor_user_id, occurred_at DESC);
CREATE INDEX audit_logs_target_idx ON audit.audit_logs (target_type, target_id);
CREATE INDEX audit_logs_action_time_idx ON audit.audit_logs (action, occurred_at DESC);
CREATE TABLE audit.audit_logs_default PARTITION OF audit.audit_logs DEFAULT;

CREATE TABLE audit.security_events (
  id              uuid NOT NULL DEFAULT app.uuidv7(),
  occurred_at     timestamptz NOT NULL DEFAULT now(),
  event_type      text NOT NULL CHECK (event_type IN (
                    'login_succeeded', 'login_failed', 'mfa_succeeded', 'mfa_failed', 'account_locked', 'password_changed',
                    'password_reset_requested', 'session_revoked', 'refresh_token_reuse', 'suspicious_login', 'mfa_enrolled',
                    'mfa_reset', 'webhook_token_invalid', 'rate_limited', 'authz_denied', 'cross_tenant_probe',
                    'support_session_started', 'support_session_ended', 'double_booking_attempt', 'export_generated')),
  severity        text NOT NULL CHECK (severity IN ('info', 'low', 'medium', 'high', 'critical')),
  user_id         uuid,
  business_id     uuid,
  ip              inet,
  user_agent      text,
  details         jsonb NOT NULL DEFAULT '{}'::jsonb,
  correlation_id  text,
  PRIMARY KEY (id, occurred_at)
) PARTITION BY RANGE (occurred_at);
CREATE INDEX security_events_user_time_idx ON audit.security_events (user_id, occurred_at DESC);
CREATE INDEX security_events_type_time_idx ON audit.security_events (event_type, occurred_at DESC);
CREATE TABLE audit.security_events_default PARTITION OF audit.security_events DEFAULT;

-- Transactional outbox: written in the same transaction as the state change; dispatched by outbox.dispatch.
CREATE TABLE app.outbox_events (
  id              uuid PRIMARY KEY DEFAULT app.uuidv7(),
  business_id     uuid REFERENCES app.businesses (id),
  aggregate_type  text NOT NULL,                         -- 'booking', 'payment', 'refund', 'payout', 'order', ...
  aggregate_id    uuid NOT NULL,
  event_type      text NOT NULL CHECK (event_type ~ '^[a-z_]+(\.[a-z_]+)+$'),   -- e.g. 'booking.confirmed'
  event_version   integer NOT NULL DEFAULT 1,
  payload         jsonb NOT NULL,
  status          app.outbox_status NOT NULL DEFAULT 'pending',
  attempts        integer NOT NULL DEFAULT 0,
  available_at    timestamptz NOT NULL DEFAULT now(),
  dispatched_at   timestamptz,
  last_error      text,
  correlation_id  text NOT NULL,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX outbox_events_pending_idx ON app.outbox_events (available_at) WHERE status IN ('pending', 'failed');
CREATE INDEX outbox_events_aggregate_idx ON app.outbox_events (aggregate_type, aggregate_id, created_at);

-- Idempotency-Key store (24 h). scope = 'user:{id}' | 'member:{business_id}:{user_id}' | 'platform:{user_id}'.
CREATE TABLE app.idempotency_keys (
  id                uuid PRIMARY KEY DEFAULT app.uuidv7(),
  scope             text NOT NULL,
  idem_key          text NOT NULL CHECK (length(idem_key) BETWEEN 8 AND 255),
  method            text NOT NULL CHECK (method IN ('POST', 'PUT', 'PATCH', 'DELETE')),
  route             text NOT NULL,                       -- route template, e.g. 'POST /v1/me/booking-holds'
  request_sha256    text NOT NULL CHECK (request_sha256 ~ '^[0-9a-f]{64}$'),
  state             app.idempotency_state NOT NULL DEFAULT 'in_progress',
  locked_until      timestamptz NOT NULL,                -- in_progress lease; after expiry a retry may take over
  response_status   integer,
  response_headers  jsonb,
  response_body     jsonb,
  resource_type     text,
  resource_id       uuid,
  created_at        timestamptz NOT NULL DEFAULT now(),
  expires_at        timestamptz NOT NULL,
  CONSTRAINT idempotency_keys_completed CHECK (state <> 'completed' OR response_status IS NOT NULL),
  UNIQUE (scope, idem_key)
);
CREATE INDEX idempotency_keys_expiry_idx ON app.idempotency_keys (expires_at);

-- =============================================================================
-- 4. TRIGGERS
-- =============================================================================

-- 4.1 updated_at on every app/audit table that has the column.
DO $trg$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT c.table_schema, c.table_name
      FROM information_schema.columns c
      JOIN information_schema.tables t ON t.table_schema = c.table_schema AND t.table_name = c.table_name
     WHERE c.table_schema IN ('app', 'audit') AND c.column_name = 'updated_at' AND t.table_type = 'BASE TABLE'
  LOOP
    EXECUTE format('CREATE TRIGGER trg_%s_updated_at BEFORE UPDATE ON %I.%I FOR EACH ROW EXECUTE FUNCTION app.tg_set_updated_at()',
                   r.table_name, r.table_schema, r.table_name);
  END LOOP;
END
$trg$;

-- 4.2 Append-only tables: block UPDATE and DELETE for every role (the owner can only bypass by dropping the trigger in a
--     reviewed migration, which is itself audited by CloudTrail/RDS logs). TRUNCATE is never granted to runtime roles.
DO $trg$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'app.financial_ledger_entries', 'app.ledger_journals', 'app.payment_events', 'app.inventory_movements',
    'app.booking_price_snapshots', 'app.booking_status_history', 'app.cancellation_policy_versions', 'app.consents',
    'audit.audit_logs', 'audit.security_events']
  LOOP
    EXECUTE format('CREATE TRIGGER trg_append_only BEFORE UPDATE OR DELETE ON %s FOR EACH ROW EXECUTE FUNCTION app.tg_forbid_mutation()', t);
  END LOOP;
  -- Statement-level TRUNCATE guard on the non-partitioned financial tables.
  FOREACH t IN ARRAY ARRAY['app.financial_ledger_entries', 'app.ledger_journals', 'app.payment_events']
  LOOP
    EXECUTE format('CREATE TRIGGER trg_no_truncate BEFORE TRUNCATE ON %s FOR EACH STATEMENT EXECUTE FUNCTION app.tg_forbid_mutation()', t);
  END LOOP;
END
$trg$;

-- 4.3 Booking state-machine guard: only the transitions of doc 07 §3 (B01–B29) are accepted, and money-backed transitions
--     (to confirmed / refunded / partially_refunded / disputed, and out of disputed) are accepted only in 'system' scope,
--     i.e. from the worker after authoritative provider verification. New bookings always start as 'draft'.
CREATE OR REPLACE FUNCTION app.tg_guard_booking_transition() RETURNS trigger
LANGUAGE plpgsql
SET search_path = app, pg_catalog, pg_temp
AS $fn$
DECLARE
  v_scope text := app.app_scope();
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'bookings must be inserted as draft (got %)', NEW.status USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.status = OLD.status THEN
    RETURN NEW;                                        -- B12 reschedule (confirmed -> confirmed) and non-status edits
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM (VALUES
        ('draft', 'slot_held'),               ('slot_held', 'payment_pending'),     ('slot_held', 'cancelled'),
        ('slot_held', 'expired'),             ('payment_pending', 'slot_held'),     ('payment_pending', 'confirmed'),
        ('payment_pending', 'expired'),       ('payment_pending', 'failed'),        ('payment_pending', 'refund_pending'),
        ('expired', 'confirmed'),             ('expired', 'refund_pending'),        ('confirmed', 'checked_in'),
        ('confirmed', 'completed'),           ('checked_in', 'completed'),          ('confirmed', 'no_show'),
        ('confirmed', 'cancelled'),           ('confirmed', 'refund_pending'),      ('refund_pending', 'refunded'),
        ('refund_pending', 'partially_refunded'), ('completed', 'refund_pending'),  ('no_show', 'refund_pending'),
        ('confirmed', 'disputed'),            ('checked_in', 'disputed'),           ('completed', 'disputed'),
        ('disputed', 'completed'),            ('disputed', 'confirmed'),            ('disputed', 'refunded'),
        ('partially_refunded', 'refund_pending')
      ) AS t (from_status, to_status)
     WHERE t.from_status = OLD.status::text AND t.to_status = NEW.status::text) THEN
    RAISE EXCEPTION 'INVALID_STATE_TRANSITION: booking % -> %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;

  IF (NEW.status IN ('confirmed', 'refunded', 'partially_refunded', 'disputed') OR OLD.status = 'disputed')
     AND v_scope <> 'system' THEN
    RAISE EXCEPTION 'booking transition % -> % is reserved to the system scope', OLD.status, NEW.status
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  NEW.version := OLD.version + 1;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER trg_bookings_guard_transition
  BEFORE INSERT OR UPDATE OF status ON app.bookings
  FOR EACH ROW EXECUTE FUNCTION app.tg_guard_booking_transition();

-- 4.4 Payment state-machine guard (doc 08 §2, P01–P22). Every transition into a money state is system-only.
CREATE OR REPLACE FUNCTION app.tg_guard_payment_transition() RETURNS trigger
LANGUAGE plpgsql
SET search_path = app, pg_catalog, pg_temp
AS $fn$
DECLARE
  v_scope text := app.app_scope();
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'created' THEN
      RAISE EXCEPTION 'payments must be inserted as created (got %)', NEW.status USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.status = OLD.status THEN
    RETURN NEW;                                        -- e.g. additional partial refund keeps partially_refunded
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM (VALUES
        ('created', 'pending'),       ('created', 'failed'),          ('pending', 'authorized'),
        ('pending', 'captured'),      ('pending', 'failed'),          ('pending', 'expired'),
        ('pending', 'cancelled'),     ('authorized', 'captured'),     ('authorized', 'cancelled'),
        ('authorized', 'expired'),    ('authorized', 'failed'),       ('captured', 'partially_refunded'),
        ('captured', 'refunded'),     ('partially_refunded', 'refunded'), ('captured', 'disputed'),
        ('partially_refunded', 'disputed'), ('disputed', 'captured'), ('disputed', 'partially_refunded'),
        ('disputed', 'chargeback'),   ('expired', 'captured'),        ('cancelled', 'captured'),
        ('failed', 'captured')
      ) AS t (from_status, to_status)
     WHERE t.from_status = OLD.status::text AND t.to_status = NEW.status::text) THEN
    RAISE EXCEPTION 'INVALID_STATE_TRANSITION: payment % -> %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status IN ('authorized', 'captured', 'partially_refunded', 'refunded', 'disputed', 'chargeback')
     AND v_scope <> 'system' THEN
    RAISE EXCEPTION 'payment transition % -> % is reserved to the system scope', OLD.status, NEW.status
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  NEW.version := OLD.version + 1;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER trg_payments_guard_transition
  BEFORE INSERT OR UPDATE OF status ON app.payments
  FOR EACH ROW EXECUTE FUNCTION app.tg_guard_payment_transition();

-- 4.5 Ledger: every journal balances per currency and has at least two lines (checked at COMMIT).
--     SECURITY DEFINER (owner app_definer, see section 6) so the check always sees every line of the journal.
CREATE OR REPLACE FUNCTION app.tg_assert_journal_balanced() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = app, pg_catalog, pg_temp
AS $fn$
DECLARE
  v_journal_id uuid;
  v_lines integer;
  v_currency char(3);
  v_net bigint;
BEGIN
  -- Separate branches: PL/pgSQL compiles one copy per trigger relation, and each branch only touches fields that exist.
  IF TG_TABLE_NAME = 'ledger_journals' THEN
    v_journal_id := NEW.id;
  ELSE
    v_journal_id := NEW.journal_id;
  END IF;

  SELECT count(*) INTO v_lines FROM app.financial_ledger_entries WHERE journal_id = v_journal_id;
  IF v_lines < 2 THEN
    RAISE EXCEPTION 'ledger journal % has % line(s); at least 2 are required', v_journal_id, v_lines
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT e.currency, sum(CASE e.direction WHEN 'debit' THEN e.amount_minor ELSE -e.amount_minor END)
    INTO v_currency, v_net
    FROM app.financial_ledger_entries e
   WHERE e.journal_id = v_journal_id
   GROUP BY e.currency
  HAVING sum(CASE e.direction WHEN 'debit' THEN e.amount_minor ELSE -e.amount_minor END) <> 0
   LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'ledger journal % does not balance in %: debits - credits = %', v_journal_id, v_currency, v_net
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END
$fn$;
CREATE CONSTRAINT TRIGGER trg_fle_journal_balanced
  AFTER INSERT ON app.financial_ledger_entries
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION app.tg_assert_journal_balanced();
CREATE CONSTRAINT TRIGGER trg_journal_has_lines
  AFTER INSERT ON app.ledger_journals
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION app.tg_assert_journal_balanced();

-- Lines must share the journal's tenant (a journal never mixes two businesses).
CREATE OR REPLACE FUNCTION app.tg_assert_entry_tenant() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = app, pg_catalog, pg_temp
AS $fn$
DECLARE
  v_business uuid;
BEGIN
  SELECT j.business_id INTO v_business FROM app.ledger_journals j WHERE j.id = NEW.journal_id;
  IF NEW.business_id IS DISTINCT FROM v_business THEN
    RAISE EXCEPTION 'ledger entry business % differs from journal business %', NEW.business_id, v_business
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.account_code LIKE 'venue:%' AND NEW.account_code <> 'venue:' || v_business::text || ':payable' THEN
    RAISE EXCEPTION 'venue account % does not belong to journal business %', NEW.account_code, v_business
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER trg_fle_tenant BEFORE INSERT ON app.financial_ledger_entries
  FOR EACH ROW EXECUTE FUNCTION app.tg_assert_entry_tenant();

-- 4.6 Booking <-> slot invariant (checked at COMMIT):
--     slot_held | payment_pending | confirmed | checked_in  => exactly one active booking_slots row
--     draft | cancelled | expired | failed                  => no active booking_slots row
--     other statuses: slot retained (time consumed) or released (refund before play) — both valid.
CREATE OR REPLACE FUNCTION app.tg_assert_booking_slot_invariant() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = app, pg_catalog, pg_temp
AS $fn$
DECLARE
  v_status app.booking_status;
  v_active integer;
BEGIN
  SELECT b.status INTO v_status FROM app.bookings b WHERE b.id = NEW.id;   -- state at commit time
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  SELECT count(*) INTO v_active FROM app.booking_slots s WHERE s.booking_id = NEW.id AND s.status = 'active';
  IF v_status IN ('slot_held', 'payment_pending', 'confirmed', 'checked_in') AND v_active <> 1 THEN
    RAISE EXCEPTION 'booking % (%) must own exactly one active slot; found %', NEW.id, v_status, v_active
      USING ERRCODE = 'check_violation';
  ELSIF v_status IN ('draft', 'cancelled', 'expired', 'failed') AND v_active <> 0 THEN
    RAISE EXCEPTION 'booking % (%) must not own an active slot; found %', NEW.id, v_status, v_active
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END
$fn$;
CREATE CONSTRAINT TRIGGER trg_bookings_slot_invariant
  AFTER INSERT OR UPDATE ON app.bookings
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION app.tg_assert_booking_slot_invariant();

