-- Every business role implicitly has business.view (granted explicitly here so checks stay data-driven).
INSERT INTO app.role_permissions (role_id, permission_code)
SELECT r.id, p.code
  FROM app.roles r
  JOIN app.permissions p ON p.scope = r.scope
 WHERE r.business_id IS NULL
   AND (   r.code IN ('superadmin', 'business_owner')
        OR (r.scope = 'business' AND p.code = 'business.view')
        OR (r.code = 'business_manager' AND p.code NOT IN ('finance.manage_payout_account', 'roles.manage', 'refunds.approve'))
        OR (r.code = 'receptionist' AND p.code IN ('bookings.view', 'bookings.create_walkin', 'bookings.check_in',
              'bookings.mark_no_show', 'payments.view', 'customers.view', 'orders.fulfill', 'events.check_in', 'restrictions.view'))
        OR (r.code = 'court_manager' AND p.code IN ('bookings.view', 'courts.manage', 'courts.block', 'venues.manage'))
        OR (r.code = 'finance_viewer' AND p.code IN ('finance.view_summary', 'finance.view_payouts', 'payments.view',
              'reports.view', 'reports.export'))
        OR (r.code = 'event_manager' AND p.code IN ('bookings.view', 'events.manage', 'events.check_in', 'customers.view'))
        OR (r.code = 'inventory_manager' AND p.code IN ('products.manage', 'inventory.manage', 'orders.fulfill'))
        OR (r.code = 'platform_support' AND p.code IN ('platform.users.view', 'platform.bookings.view',
              'platform.support.impersonate', 'platform.overview.view'))
        OR (r.code = 'platform_finance' AND p.code IN ('platform.transactions.view', 'platform.reconciliation.run',
              'platform.payouts.manage', 'platform.refunds.approve', 'platform.disputes.manage', 'platform.reports.view',
              'platform.reports.export', 'platform.commissions.manage'))
        OR (r.code = 'platform_trust_safety' AND p.code IN ('platform.moderation.manage', 'platform.restrictions.manage',
              'platform.users.suspend', 'platform.venues.moderate', 'platform.users.view'))
        OR (r.code = 'platform_compliance' AND p.code IN ('platform.audit.view', 'platform.privacy.requests',
              'platform.businesses.verify', 'platform.security.view')));

-- =============================================================================
-- 6. ROW-LEVEL SECURITY (doc 10 §5)
-- Notation used in comments: S = (SELECT app.app_scope()), B = (SELECT app.app_current_business_id()),
-- U = (SELECT app.app_current_user_id()). Scalar sub-selects make the planner evaluate each helper once per statement.
-- Policies are PERMISSIVE and OR-ed per command. app.webhook_events and app.idempotency_keys are infrastructure tables
-- without tenant reads; they are protected by grants (section 8) instead of RLS.
-- =============================================================================

-- 6.1 Enable + force RLS everywhere (including partitions, which get no policies => direct access denied).
DO $rls$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT n.nspname, c.relname
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname IN ('app', 'audit')
       AND c.relkind IN ('r', 'p')
       AND c.relname NOT IN ('webhook_events', 'idempotency_keys')
  LOOP
    EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', r.nspname, r.relname);
    EXECUTE format('ALTER TABLE %I.%I FORCE ROW LEVEL SECURITY', r.nspname, r.relname);
  END LOOP;
END
$rls$;

-- 6.2 Reference tables: readable in every valid scope; writable only by platform/system.
DO $rls$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['ph_locations', 'amenities', 'court_types', 'event_types', 'product_categories',
                           'payment_method_types', 'permissions', 'platform_settings', 'feature_flags']
  LOOP
    EXECUTE format('CREATE POLICY ref_read ON app.%I FOR SELECT USING ((SELECT app.app_scope()) <> %L)', t, 'none');
    EXECUTE format('CREATE POLICY ref_write ON app.%I FOR ALL USING ((SELECT app.app_scope()) IN (%L, %L)) WITH CHECK ((SELECT app.app_scope()) IN (%L, %L))',
                   t, 'platform', 'system', 'platform', 'system');
  END LOOP;
END
$rls$;

-- 6.3 Tenant isolation, read-write for the owning business (application authz narrows further by permission + venue).
DO $rls$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'venues', 'venue_operating_hours', 'venue_special_hours', 'venue_amenities', 'courts', 'court_blocks',
    'business_members', 'business_member_roles', 'business_verifications', 'pricing_rules', 'bookings', 'booking_holds',
    'booking_slots', 'booking_participants', 'booking_price_snapshots', 'booking_status_history', 'checkouts',
    'checkout_items', 'promotion_redemptions', 'events', 'event_divisions', 'event_registrations', 'event_waitlists',
    'teams', 'team_members', 'matches', 'products', 'product_variants', 'inventory_movements', 'orders', 'order_items',
    'pickup_claims', 'reviews', 'payout_accounts', 'payments', 'refunds', 'approval_requests', 'roles', 'role_permissions',
    'holidays', 'cancellation_policies', 'cancellation_policy_versions', 'promotions', 'venue_user_restrictions',
    'uploads', 'support_cases']
  LOOP
    EXECUTE format($p$
      CREATE POLICY tenant_isolation ON app.%I
        USING ((SELECT app.app_scope()) IN ('platform', 'system')
               OR ((SELECT app.app_scope()) = 'business' AND business_id = (SELECT app.app_current_business_id())))
        WITH CHECK ((SELECT app.app_scope()) IN ('platform', 'system')
               OR ((SELECT app.app_scope()) = 'business' AND business_id = (SELECT app.app_current_business_id())))
    $p$, t);
  END LOOP;
END
$rls$;

-- 6.4 Tenant data that a business may READ but only platform/system may WRITE (money + commercial terms).
DO $rls$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['commission_agreements', 'fee_schedules', 'payment_provider_accounts', 'payment_events',
                           'commissions', 'settlements', 'settlement_lines', 'payouts', 'disputes', 'ledger_journals']
  LOOP
    EXECUTE format($p$
      CREATE POLICY tenant_read ON app.%I FOR SELECT
        USING ((SELECT app.app_scope()) = 'business' AND business_id = (SELECT app.app_current_business_id()))
    $p$, t);
    EXECUTE format($p$
      CREATE POLICY platform_write ON app.%I
        USING ((SELECT app.app_scope()) IN ('platform', 'system'))
        WITH CHECK ((SELECT app.app_scope()) IN ('platform', 'system'))
    $p$, t);
  END LOOP;
END
$rls$;

-- 6.5 Platform templates (business_id IS NULL) are readable by every valid scope.
DO $rls$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['roles', 'role_permissions', 'holidays', 'cancellation_policies', 'cancellation_policy_versions',
                           'commission_agreements', 'fee_schedules', 'promotions']
  LOOP
    EXECUTE format('CREATE POLICY template_read ON app.%I FOR SELECT USING (business_id IS NULL AND (SELECT app.app_scope()) <> %L)', t, 'none');
  END LOOP;
END
$rls$;

-- 6.6 Player-owned rows inside tenant tables: a player sees and acts on their own rows across all businesses.
DO $rls$
DECLARE
  r record;
BEGIN
  FOR r IN SELECT * FROM (VALUES
      ('bookings', 'player_user_id'), ('booking_holds', 'holder_user_id'), ('checkouts', 'user_id'),
      ('payments', 'user_id'), ('orders', 'user_id'), ('event_registrations', 'user_id'),
      ('event_waitlists', 'user_id'), ('promotion_redemptions', 'user_id'), ('reviews', 'user_id'),
      ('team_members', 'user_id')) AS v (tbl, col)
  LOOP
    EXECUTE format($p$
      CREATE POLICY player_own ON app.%1$I
        USING ((SELECT app.app_scope()) = 'player' AND %2$I = (SELECT app.app_current_user_id()))
        WITH CHECK ((SELECT app.app_scope()) = 'player' AND %2$I = (SELECT app.app_current_user_id()))
    $p$, r.tbl, r.col);
  END LOOP;
END
$rls$;

-- Child rows reachable through a player-owned parent (the sub-select is itself filtered by the parent's policies).
CREATE POLICY player_via_booking ON app.booking_slots
  USING ((SELECT app.app_scope()) = 'player' AND booking_id IN (SELECT b.id FROM app.bookings b WHERE b.player_user_id = (SELECT app.app_current_user_id())))
  WITH CHECK ((SELECT app.app_scope()) = 'player' AND booking_id IN (SELECT b.id FROM app.bookings b WHERE b.player_user_id = (SELECT app.app_current_user_id())));
CREATE POLICY player_via_booking ON app.booking_price_snapshots
  USING ((SELECT app.app_scope()) = 'player' AND booking_id IN (SELECT b.id FROM app.bookings b WHERE b.player_user_id = (SELECT app.app_current_user_id())))
  WITH CHECK ((SELECT app.app_scope()) = 'player' AND booking_id IN (SELECT b.id FROM app.bookings b WHERE b.player_user_id = (SELECT app.app_current_user_id())));
CREATE POLICY player_via_booking ON app.booking_status_history
  USING ((SELECT app.app_scope()) = 'player' AND booking_id IN (SELECT b.id FROM app.bookings b WHERE b.player_user_id = (SELECT app.app_current_user_id())))
  WITH CHECK ((SELECT app.app_scope()) = 'player' AND booking_id IN (SELECT b.id FROM app.bookings b WHERE b.player_user_id = (SELECT app.app_current_user_id())));
CREATE POLICY player_via_booking ON app.booking_participants
  USING ((SELECT app.app_scope()) = 'player' AND (user_id = (SELECT app.app_current_user_id())
         OR booking_id IN (SELECT b.id FROM app.bookings b WHERE b.player_user_id = (SELECT app.app_current_user_id()))))
  WITH CHECK ((SELECT app.app_scope()) = 'player' AND booking_id IN (SELECT b.id FROM app.bookings b WHERE b.player_user_id = (SELECT app.app_current_user_id())));
CREATE POLICY player_via_checkout ON app.checkout_items
  USING ((SELECT app.app_scope()) = 'player' AND checkout_id IN (SELECT c.id FROM app.checkouts c WHERE c.user_id = (SELECT app.app_current_user_id())))
  WITH CHECK ((SELECT app.app_scope()) = 'player' AND checkout_id IN (SELECT c.id FROM app.checkouts c WHERE c.user_id = (SELECT app.app_current_user_id())));
CREATE POLICY player_via_order ON app.order_items
  USING ((SELECT app.app_scope()) = 'player' AND order_id IN (SELECT o.id FROM app.orders o WHERE o.user_id = (SELECT app.app_current_user_id())))
  WITH CHECK ((SELECT app.app_scope()) = 'player' AND order_id IN (SELECT o.id FROM app.orders o WHERE o.user_id = (SELECT app.app_current_user_id())));
CREATE POLICY player_via_payment ON app.refunds
  USING ((SELECT app.app_scope()) = 'player' AND payment_id IN (SELECT p.id FROM app.payments p WHERE p.user_id = (SELECT app.app_current_user_id())))
  WITH CHECK ((SELECT app.app_scope()) = 'player' AND payment_id IN (SELECT p.id FROM app.payments p WHERE p.user_id = (SELECT app.app_current_user_id())));

-- 6.7 Public catalog reads (scopes 'public' and 'player'): only published/active listings.
