         AND venue_id IN (SELECT v.id FROM app.venues v));
CREATE POLICY public_read ON app.venue_operating_hours FOR SELECT
  USING ((SELECT app.app_scope()) IN ('public', 'player') AND venue_id IN (SELECT v.id FROM app.venues v));
CREATE POLICY public_read ON app.venue_special_hours FOR SELECT
  USING ((SELECT app.app_scope()) IN ('public', 'player') AND venue_id IN (SELECT v.id FROM app.venues v));
CREATE POLICY public_read ON app.venue_amenities FOR SELECT
  USING ((SELECT app.app_scope()) IN ('public', 'player') AND venue_id IN (SELECT v.id FROM app.venues v));
CREATE POLICY public_read ON app.pricing_rules FOR SELECT
  USING ((SELECT app.app_scope()) IN ('public', 'player') AND status = 'active' AND venue_id IN (SELECT v.id FROM app.venues v));
CREATE POLICY public_read ON app.holidays FOR SELECT
