CREATE POLICY public_read ON app.events FOR SELECT
  USING ((SELECT app.app_scope()) IN ('public', 'player')
         AND status IN ('published', 'registration_closed', 'in_progress', 'completed') AND visibility IN ('public', 'unlisted'));
CREATE POLICY public_read ON app.event_divisions FOR SELECT
  USING ((SELECT app.app_scope()) IN ('public', 'player') AND event_id IN (SELECT e.id FROM app.events e));
CREATE POLICY public_read ON app.teams FOR SELECT
  USING ((SELECT app.app_scope()) IN ('public', 'player') AND event_id IN (SELECT e.id FROM app.events e));
CREATE POLICY public_read ON app.matches FOR SELECT
  USING ((SELECT app.app_scope()) IN ('public', 'player') AND event_id IN (SELECT e.id FROM app.events e));
CREATE POLICY public_read ON app.products FOR SELECT
  USING ((SELECT app.app_scope()) IN ('public', 'player') AND status = 'active' AND deleted_at IS NULL
         AND venue_id IN (SELECT v.id FROM app.venues v));
CREATE POLICY public_read ON app.product_variants FOR SELECT
  USING ((SELECT app.app_scope()) IN ('public', 'player') AND status = 'active' AND product_id IN (SELECT p.id FROM app.products p));
CREATE POLICY public_read ON app.reviews FOR SELECT
