CREATE POLICY public_read ON app.promotions FOR SELECT
  USING ((SELECT app.app_scope()) IN ('public', 'player') AND status = 'active');   -- API looks up by exact code only
-- Availability: active occupancy rows only. The public repository reads app.v_public_court_occupancy (court, range).
CREATE POLICY public_read ON app.booking_slots FOR SELECT
  USING ((SELECT app.app_scope()) IN ('public', 'player') AND status = 'active');

-- 6.8 Identity: users see themselves; platform/system see all. Signup runs in 'player' scope with the pre-generated id.
CREATE POLICY users_self ON app.users
  USING ((SELECT app.app_scope()) IN ('player', 'business') AND id = (SELECT app.app_current_user_id()))
  WITH CHECK ((SELECT app.app_scope()) IN ('player', 'business') AND id = (SELECT app.app_current_user_id()));
CREATE POLICY users_platform ON app.users
  USING ((SELECT app.app_scope()) IN ('platform', 'system'))
  WITH CHECK ((SELECT app.app_scope()) IN ('platform', 'system'));

CREATE POLICY business_self ON app.businesses
  USING ((SELECT app.app_scope()) = 'business' AND id = (SELECT app.app_current_business_id()))
  WITH CHECK ((SELECT app.app_scope()) = 'business' AND id = (SELECT app.app_current_business_id()));
CREATE POLICY owner_onboarding ON app.businesses
  USING ((SELECT app.app_scope()) = 'player' AND owner_user_id = (SELECT app.app_current_user_id())
         AND status IN ('draft', 'pending_verification', 'rejected'))
  WITH CHECK ((SELECT app.app_scope()) = 'player' AND owner_user_id = (SELECT app.app_current_user_id())
         AND status IN ('draft', 'pending_verification'));
CREATE POLICY platform_all ON app.businesses
  USING ((SELECT app.app_scope()) IN ('platform', 'system'))
  WITH CHECK ((SELECT app.app_scope()) IN ('platform', 'system'));

-- Staff helper (/v1/staff/me/memberships) lists the caller's memberships from any authenticated scope.
CREATE POLICY self_read ON app.business_members FOR SELECT
  USING ((SELECT app.app_scope()) IN ('player', 'business', 'platform') AND user_id = (SELECT app.app_current_user_id()));
CREATE POLICY self_read ON app.business_member_roles FOR SELECT
  USING ((SELECT app.app_scope()) IN ('player', 'business', 'platform')
         AND member_id IN (SELECT m.id FROM app.business_members m WHERE m.user_id = (SELECT app.app_current_user_id())));
CREATE POLICY self_read ON app.platform_member_roles FOR SELECT
  USING ((SELECT app.app_scope()) IN ('player', 'business', 'platform') AND user_id = (SELECT app.app_current_user_id()));
CREATE POLICY platform_all ON app.platform_member_roles
  USING ((SELECT app.app_scope()) IN ('platform', 'system'))
  WITH CHECK ((SELECT app.app_scope()) IN ('platform', 'system'));

-- 6.9 Self-owned global rows (not tenant data). Secret-bearing tables are NOT readable in platform scope.
DO $rls$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['user_profiles', 'user_addresses', 'user_preferences', 'identities', 'sessions', 'mfa_factors',
                           'mfa_recovery_codes', 'verification_tokens', 'favorites', 'notifications', 'notification_preferences',
                           'push_subscriptions', 'consents', 'payment_customers', 'payment_method_tokens', 'player_ratings',
                           'rating_history', 'data_subject_requests']
  LOOP
    EXECUTE format($p$
      CREATE POLICY self_access ON app.%I
        USING ((SELECT app.app_scope()) IN ('player', 'business', 'platform') AND user_id = (SELECT app.app_current_user_id()))
        WITH CHECK ((SELECT app.app_scope()) IN ('player', 'business', 'platform') AND user_id = (SELECT app.app_current_user_id()))
    $p$, t);
    IF t IN ('mfa_factors', 'mfa_recovery_codes', 'verification_tokens', 'push_subscriptions') THEN
      EXECUTE format($p$
        CREATE POLICY system_access ON app.%I
          USING ((SELECT app.app_scope()) = 'system') WITH CHECK ((SELECT app.app_scope()) = 'system')
      $p$, t);
    ELSE
      EXECUTE format($p$
        CREATE POLICY platform_access ON app.%I
          USING ((SELECT app.app_scope()) IN ('platform', 'system'))
          WITH CHECK ((SELECT app.app_scope()) IN ('platform', 'system'))
      $p$, t);
    END IF;
  END LOOP;
END
$rls$;

-- Staff invitations are created in business scope for a target who may not have an account yet.
CREATE POLICY business_invitations ON app.verification_tokens
  USING ((SELECT app.app_scope()) = 'business' AND purpose = 'staff_invitation' AND business_id = (SELECT app.app_current_business_id()))
  WITH CHECK ((SELECT app.app_scope()) = 'business' AND purpose = 'staff_invitation' AND business_id = (SELECT app.app_current_business_id()));

CREATE POLICY self_uploads ON app.uploads
  USING ((SELECT app.app_scope()) IN ('player', 'business') AND business_id IS NULL AND uploaded_by = (SELECT app.app_current_user_id()))
  WITH CHECK ((SELECT app.app_scope()) IN ('player', 'business') AND business_id IS NULL AND uploaded_by = (SELECT app.app_current_user_id()));
CREATE POLICY requester_access ON app.support_cases
  USING ((SELECT app.app_scope()) IN ('player', 'business') AND requester_user_id = (SELECT app.app_current_user_id()))
  WITH CHECK ((SELECT app.app_scope()) IN ('player', 'business') AND requester_user_id = (SELECT app.app_current_user_id()));
CREATE POLICY reporter_access ON app.reports
  USING ((SELECT app.app_scope()) IN ('player', 'business') AND reporter_user_id = (SELECT app.app_current_user_id()))
  WITH CHECK ((SELECT app.app_scope()) IN ('player', 'business') AND reporter_user_id = (SELECT app.app_current_user_id()));

-- 6.10 Platform/system-only tables.
DO $rls$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['support_sessions', 'reconciliation_runs', 'reconciliation_exceptions', 'notification_deliveries', 'reports']
  LOOP
    EXECUTE format($p$
      CREATE POLICY platform_all ON app.%I
        USING ((SELECT app.app_scope()) IN ('platform', 'system'))
        WITH CHECK ((SELECT app.app_scope()) IN ('platform', 'system'))
    $p$, t);
  END LOOP;
END
$rls$;

-- 6.11 Ledger. Businesses read only their own venue-payable lines; posting is platform/system only.
CREATE POLICY account_read ON app.ledger_accounts FOR SELECT
  USING ((SELECT app.app_scope()) IN ('platform', 'system')
         OR ((SELECT app.app_scope()) = 'business' AND (owner = 'platform' OR business_id = (SELECT app.app_current_business_id()))));
CREATE POLICY account_write ON app.ledger_accounts
  USING ((SELECT app.app_scope()) IN ('platform', 'system'))
  WITH CHECK ((SELECT app.app_scope()) IN ('platform', 'system'));
CREATE POLICY venue_lines_read ON app.financial_ledger_entries FOR SELECT
  USING ((SELECT app.app_scope()) = 'business' AND business_id = (SELECT app.app_current_business_id())
         AND account_code LIKE 'venue:%');
CREATE POLICY platform_post ON app.financial_ledger_entries
  USING ((SELECT app.app_scope()) IN ('platform', 'system'))
  WITH CHECK ((SELECT app.app_scope()) IN ('platform', 'system'));

-- 6.12 Outbox and audit: any valid scope may append; reads are restricted.
CREATE POLICY outbox_append ON app.outbox_events FOR INSERT
  WITH CHECK ((SELECT app.app_scope()) <> 'none'
              AND ((SELECT app.app_scope()) <> 'business' OR business_id = (SELECT app.app_current_business_id())));
CREATE POLICY outbox_dispatch ON app.outbox_events
  USING ((SELECT app.app_scope()) = 'system') WITH CHECK ((SELECT app.app_scope()) = 'system');

CREATE POLICY audit_append ON audit.audit_logs FOR INSERT
  WITH CHECK ((SELECT app.app_scope()) <> 'none'
              AND ((SELECT app.app_scope()) <> 'business' OR business_id = (SELECT app.app_current_business_id())));
CREATE POLICY audit_business_read ON audit.audit_logs FOR SELECT
  USING ((SELECT app.app_scope()) = 'business' AND business_id = (SELECT app.app_current_business_id()));
CREATE POLICY audit_platform_read ON audit.audit_logs FOR SELECT
  USING ((SELECT app.app_scope()) IN ('platform', 'system'));

CREATE POLICY security_append ON audit.security_events FOR INSERT
  WITH CHECK ((SELECT app.app_scope()) <> 'none');
CREATE POLICY security_platform_read ON audit.security_events FOR SELECT
  USING ((SELECT app.app_scope()) IN ('platform', 'system'));

-- 6.13 app_definer: full row visibility, limited by its table privileges (section 8) and used only by the vetted
--      SECURITY DEFINER functions of section 7 and the invariant triggers of section 4.
DO $rls$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['app.bookings', 'app.booking_slots', 'app.booking_holds', 'app.booking_status_history',
                           'app.outbox_events', 'app.financial_ledger_entries', 'app.ledger_journals', 'app.users',
                           'app.sessions', 'app.verification_tokens', 'app.venue_user_restrictions',
                           'app.commission_agreements', 'app.fee_schedules', 'app.business_members', 'audit.audit_logs']
  LOOP
    EXECUTE format('CREATE POLICY definer_access ON %s TO app_definer USING (true) WITH CHECK (true)', t);
  END LOOP;
END
$rls$;
CREATE POLICY definer_read ON app.orders FOR SELECT TO app_definer USING (true);
CREATE POLICY definer_read ON app.event_registrations FOR SELECT TO app_definer USING (true);

-- =============================================================================
-- 7. PRIVILEGED HELPER FUNCTIONS (SECURITY DEFINER, owned by app_definer)
-- Rules: fixed queries only; pinned search_path; validate the caller's scope explicitly; return the minimum data;
-- EXECUTE granted to app_rw only. These are the ONLY paths by which a scope reaches rows its policies hide.
-- =============================================================================

GRANT USAGE, CREATE ON SCHEMA app TO app_definer;
GRANT USAGE ON SCHEMA audit, extensions TO app_definer;

-- 7.1 Inline stale-hold cleanup, called inside the hold-creation transaction BEFORE inserting the new slot (doc 07 §5).
--     Lock order is always booking row -> slot -> hold. SKIP LOCKED leaves a booking that another transaction is
--     confirming untouched; the exclusion constraint then arbitrates.
CREATE OR REPLACE FUNCTION app.fn_release_stale_holds(p_court_id uuid, p_range tstzrange, p_correlation_id text)
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = app, pg_catalog, pg_temp
AS $fn$
DECLARE
  v_row record;
  v_count integer := 0;
BEGIN
  IF app.app_scope() NOT IN ('player', 'business', 'platform', 'system') THEN
    RAISE EXCEPTION 'fn_release_stale_holds requires an authenticated scope' USING ERRCODE = 'insufficient_privilege';
  END IF;

  FOR v_row IN
    SELECT b.id, b.business_id, b.status
      FROM app.bookings b
     WHERE b.id IN (SELECT s.booking_id
                      FROM app.booking_slots s
                     WHERE s.court_id = p_court_id
                       AND s.status = 'active'
                       AND s.hold_expires_at IS NOT NULL
                       AND s.hold_expires_at <= now()
                       AND s.occupied_range && p_range)
       AND b.status IN ('slot_held', 'payment_pending')
     ORDER BY b.id
       FOR UPDATE OF b SKIP LOCKED
  LOOP
    UPDATE app.booking_slots
       SET status = 'released', released_at = now(), release_reason = 'hold_expired'
     WHERE booking_id = v_row.id AND status = 'active';
    UPDATE app.booking_holds
       SET status = 'expired', released_at = now(), release_reason = 'hold_expired'
     WHERE booking_id = v_row.id AND status = 'active';
    UPDATE app.bookings
       SET status = 'expired', expired_at = now()
     WHERE id = v_row.id;
    INSERT INTO app.booking_status_history (business_id, booking_id, from_status, to_status, transition_code, actor_type, reason, correlation_id)
    VALUES (v_row.business_id, v_row.id, v_row.status, 'expired',
            CASE v_row.status WHEN 'slot_held' THEN 'B04' ELSE 'B07' END,
            'system', 'stale hold released inline before a new hold', p_correlation_id);
    INSERT INTO app.outbox_events (business_id, aggregate_type, aggregate_id, event_type, payload, correlation_id)
    VALUES (v_row.business_id, 'booking', v_row.id, 'booking.expired',
            jsonb_build_object('booking_id', v_row.id, 'from_status', v_row.status, 'reason', 'hold_expired'), p_correlation_id);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END
$fn$;

-- 7.2 Booking eligibility (restrictions) without exposing restriction rows. Neutral boolean only; the API maps false to
--     BOOKING_NOT_ALLOWED. A player may only ask about themselves; a business only about its own tenant.
CREATE OR REPLACE FUNCTION app.fn_booking_eligibility(p_user_id uuid, p_business_id uuid, p_venue_id uuid, p_kind text)
RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = app, pg_catalog, pg_temp
AS $fn$
DECLARE
  v_scope text := app.app_scope();
BEGIN
  IF p_kind NOT IN ('booking', 'event_registration') THEN
    RAISE EXCEPTION 'unknown eligibility kind %', p_kind USING ERRCODE = 'invalid_parameter_value';
  END IF;
  IF (v_scope = 'player' AND p_user_id IS DISTINCT FROM app.app_current_user_id())
     OR (v_scope = 'business' AND p_business_id IS DISTINCT FROM app.app_current_business_id())
     OR v_scope NOT IN ('player', 'business', 'platform', 'system') THEN
    RAISE EXCEPTION 'eligibility check not permitted in this scope' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NOT EXISTS (
    SELECT 1
      FROM app.venue_user_restrictions r
     WHERE r.user_id = p_user_id
       AND r.status = 'active'
       AND r.starts_at <= now()
       AND (r.ends_at IS NULL OR r.ends_at > now())
       AND (CASE p_kind WHEN 'booking' THEN r.blocks_bookings ELSE r.blocks_event_registration END)
       AND (   r.level = 'platform'
            OR (r.level = 'business' AND r.business_id = p_business_id)
            OR (r.level = 'venue' AND r.business_id = p_business_id AND r.venue_id = p_venue_id)));
END
$fn$;

-- 7.3 Commercial terms resolution for quotes (player scope cannot read business-specific agreements directly).
CREATE OR REPLACE FUNCTION app.fn_resolve_commission_agreement(p_business_id uuid, p_at timestamptz)
RETURNS TABLE (agreement_id uuid, rate_ppm integer, commissionable_base text, applies_to_products boolean, applies_to_events boolean)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = app, pg_catalog, pg_temp
AS $fn$
  SELECT a.id, a.rate_ppm, a.commissionable_base, a.applies_to_products, a.applies_to_events
    FROM app.commission_agreements a
   WHERE a.status = 'approved'
     AND tstzrange(a.effective_from, a.effective_to, '[)') @> p_at
     AND (a.business_id = p_business_id OR a.business_id IS NULL)
     AND app.app_scope() <> 'none'
   ORDER BY (a.business_id IS NULL), a.effective_from DESC   -- business-specific agreement wins over the global default
   LIMIT 1
$fn$;

CREATE OR REPLACE FUNCTION app.fn_resolve_fee_schedule(p_business_id uuid, p_payment_method_code text, p_at timestamptz)
RETURNS TABLE (fee_schedule_id uuid, percent_ppm integer, fixed_minor bigint, fee_vat_ppm integer,
               pass_through_enabled boolean, absorbed_by app.fee_bearer, is_placeholder boolean)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = app, pg_catalog, pg_temp
AS $fn$
  SELECT f.id, f.percent_ppm, f.fixed_minor, f.fee_vat_ppm, f.pass_through_enabled, f.absorbed_by, f.is_placeholder
    FROM app.fee_schedules f
   WHERE f.status = 'approved'
     AND f.payment_method_code = p_payment_method_code
     AND tstzrange(f.effective_from, f.effective_to, '[)') @> p_at
     AND (f.business_id = p_business_id OR f.business_id IS NULL)
     AND app.app_scope() <> 'none'
   ORDER BY (f.business_id IS NULL), f.effective_from DESC
   LIMIT 1
$fn$;

-- 7.4 Authentication lookups that must run before a user scope exists.
CREATE OR REPLACE FUNCTION app.fn_auth_find_login(p_login text)
RETURNS TABLE (user_id uuid, password_hash text, status app.user_status, locked_until timestamptz, mfa_enrolled boolean)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = app, extensions, pg_catalog, pg_temp
AS $fn$
  SELECT u.id, u.password_hash, u.status, u.locked_until, u.mfa_enrolled
    FROM app.users u
   WHERE u.deleted_at IS NULL
     AND (u.email = p_login::extensions.citext OR u.phone_e164 = p_login)
   LIMIT 1
$fn$;

CREATE OR REPLACE FUNCTION app.fn_auth_record_login_attempt(p_user_id uuid, p_success boolean,
                                                            p_lock_threshold integer DEFAULT 10, p_lock_minutes integer DEFAULT 15)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = app, pg_catalog, pg_temp
AS $fn$
BEGIN
  IF p_success THEN
    UPDATE app.users SET failed_login_count = 0, locked_until = NULL, last_login_at = now() WHERE id = p_user_id;
  ELSE
    UPDATE app.users
       SET failed_login_count = failed_login_count + 1,
           locked_until = CASE WHEN failed_login_count + 1 >= p_lock_threshold
                               THEN now() + make_interval(mins => p_lock_minutes) ELSE locked_until END
     WHERE id = p_user_id;
  END IF;
END
$fn$;

-- Resolves an opaque session token (hashed by the caller) and slides the idle timeout (15 min admin, 30 min otherwise).
CREATE OR REPLACE FUNCTION app.fn_auth_resolve_session(p_token_hash bytea, p_surface app.session_surface)
RETURNS TABLE (session_id uuid, user_id uuid, mfa_verified_at timestamptz, support_session_id uuid, absolute_expires_at timestamptz)
LANGUAGE sql VOLATILE SECURITY DEFINER
SET search_path = app, pg_catalog, pg_temp
AS $fn$
  UPDATE app.sessions s
     SET last_seen_at = now(),
         idle_expires_at = least(s.absolute_expires_at,
                                 now() + CASE WHEN s.remember_me THEN interval '30 days'
                                              WHEN s.surface = 'admin' THEN interval '15 minutes'
                                              ELSE interval '30 minutes' END)
   WHERE s.token_hash = p_token_hash
     AND s.surface = p_surface
     AND s.revoked_at IS NULL
     AND s.idle_expires_at > now()
     AND s.absolute_expires_at > now()
  RETURNING s.id, s.user_id, s.mfa_verified_at, s.support_session_id, s.absolute_expires_at
$fn$;

CREATE OR REPLACE FUNCTION app.fn_consume_verification_token(p_token_hash bytea, p_purpose app.token_purpose)
RETURNS TABLE (token_id uuid, user_id uuid, target text, business_id uuid)
LANGUAGE sql VOLATILE SECURITY DEFINER
SET search_path = app, pg_catalog, pg_temp
AS $fn$
  UPDATE app.verification_tokens t
     SET consumed_at = now()
   WHERE t.token_hash = p_token_hash
     AND t.purpose = p_purpose
     AND t.consumed_at IS NULL
     AND t.expires_at > now()
  RETURNING t.id, t.user_id, t.target, t.business_id
$fn$;

-- 7.5 Customer contact details for staff holding customers.view_contact (checked + audited by the API). Returns rows only
--     for a customer who has a booking, order or event registration with the calling business.
CREATE OR REPLACE FUNCTION app.fn_business_customer_contact(p_business_id uuid, p_user_id uuid)
RETURNS TABLE (email extensions.citext, phone_e164 text)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = app, extensions, pg_catalog, pg_temp
AS $fn$
  SELECT u.email, u.phone_e164
    FROM app.users u
   WHERE u.id = p_user_id
     AND app.app_scope() = 'business'
     AND p_business_id = app.app_current_business_id()
     AND (   EXISTS (SELECT 1 FROM app.bookings b WHERE b.business_id = p_business_id AND b.player_user_id = p_user_id)
          OR EXISTS (SELECT 1 FROM app.orders o WHERE o.business_id = p_business_id AND o.user_id = p_user_id)
          OR EXISTS (SELECT 1 FROM app.event_registrations r WHERE r.business_id = p_business_id AND r.user_id = p_user_id))
$fn$;

-- Ownership + execute rights for every SECURITY DEFINER function (including the invariant trigger functions of section 4).
DO $fn$
DECLARE
  f text;
BEGIN
  FOREACH f IN ARRAY ARRAY[
    'app.fn_release_stale_holds(uuid, tstzrange, text)',
    'app.fn_booking_eligibility(uuid, uuid, uuid, text)',
    'app.fn_resolve_commission_agreement(uuid, timestamptz)',
    'app.fn_resolve_fee_schedule(uuid, text, timestamptz)',
    'app.fn_auth_find_login(text)',
    'app.fn_auth_record_login_attempt(uuid, boolean, integer, integer)',
    'app.fn_auth_resolve_session(bytea, app.session_surface)',
    'app.fn_consume_verification_token(bytea, app.token_purpose)',
    'app.fn_business_customer_contact(uuid, uuid)',
    'app.tg_assert_journal_balanced()',
    'app.tg_assert_entry_tenant()',
    'app.tg_assert_booking_slot_invariant()']
  LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO app_definer', f);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', f);
  END LOOP;
  FOREACH f IN ARRAY ARRAY[
    'app.fn_release_stale_holds(uuid, tstzrange, text)',
    'app.fn_booking_eligibility(uuid, uuid, uuid, text)',
    'app.fn_resolve_commission_agreement(uuid, timestamptz)',
    'app.fn_resolve_fee_schedule(uuid, text, timestamptz)',
    'app.fn_auth_find_login(text)',
    'app.fn_auth_record_login_attempt(uuid, boolean, integer, integer)',
    'app.fn_auth_resolve_session(bytea, app.session_surface)',
    'app.fn_consume_verification_token(bytea, app.token_purpose)',
    'app.fn_business_customer_contact(uuid, uuid)']
  LOOP
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO app_rw', f);
  END LOOP;
END
$fn$;

-- =============================================================================
-- 8. VIEWS (security_invoker: the caller's RLS policies apply)
-- =============================================================================

-- Public availability projection: occupancy without occupant identity.
CREATE VIEW app.v_public_court_occupancy WITH (security_invoker = true) AS
  SELECT s.court_id, s.venue_id, s.occupied_range
    FROM app.booking_slots s
   WHERE s.status = 'active';

-- Reporting facts. Each date basis is a separate, explicitly named column (never mixed).
CREATE VIEW reporting.v_booking_facts WITH (security_invoker = true) AS
  SELECT b.id               AS booking_id,
         b.business_id,
         b.venue_id,
         b.court_id,
         b.status,
         b.source,
         b.created_at       AS booking_created_at,   -- booking date
         b.starts_at        AS play_starts_at,       -- play date (UTC)
         b.play_local_date,                          -- play date (venue local)
         b.confirmed_at,
         b.cancelled_at,
         b.completed_at,
         b.currency,
         b.base_minor,
         b.discount_minor,
         b.total_minor,
         b.refunded_minor,
         b.commission_rate_ppm
    FROM app.bookings b;

CREATE VIEW reporting.v_payment_facts WITH (security_invoker = true) AS
  SELECT p.id                  AS payment_id,
         p.business_id,
         p.checkout_id,
         p.status,
         p.payment_method_code,
         p.currency,
         p.amount_minor,
         p.customer_fee_minor,
         p.provider_fee_minor,
         p.refunded_minor,
         p.captured_at         AS payment_captured_at,   -- payment date
         p.provider_settled_at                            -- settlement date
    FROM app.payments p;

CREATE VIEW reporting.v_venue_payable_balances WITH (security_invoker = true) AS
  SELECT e.business_id,
         e.currency,
         sum(CASE e.direction WHEN 'credit' THEN e.amount_minor ELSE -e.amount_minor END) AS balance_minor  -- < 0 = receivable
    FROM app.financial_ledger_entries e
   WHERE e.account_code LIKE 'venue:%'
   GROUP BY e.business_id, e.currency;

-- =============================================================================
-- 9. GRANTS (least privilege; RLS applies on top of every grant)
-- =============================================================================

GRANT USAGE ON SCHEMA app, audit, extensions TO app_rw, app_reporting;
GRANT USAGE ON SCHEMA reporting TO app_reporting;

-- 9.1 Runtime roles: read/write without DELETE or TRUNCATE.
GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA app TO app_rw;

-- 9.2 Append-only tables: no UPDATE for anyone at runtime (the triggers of section 4 also block it).
REVOKE UPDATE ON app.financial_ledger_entries, app.ledger_journals, app.payment_events, app.inventory_movements,
                 app.booking_price_snapshots, app.booking_status_history, app.cancellation_policy_versions, app.consents
  FROM app_rw;

-- 9.3 Hard DELETE only for disposable association/preference rows; everything else is soft-deleted or retained.
GRANT DELETE ON app.favorites, app.notification_preferences, app.push_subscriptions, app.venue_amenities,
                app.business_member_roles, app.role_permissions, app.booking_participants, app.team_members
  TO app_rw;

-- 9.4 Infrastructure tables split by login role (no RLS on these two tables).
REVOKE ALL ON app.webhook_events FROM app_rw;
GRANT SELECT, INSERT ON app.webhook_events TO app_api;             -- ingestion + dedup lookup only
GRANT SELECT, UPDATE ON app.webhook_events TO app_worker;          -- processing status
GRANT DELETE ON app.idempotency_keys, app.outbox_events, app.sessions, app.verification_tokens, app.webhook_events
  TO app_worker;                                                   -- retention.enforce purges expired rows

-- 9.5 Audit schema: parent tables only (partitions are never granted, so direct partition access is impossible).
GRANT SELECT, INSERT ON audit.audit_logs, audit.security_events TO app_rw;

-- 9.6 Helper functions.
GRANT EXECUTE ON FUNCTION app.app_scope(), app.app_current_business_id(), app.app_current_user_id(), app.uuidv7()
  TO app_rw, app_reporting, app_definer;

-- 9.7 app_definer: exactly what the section 7 functions and section 4 invariant triggers need.
GRANT SELECT ON app.bookings, app.booking_slots, app.booking_holds, app.financial_ledger_entries, app.ledger_journals,
                app.users, app.sessions, app.verification_tokens, app.venue_user_restrictions, app.commission_agreements,
                app.fee_schedules, app.business_members, app.orders, app.event_registrations
  TO app_definer;
GRANT UPDATE ON app.bookings, app.booking_slots, app.booking_holds, app.sessions, app.verification_tokens TO app_definer;
GRANT UPDATE (failed_login_count, locked_until, last_login_at) ON app.users TO app_definer;
GRANT INSERT ON app.booking_status_history, app.outbox_events, audit.audit_logs TO app_definer;

-- 9.8 Reporting role (read replica). Views are security_invoker, so tenant policies still apply per app.scope.
GRANT SELECT ON ALL TABLES IN SCHEMA reporting TO app_reporting;
GRANT SELECT ON app.businesses, app.venues, app.courts, app.bookings, app.booking_slots, app.checkouts, app.checkout_items,
                app.payments, app.refunds, app.disputes, app.commissions, app.settlements, app.settlement_lines, app.payouts,
                app.ledger_accounts, app.ledger_journals, app.financial_ledger_entries, app.events, app.event_registrations,
                app.orders, app.order_items, app.products
  TO app_reporting;
GRANT SELECT ON audit.audit_logs TO app_reporting;

-- 9.9 Future objects created by the migrator in schema app. Migrations adding append-only tables must REVOKE UPDATE.
ALTER DEFAULT PRIVILEGES FOR ROLE courtko_migrator IN SCHEMA app GRANT SELECT, INSERT, UPDATE ON TABLES TO app_rw;
ALTER DEFAULT PRIVILEGES FOR ROLE courtko_migrator IN SCHEMA app REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;

RESET ROLE;
COMMIT;

